W_EXTRA.push({"id":"LDB","title":"이대봉전","unit":"권","persons":{"장애황":{"name":"장애황","alias":["애황","장해운","해운","장 원수","연왕","장후","충렬왕후","장 부인"],"sex":"F","note":"여성 영웅. 남장하여 장원급제, 대원수로 남선우·남만을 평정, 상소로 정체를 밝히고 대봉과 혼인한 뒤 재출전"},"이대봉":{"name":"이대봉","alias":["대봉","이 원수","초왕"],"sex":"M","note":"정혼자이자 남성 영웅. 백운암에서 수학, 능주에서 천자를 구하고 흉노를 멸함, 초왕"},"이익":{"name":"이익","alias":["이 시랑","시랑","우승상","태왕","태상왕","친국문후"],"sex":"M","note":"대봉의 부친. 왕희를 탄핵하다 귀양 길에 수장될 뻔하고 무인도에서 8년을 지냄"},"양씨":{"name":"양씨","alias":["이 시랑 부인","명자","정렬왕비","태후"],"sex":"F","note":"대봉의 모친. 흉노의 난에 피란하여 봉명암 여승(법명 명자)이 됨"},"장화":{"name":"장화","alias":["장 한림","한림"],"sex":"M","note":"애황의 부친. 대봉 부자의 귀양에 분해하다 병사"},"소씨":{"name":"소씨","alias":["장 한림 부인"],"sex":"F","note":"애황의 모친. 장화와 같은 날 세상을 떠남"},"난향":{"name":"난향","alias":["애원","후궁"],"sex":"F","note":"애황의 시비. 애황 대신 혼행 가마에 오르고 집과 제사를 지킴, 뒤에 여승(법명 애원), 끝에 초왕의 후궁"},"왕희":{"name":"왕희","alias":["우승상","승상"],"sex":"M","note":"간신. 이익을 모함하고 사공을 매수해 부자를 수장시키려 함, 천자에게 항서를 권함"},"왕석연":{"name":"왕석연","alias":["석연","왕 공자"],"sex":"M","note":"왕희의 아들. 애황을 밤중에 억지로 데려가려 함"},"진태열":{"name":"진태열","alias":["병부상서","병부시랑","군량관"],"sex":"M","note":"왕희 편 신하. 이익을 죽이라 아뢰고 해운을 시기, 해운 휘하 군량관이 됨"},"진여":{"name":"진여","alias":[],"sex":"M","note":"진태열의 사촌 병부시랑. 항서를 재촉한 죄로 귀양"},"유원진":{"name":"유원진","alias":["좌승상"],"sex":"M","note":"진태열과 함께 해운을 시기하여 출정을 부추김"},"장준":{"name":"장준","alias":[],"sex":"M","note":"장화의 육촌. 왕희의 중매를 서고 늑혼을 꾸밈"},"진씨":{"name":"진씨","alias":[],"sex":"F","note":"장준의 아내. 혼인을 권하러 애황에게 감"},"백운암 노승":{"name":"백운암 노승","alias":["노승","세존","살아 있는 부처","화산 도사"],"sex":"M","note":"천축국 금화산 백운암의 노승. 이익의 시주를 받고 대봉을 가르침, 마고선녀를 애황에게 보냄"},"마고선녀":{"name":"마고선녀","alias":["늙은 여인","부인"],"sex":"F","note":"애황의 스승. 천태산에 있다가 세존의 명으로 여남 산중에서 애황을 가르침"},"산중 노인":{"name":"산중 노인","alias":[],"sex":"M","note":"애황의 꿈에 나타나 스승의 집을 가르쳐 줌"},"호씨":{"name":"호씨","alias":["최 어사 부인"],"sex":"F","note":"최 어사의 부인. 해운을 초당에 머물게 하고 딸과 혼인을 약속함"},"최 소저":{"name":"최 소저","alias":["최씨","최 부인"],"sex":"F","note":"호씨의 딸. 해운과 약혼했다가 초왕 대봉의 처가 됨"},"천자":{"name":"천자","alias":["효종 황제","황제","황상"],"sex":"M","note":"명 천자. 왕희를 믿다가 흉노에게 항복 직전 대봉에게 구출됨"},"서해 용왕":{"name":"서해 용왕","alias":["용왕"],"sex":"M","note":"동자를 보내 이익 부자를 구하고, 뒤에 대봉을 대사마 대장군으로 삼아 남해왕을 침"},"두 동자":{"name":"두 동자","alias":["동자"],"sex":"M","note":"서해 용왕의 사자. 이익과 대봉을 각각 건짐"},"남해왕":{"name":"남해왕","alias":["남해 용왕"],"sex":"M","note":"서해 용궁을 침범했다가 대봉에게 항복"},"남선우":{"name":"남선우","alias":["선우"],"sex":"M","note":"남방 외적. 애황에게 패해 항복했다가 재침하여 애황에게 죽음"},"촉담":{"name":"촉담","alias":[],"sex":"M","note":"남선우의 선봉장. 애황에게 베임"},"거란퇴":{"name":"거란퇴","alias":[],"sex":"M","note":"남선우의 선봉장. 애황에게 베임"},"골통":{"name":"골통","alias":[],"sex":"M","note":"재침한 남선우의 선봉장. 애황에게 베임"},"북흉노":{"name":"북흉노","alias":["흉노","호왕"],"sex":"M","note":"북방 외적. 황성을 빼앗고 스스로 천자라 일컬음, 서릉도에서 대봉에게 죽음"},"묵특":{"name":"묵특","alias":[],"sex":"M","note":"흉노의 장수. 능주성을 깨뜨리다 대봉에게 베임(재침 때 다시 이름이 나옴)"},"통달":{"name":"통달","alias":[],"sex":"M","note":"흉노의 장수. 곽태효를 사로잡음, 대봉에게 베임"},"이릉":{"name":"이릉","alias":[],"sex":"M","note":"한나라 장수의 혼령. 대봉에게 월각 투구와 용린갑을 줌"},"관운장":{"name":"관운장","alias":["한수정후"],"sex":"M","note":"관우의 혼령. 화룡도에서 대봉에게 청룡도를 줌"},"곽태효":{"name":"곽태효","alias":[],"sex":"M","note":"공부상서. 흉노를 막으러 갔다가 사로잡힘"},"한능":{"name":"한능","alias":[],"sex":"M","note":"애황 휘하 선봉장"},"장연":{"name":"장연","alias":[],"sex":"M","note":"해남 절도사. 능주에서 천자를 호위, 대봉의 중군장"},"화양공주":{"name":"화양공주","alias":["숙렬왕비"],"sex":"F","note":"천자의 딸. 초왕의 비"},"화평공주":{"name":"화평공주","alias":["전안왕비"],"sex":"F","note":"천자의 딸. 처음 연왕(애황)의 비로 정해졌다가 초왕의 비가 됨"},"출전":{"name":"출전","alias":[],"sex":"M","note":"애황이 진중에서 낳은 아들. 천자가 이름을 지어 줌"}},"places":{},"paras":[{"c":1,"sub":"리ᄃᆡ봉젼상(李大鳳傳上)","t":"대명(大明) 성화(成化) 연간, 효종 황제가 즉위한 지 3년째 되던 때였다. 이때 기주 땅 모란동에 한 명망 있는 벼슬아치가 있었는데, 성은 이(李)요 이름은 익이었다. 좌승상 영준의 증손이요 이부상서 덕연의 아들이었다. 대대로 이름난 가문의 자손으로 일찍 벼슬길에 올라 이부시랑의 자리에 있으니 명망이 조정에 떨쳤다. 다만 슬하에 피붙이 하나 없어 조상의 제사가 끊기게 되었으므로, 부귀도 생각이 없고 영화로운 지위에도 뜻이 없어 하늘을 우러러 탄식하였다. 부인 양씨도 자식 없음을 스스로 한탄하며 눈물로 세월을 보내다가 상공 앞에 여쭈었다. \"불효 삼천 가지 가운데 뒤를 잇지 못하는 것이 가장 크다 하였으니, 상공께 자식이 없는 것은 모두 첩의 죄입니다.\" 이렇게 서로 서러워하던 중, 하루는 사랑채에 한 늙은 중이 검은 장삼을 입고 아홉 마디 대지팡이를 짚고 팔각 두건을 쓰고 들어와 상공 앞에 합장하고 절하였다. 시랑도 답례하고 물었다. \"스님은 어느 절에 계시며 누추한 곳에 어찌 오셨습니까?\" 노승이 대답하였다. \"소승은 천축국 금화산 백운암에 있는데, 절이 허물어져 부처님이 비바람을 피하지 못하시므로 고쳐 짓고자 시주 책을 가지고 사방팔방을 두루 다니다가 상공 댁에 왔습니다. 시주하여 주십시오.\"","sp":[[18,23,"P","천자"],[95,98,"P","유원진"],[154,156,"P","이익"],[257,259,"P","마고선녀"],[260,262,"P","양씨"],[460,462,"P","이익"],[507,509,"P","백운암 노승"]]},{"c":1,"sub":"","t":"시랑이 말하였다. \"절을 고쳐 지으려면 재물이 얼마나 있어야 다시 세울 수 있겠습니까?\" 노승이 대답하였다. \"재물에 많고 적음이 있겠습니까? 상공의 뜻에 달렸습니다.\" 시랑이 말하였다. \"나는 지은 죄가 무거워 나이가 반백이 되도록 피붙이 하나 없어, 앞길을 이끌고 뒤를 이을 자식이 없습니다. 죽은 뒤에 백골인들 누가 거두며, 조상의 제사가 끊기게 되니 죽어 황천에 돌아간들 조상을 어찌 대하며 무슨 면목으로 부모를 대하겠습니까? 조상께는 죄인이요 저승에서는 악귀가 될 것입니다. 내 재물을 두어 누구에게 전하겠습니까? 부처님 앞에 시주하여 다음 생의 길이나 닦으렵니다.\" 하고 시주 책을 받들어 황금 오백 냥과 흰쌀 삼백 석, 황촉 삼천 자루를 시주하였다. 노승이 시주 책을 받아 들고 머리를 조아려 사례하였다. \"소승이 멀리 와서 적지 않은 재물을 얻어 가니 부처님을 편히 모실 수 있게 되었습니다. 은혜는 백골이 되어도 잊기 어렵습니다. 상공은 자식 없음을 한탄하지 마십시오.\"","sp":[[0,2,"P","이익"],[50,52,"P","백운암 노승"],[95,97,"P","이익"],[371,373,"P","백운암 노승"]]},{"c":1,"sub":"","t":"하고는 문득 간 데가 없었다. 시랑이 그제야 부처인 줄 알고 마루에서 내려와 공중을 향해 사례하였다. \"원컨대 부처님은 자식 하나를 점지해 주십시오.\" 하며 수없이 절하고, 부인 양씨와 이 일을 이야기하며 다행히 자식을 점지받을까 바랐다. 과연 그달부터 태기가 있어 열 달이 차자, 하루는 몸이 고단하여 잠자리에 졸고 있었는데 꿈결에 하늘에서 봉황 한 쌍이 내려와, 봉(鳳)은 부인의 품으로 날아들고 황(凰)은 장미동 장 한림의 집으로 갔다. 깨어 보니 집안에 향기가 가득하고 오색구름이 영롱하였다. 정신이 혼미한 가운데 아이를 낳으니 활달하고 빼어난 사내아이였다. 시랑이 크게 기뻐 아이를 살펴보니 콧마루가 우뚝하고 봉황의 눈이며 목소리가 봉황의 소리 같았다. 부인이 꿈을 생각하여 이름을 대봉(大鳳)이라 하였다.","sp":[[17,19,"P","이익"],[97,99,"P","마고선녀"],[100,102,"P","양씨"],[211,213,"P","마고선녀"],[234,238,"P","장화"],[317,319,"P","이익"],[371,373,"P","마고선녀"],[387,389,"P","이대봉"]]},{"c":1,"sub":"","t":"이때 기주 장미동에 장화라는 사람이 있었다. 일찍 벼슬길에 올라 한림학사 자리에 있으니 명망이 조정에 떨치고 부귀가 지극하였으나, 나이 사십이 되도록 슬하에 아들딸 하나 없어 부인 소씨와 함께 날마다 서러워하였다. 그러다 부인 소씨가 뜻밖에 태기가 있어 열 달이 찼는데, 하루는 문득 몸이 고단하여 이불에 기대어 졸고 있었다. 꿈결에 하늘에서 봉황 한 쌍이 내려와 봉은 모란동 이 시랑의 집으로 가고 황은 부인의 품 안으로 날아들었다. 이른바 봉이 나면 황이 나고, 장수가 나면 용마가 난다는 격이었다. 또 향내가 방에 가득하고 채색 구름이 어리었는데, 혼미한 가운데 아이를 낳으니 바로 애황이었다. 부인이 한림에게 꿈 이야기를 하자 한림이 크게 기뻐하여 이름을 애황이라 하였다. 그리고 곧 모란동 이 시랑 집에 가서 보니 이 시랑 댁 부인도 또한 해산하였으므로 속으로 은근히 기뻐하며, 시랑을 청하여 이야기를 나누었다.","sp":[[11,13,"P","장화"],[36,38,"P","장화"],[98,100,"P","마고선녀"],[101,103,"P","소씨"],[124,126,"P","마고선녀"],[127,129,"P","소씨"],[211,215,"P","이익"],[227,229,"P","마고선녀"],[329,331,"P","장애황"],[336,338,"P","마고선녀"],[340,342,"P","장화"],[355,357,"P","장화"],[371,373,"P","장애황"],[391,395,"P","이익"],[405,409,"P","이익"],[412,414,"P","마고선녀"],[441,443,"P","이익"]]},{"c":1,"sub":"","t":"한림이 물었다. \"시랑은 어느 때 해산하셨습니까?\" 시랑이 대답하였다. \"나는 어제 사시(巳時)에 사내아이를 얻었습니다. 한림은 나와 어릴 적부터의 벗으로, 함께 과거에 올라 부귀와 영화를 누리며 나라를 받들어 명망이 높았으나 자식 없음을 한으로 여겼지요. 나는 다행히 자식을 얻었지만 한림은 지금까지 아들딸 하나 없으니 몹시 안타깝습니다.\" 한림이 대답하였다. \"나도 어제 사시에 딸 하나를 낳았으니 참으로 다행입니다. 우리가 서로 정이 각별한 가운데 이것 또한 기이한 일입니다.\" 한림이 자기 부인의 꿈 이야기를 하니 시랑이 크게 기뻐하여 곧 안채에 들어가 장 한림 부인의 꿈 이야기를 양씨 부인에게 전하였다. 부인도 자기 꿈을 말하는데, 두 부인의 꿈이 서로 같았다. 시랑이 사랑채로 나와 한림과 즐겁게 이야기를 나누며 말하였다. \"이는 반드시 상제께서 이 인연을 맺어 보내신 것입니다.","sp":[[0,2,"P","장화"],[10,12,"P","이익"],[29,31,"P","이익"],[68,70,"P","장화"],[160,162,"P","장화"],[192,194,"P","장화"],[271,273,"P","장화"],[278,280,"P","마고선녀"],[292,294,"P","이익"],[314,321,"P","소씨"],[330,332,"P","양씨"],[333,335,"P","마고선녀"],[344,346,"P","마고선녀"],[362,364,"P","마고선녀"],[377,379,"P","이익"],[389,391,"P","장화"]]},{"c":1,"sub":"","t":"태어난 해와 달과 날과 시가 조금도 틀림이 없으니, 두 아이가 자라거든 봉황으로 짝을 지어 원앙의 즐거움을 이루게 하고, 우리도 서로 말년의 재미를 봅시다.\" 하고 종일토록 함께 즐기며 술을 마시고 배불리 먹었다. 해가 서산에 지자 한림이 집으로 돌아와, 이 시랑 부인 양씨의 꿈 이야기를 하고 시랑의 아들 대봉을 사위로 맞기로 혼약한 일을 말하니 부인도 매우 기뻐하였다. 이때 시랑이 안채에 들어가 \"장 한림의 딸 애황을 맞아 아들 대봉의 짝을 정하였으니 참으로 우리 집의 다행입니다.\" 하니 부인 양씨도 매우 기뻐하였다. 두 집안이 서로 봉과 황이 자라기를 기다려 혼례를 치르기를 바랐다.","sp":[[130,132,"P","장화"],[143,150,"P","양씨"],[151,153,"P","양씨"],[165,167,"P","이익"],[172,174,"P","이대봉"],[195,197,"P","마고선녀"],[212,214,"P","이익"],[225,229,"P","장화"],[233,235,"P","장애황"],[243,245,"P","이대봉"],[277,279,"P","마고선녀"],[280,282,"P","양씨"]]},{"c":1,"sub":"","t":"세월이 물 흐르듯 흘러 대봉의 나이가 열세 살이 되었다. 골격이 크고 늠름한 풍채와 활달한 거동은 당시에 짝할 이가 없었으며, 빼어난 기상의 호걸로서 진정 세상에 드문 사내였다. 시서(詩書)와 백가(百家)의 글을 모르는 것이 없고, 육도삼략(六韜三略)과 손자·오자의 병서에 마음을 기울이니, 총명과 지혜가 관중과 악의보다 나았다. 하루는 시랑이 대봉이 너무 일찍 영악해지는 것을 걱정하여 크게 꾸짖었다. \"성현의 글이 수없이 많은데 너는 어찌하여 태평성대에 귀신도 칭찬하지 않을 병서에 힘을 쏟느냐?\" 대봉이 아뢰었다. \"옛날 황제 헌원씨는 만고의 영웅이었으나 치우의 난을 만났고, 요임금 도당씨는 만고의 성현이었으나 사흉(四凶)의 변을 당하였습니다. 태평이 어찌 오래가리라 믿겠습니까? 대장부가 세상에 났으면 시서와 백가의 글, 육도삼략을 마음속에 통달하여 과거에 올라 요순 같은 임금을 섬기다가, 나라의 운수가 불행하여 난세를 당하면 허리에 대장의 절월(節鉞)을 띠고 황금 인끈을 비껴 차고, 머리에는 백금 투구를 쓰고 몸에는 갑옷을 입고, 오른손에 보검을 잡고 왼손에 지휘 깃발을 들고, 용과 봉황을 그린 깃발과 흰 깃대 장식, 누런 도끼, 긴 창과 칼을 늘어세우고 대군을 몰아 싸움터에 나아가 반적을 쓸어 없애고,","sp":[[13,15,"P","이대봉"],[189,191,"P","이익"],[193,195,"P","이대봉"],[281,283,"P","이대봉"],[295,297,"P","천자"],[420,422,"P","통달"]]},{"c":1,"sub":"","t":"사해를 평정하여 공을 역사에 올리고 기린각에 이름을 새기며, 나라의 충신이 되어 많은 녹봉을 누린다면 선왕의 덕택과 부모의 은덕을 알아 평생 부귀를 누릴 것입니다. 어찌 책만 살피며 유정한 세월을 무정하게 보내겠습니까?\" 하니 시랑이 크게 기뻐하며 칭찬하였다. \"네 말이 옛사람을 본받기에 넉넉하구나. 나 같은 사람은 조정에 몸을 두어 그저 자리만 차지하고 녹을 먹을 뿐이로다.\" 하고 사랑함을 이루 다 말할 수 없었다.","sp":[[127,129,"P","이익"]]},{"c":1,"sub":"","t":"이때 황제가 어리고 약하여 법령이 해이한 가운데, 우승상 왕희가 국권을 잡고 나랏일을 처결하였다. 조정의 백관과 각 도의 방백과 수령이 모두 왕희의 무리가 되니, 나라의 권세가 그의 손바닥 안에 놓이고 만인의 생사가 그의 손끝에 달렸다. 권세가 막중함이 한나라의 왕망과 진나라의 왕돈보다 더하였다. 군자는 참소하여 멀리하고 소인은 아첨으로 무리를 이루니 나랏일이 점점 어지러워졌다. 나랏일이 이러한데도 황제는 알지 못하고 다만 소인 왕희에게 천하의 큰일을 모두 맡겨","sp":[[3,5,"P","천자"],[28,31,"P","이익"],[32,34,"P","왕희"],[79,81,"P","왕희"],[225,227,"P","천자"],[242,244,"P","왕희"]]},{"c":1,"sub":"","t":"처결하게 하니, 슬프다, 대명의 사직이 아침저녁으로 위태로웠다. 이때 시랑 이익이 나랏일이 어지러운 것을 보고 상소하였다. \"조정의 형세를 살피니 어찌 한심하지 않겠습니까? 군자를 쓰시면 소인은 스스로 멀어질 것입니다. 군자를 가까이하고 소인을 멀리함은 나라가 흥하는 근본이요, 군자를 멀리하고 소인을 가까이함은 나라가 망하는 근본입니다. 이제 폐하께서는 궁궐 깊이 계시어 나랏일이 어지러운 것을 알지 못하시고, 승상 왕희는 나라의 간악한 소인으로서 폐하의 성덕을 가리고 아첨으로 폐하의 총명을 가렸는데도 폐하께서는 지금까지 깨닫지 못하시니 애달픕니다. 지금 조정이 거의 모두 왕희와 더불어 모반하기에 이르렀으니, 폐하께서는 살피시어 먼저 신을 베시고 그다음 왕희를 급히 베어 반적의 흉계를 깨뜨리소서.","sp":[[39,41,"P","이익"],[42,44,"P","이익"],[231,233,"P","왕희"],[234,236,"P","왕희"],[323,325,"P","왕희"],[369,371,"P","왕희"]]},{"c":1,"sub":"","t":"진나라의 조고와 송나라의 진회는 소인으로서 많은 녹봉을 받고도 나라의 은혜를 알지 못하고 나랏일을 어지럽혔습니다. 예로부터 소인에게 나라의 녹을 주는 것은 마땅하지 않습니다.\" 하였다. 이날 황제가 상소를 보신 뒤 승상 왕희를 돌아보시니, 병부상서 진태열이 황제께 여쭈었다. \"이부시랑 이익은 한낱 하찮은 신하로서 조정을 비방하고 대신을 모함하니 죽어도 죄가 남습니다. 한나라의 곽광은 권세가 막중하였으나 선제의 충신이었고, 진나라의 왕준은 강동의 인물로서 지혜가 높았습니다. 엎드려 바라건대 폐하께서는 살피시어 터무니없는 죄를 다스려 시랑 이익을 베어 소인을 경계하소서.\"[?]","sp":[[107,109,"P","천자"],[120,122,"P","왕희"],[123,125,"P","왕희"],[134,138,"P","진태열"],[139,142,"P","진태열"],[144,146,"P","천자"],[157,159,"P","이익"],[160,162,"P","이익"],[300,302,"P","이익"],[303,305,"P","이익"]]},{"c":1,"sub":"","t":"황제가 이 말을 들으시고 옳게 여겨 이익의 벼슬을 빼앗아 삼만 리 무인 절도에 귀양 보내 가두게 하시고, 그 친족은 벼슬을 거두어 평민으로 만들고, 그 아들 대봉은 오천 리 백설도로 귀양 보내라 하셨다. 이때 이 시랑 부자가 귀양지로 가려 할 때 어찌 통분하지 않겠는가. 승상부에 들어가 눈을 부릅뜨고 크게 소리쳤다. \"나라의 운수가 불행하여 소인이 조정에 가득하구나. 한나라 황실이 미약해지니 동탁이 난을 일으키고, 왕망이 정권을 쥐니 충신이 죽는구나. 승상 왕희는 한나라 역적 왕망의 자손이라, 간악함을 대대로 물려받아 위로는 황상을 속이고 아래로는 충신을 물리치며 밖으로는 소인과 무리를 지어 나랏일을 어지럽히기에, 내가 바른말로 간하였더니 간사한 소인의 참소를 만나 수만 리 절도로 가게 되었다. 그러나 내 아들 대봉은 아직 어린 나이에 무슨 죄로 수천 리 백설도로 귀양을 보내느냐?\" 하며 땅을 치고 분해하니, 왕희가 크게 노하여 책상을 치며 소리를 높였다. \"황명이 이러하거늘 무슨 잔말을 하느냐? 네가 만일 잔말을 하다가는","sp":[[0,2,"P","천자"],[20,22,"P","이익"],[88,90,"P","이대봉"],[117,121,"P","이익"],[152,154,"P","왕희"],[255,257,"P","왕희"],[258,260,"P","왕희"],[297,299,"P","천자"],[403,405,"P","이대봉"],[459,461,"P","왕희"]]},{"c":1,"sub":"","t":"죽음을 면치 못할 것이니 빨리 귀양지로 가라.\" 하며 호송하는 관원을 호령하였다. 시랑이 하릴없이 귀양지로 떠나려고 집으로 돌아오니, 온 집안이 망극하여 울음소리가 진동하였다. 날짐승과 길짐승도 모두 서러워하는 듯하고 해와 달도 빛을 잃었으니, 사람이야 누가 서러워하지 않겠는가. 이날 시랑 부자가 귀양지로 떠날 때 시랑이 부인의 손을 잡고 하늘을 우러러 통곡하였다. \"이 몸은 하늘이 미워하고 귀신이 해코지하여, 나라에 바른말로 간하다가 소인 놈의 참소를 만나 죽을 땅으로 가지만, 우리 대봉은 무슨 죄이며, 부인은 무슨 죄로 평민이 되어 남편과 자식을 이별하며, 친척은 무슨 죄로 하루아침에 평민이 되었는가.\" 하고 소리 높여 크게 우니, 그 부인의 애끊는 울음은 붓 하나로 다 적기 어려웠다. 서로 붙들고 통곡하며 부인이 말하였다. \"우리 대봉은 아비의 죄 때문에 오천 리 백설도에 갇히게 되었으니, 하늘과 땅도 무심하고 귀신도 밝지 못하다.","sp":[[46,48,"P","이익"],[160,162,"P","이익"],[177,179,"P","이익"],[181,183,"P","마고선녀"],[274,276,"P","이대봉"],[286,288,"P","마고선녀"],[362,364,"P","마고선녀"],[403,405,"P","마고선녀"],[417,419,"P","이대봉"]]},{"c":1,"sub":"","t":"넓디넓은 천지간에 이익같이 야속하고 불쌍한 팔자를 가진 사람이 또 있으랴. 대봉아, 만 리 귀양지로 떠나니 다시 보기를 바라겠느냐. 만 리 변방 사람 없는 곳에서 어린 네가 어찌 살며, 삼만 리 절도에 있는 너의 아버지를 난들 어찌 찾겠느냐. 죽은 혼백이나 둥둥 떠서 부자가 서로 만나겠구나.\" 대봉이 눈물을 흘리며 어머니를 위로하였다. \"어머니 신세를 생각하면 천지가 아득하고 해와 달이 빛을 잃은 듯하니, 가련하고 원통함을 어찌 다 말로 하겠습니까. 그러나 죽을 땅으로 가시는 아버지의 사정과 같겠습니까. 우리 부자가 귀양지로 떠나니, 다행히 살아 돌아오면 어머니 얼굴을 다시 뵙겠지만 죽으면 어느 때에 다시 만나 뵙겠습니까. 역적 왕희와 소인 진태열을 죽이지 못하고 도리어 해를 입어 귀양지로 가지만, 나라의 사직이 아침저녁에 달려 있습니다. 다행히 살아나면 칼을 잡고 우리 원수 왕희와 진태열 두 놈을 사로잡아 앞뒤 죄목을 물은 뒤에 배를 갈라 간을 꺼내 폐하께 아뢰고, 우리 아버지의 충혼당에 제사를 지내겠습니다.\" 이렇듯 분해하며 통곡하니 풀과 나무, 날짐승과 길짐승도 모두","sp":[[10,12,"P","이익"],[42,44,"P","이대봉"],[165,167,"P","이대봉"],[356,358,"P","왕희"],[363,366,"P","진태열"],[440,442,"P","왕희"],[444,447,"P","진태열"]]},{"c":1,"sub":"","t":"눈물을 흘리는 듯하였다. 서로 손을 잡고 차마 이별하지 못하는 그 가련하고 슬픈 모습은 차마 볼 수가 없었다. 이때 호송 관원이 길을 재촉하니 사공이 배를 대었다. 시랑과 대봉이 부인과 애달프게 이별하고 시랑 부자가 배에 오르니, 백설도는 절도로 가는 길에 있는 곳이라 하였다. 흰 구름은 흩어지고 순풍이 일어나 배가 화살같이 빨랐다. 이때 승상 왕희가 사공을 불러 큰 상을 주고 시랑 부자를 묶어 풍랑 속에 던지라고 약속해 두었다. 시랑 부자야 이런 흉계를 알 수 있었겠는가. 만경창파 깊은 물에 물결이 도도하고, 기나긴 가을밤에 강 한가운데도 적막한데, 십 리 모래사장에서 놀던 갈매기는 동남쪽으로 날아가니 고향 소식을 묻고 싶구나. 강물은 잔잔하고 달빛은 삼경인데, 배 안에 앉은 마음은 고향 생각이 쌓여 잠들 길이 아득하다. 푸른 하늘에 뜬 기러기와 두견새 소리가 어우러져 나그네의 근심을 돋우니, 객창의 깊은 밤에 들려오는 저 원숭이 울음은 하늘 끝을 떠도는 나그네의 신세로다.[?]","sp":[[92,94,"P","이익"],[96,98,"P","이대봉"],[100,102,"P","마고선녀"],[114,116,"P","이익"],[191,193,"P","왕희"],[194,196,"P","왕희"],[213,215,"P","이익"],[243,245,"P","이익"]]},{"c":1,"sub":"","t":"이럭저럭 여러 날 만에 한곳에 이르니 사방에 사람 하나 없이 적막하고 아득한 바다뿐이어서 어느 땅인지 알 수 없었다. 물 한가운데에 이르자 사공 십여 명이 달려들어 시랑 부자를 묶어 바닷속에 던지려 하였다. 시랑이 크게 노하여 사공을 꾸짖었다. \"내가 황명을 받아 귀양지로 가는데 너희가 무슨 까닭으로 이렇듯 핍박하느냐?\" 사공들이 대답하였다. \"우리 사정은 너희 부자가 알 바가 아니다.\" 하고 시랑과 대봉을 바닷속에 던지려 하자 시랑이 말하였다. \"우리 부자가 귀양지로 가는 것만도 억울한데, 너희가 우리 부자를 해치려 한다면 묶는 것은 무슨 일이냐. 죽는 것도 원통한데 팔다리를 묶으면 혼백인들 어찌 받아들여지겠느냐. 굴원과 오자서의 충혼을 어찌 찾아가겠느냐.\" 하자 그중 한 늙은 사공이 여러 사공을 달래며 말하였다.","sp":[[92,94,"P","이익"],[116,118,"P","이익"],[222,224,"P","이익"],[226,228,"P","이대봉"],[242,244,"P","이익"]]},{"c":1,"sub":"","t":"\"옛말에 나랏일에도 사사로운 정이 있고 난리 중에도 체면이 있다 하였으니, 시랑 부자가 억울하다는 것을 알겠다. 묶은 것을 풀어 주어도 물속에 넣으면 몸에 날개가 없으니 어찌 살기를 바라겠느냐.\" 하며 묶은 것을 풀고 시랑을 먼저 풍랑 속에 밀어 넣었다. 해와 달이 빛을 잃고 강산도 서러워하며 풀과 나무, 날짐승과 길짐승도 눈물을 머금으니, 하물며 사람이야 말해 무엇 하랴마는 무지한 뱃사람들은 짐승만도 못하였다. 이때 대봉이 아버지가 물에 빠지는 것을 보고 천지가 아득하여 정신이 혼미하였다. 겨우 정신을 차려 사공을 크게 꾸짖었다. \"살아서는 사람이요 죽어서는 귀신이다. 삼강(三江)의 깊은 물은 굴원의 충혼이요, 삼강의 찬 물결은 오자서의 정령이다. 예로부터 충신과 열사 가운데 물속의 외로운 넋이 된 이가 많으니, 하물며 나같이 보잘것없는 목숨이야 죽기를 아까워하랴마는, 궁중이 깊고 깊어 간신이 조정에 가득하여 나랏일을 제멋대로 하니 충신은 멀리 귀양 가고 소인은 때를 만났도다.","sp":[[42,44,"P","이익"],[122,124,"P","이익"],[236,238,"P","이대봉"]]},{"c":1,"sub":"","t":"백옥같이 죄 없는 우리 부자가 바닷속의 외로운 넋이 되어, 굴원의 충혼을 만나고 오자서를 반겨 보리라. 우리 임금 만세 뒤에 충혼으로 모시어 위엄을 삼고, 나의 아버지의 백옥 같은 무죄와 대봉의 어린 혼백이 원통함을 풀어 줄 증인으로 삼으리라. 우리 부자가 죄 없음은 푸른 하늘도 알고 귀신들도 알 것이다. 대봉 부자의 귀한 몸이 물고기 배 속에 장사 지내니 굴원과 같도다. 대명 천지에 대봉의 목숨이 하늘에 달렸지 어찌 너희에게 달렸겠느냐. 내 스스로 죽을지언정 너희에게 살려 달라고 빌겠느냐.\" 크게 한 번 소리치자 목에서 피를 토하여 바닷물을 물들였다. \"아버지가 이미 물속의 외로운 넋이 되었으니 나도 또한 죽으리라.\" 하고, 만경창파 깊은 물에 풍랑이 요란한데 열세 살 어린 대봉이, 물속의 외로운 넋이 되니 가련하다, 하늘을 우러러 아버지를 부르며 풍덩실 뛰어들었다. 이때 사공들은 배를 돌려 황성으로 올라가 이 사연을 왕희에게 아뢰니 왕희가 크게 기뻐하였다.[?]","sp":[[105,107,"P","이대봉"],[172,174,"P","이대봉"],[217,219,"P","이대봉"],[383,385,"P","이대봉"],[465,467,"P","왕희"],[474,476,"P","왕희"]]},{"c":1,"sub":"","t":"이때 한림 장화는 애황의 혼사를 이루지 못하고 대봉 부자가 귀양 가는 것을 보고 분기가 하늘을 찔러 울음을 참지 못하더니, 이로 말미암아 병이 들어 자리에 눕고 일어나지 못하였다. 이미 세상에 머물지 못할 줄을 알고 왼손으로 부인의 손을 잡고 오른손으로 애황의 손을 잡고 눈물을 흘리며 말하였다. \"사람의 목숨은 하늘에 달려 어길 길이 없으니 나는 황천의 나그네가 되어도 제 명대로 죽는 것이지만, 시랑 부자는 물속의 외로운 넋이 될 것이니 가련하고 원통하구나. 딸아이의 일생이 더욱 가련하고 한심하다. 애황이 사내였더라면 황천에 돌아간 아비의 원통한 분을 풀어 줄 것을, 네 몸이 여자이니 내 가슴에 맺힌 분한 것이 어느 때에 씻기겠느냐.\" 하며 부인에게 당부하였다. \"딸아이를 생각하여 선영을 받들고 매사를 잘 살펴 딸아이를 잘 이끌어 조상을 욕되게 하지 마오. 애황아, 내가 눈을 어찌 감고 가랴.\" 손을 잡고 눈물을 흘리다가 그대로 세상을 떠났다. 부인 소씨도 정신이 아득하여 목숨이 경각에 달렸다. \"애황아, 네 신세의 박명함이 너무도 심하구나.\"","sp":[[3,5,"P","장화"],[6,8,"P","장화"],[10,12,"P","장애황"],[26,28,"P","이대봉"],[126,128,"P","마고선녀"],[142,144,"P","장애황"],[223,225,"P","이익"],[282,284,"P","장애황"],[363,365,"P","마고선녀"],[429,431,"P","장애황"],[479,481,"P","마고선녀"],[482,484,"P","소씨"],[509,511,"P","장애황"]]},{"c":1,"sub":"","t":"하시며 그대로 세상을 떠나시니, 불쌍하다 애황 소저여. 하루 사이에 부모가 모두 돌아가시니 의지할 데 없는 몸이 되었다. 온 집안이 망극하여 울음소리가 진동하는데, 애황 소저가 망극하여 기절하자 하인들이 구완하여 정신을 차리게 하였다. 초상 예법을 갖추어 선산에 장사 지내니, 규중 여자로서 장부의 일을 감당하였다. 세월이 흘러 소저의 나이 열여섯이 되었다. 옥 같은 얼굴과 구름 같은 귀밑머리, 눈 같은 살결과 꽃다운 얼굴은 이 세상에 짝이 없었다. 비록 여자이나 얼굴이 웅장하여 단산의 봉황 같은 눈은 두 귀 밑까지 닿을 듯하고[?], 맑고 빼어난 골격이며 목소리가 웅장하되 산호 채로 옥 쟁반을 깨뜨리는 듯하였다. 지혜가 활달하여 소저에 견줄 이가 없었다. 총명한 그 자색을 누가 칭송하지 않겠는가. 이러므로 이름이 사방에 떨쳤다.","sp":[[23,25,"P","장애황"],[92,94,"P","장애황"]]},{"c":1,"sub":"","t":"이때 우승상 왕희에게 아들이 하나 있었는데 이름은 석연이었다. 풍채가 늠름하고 글솜씨가 남보다 뛰어나 명망이 온 나라에 떨쳤다. 승상이 각별히 사랑하여 혼처를 구하였으나 석연의 짝이 없어 뜻을 이루지 못하던 중, 애황의 덕과 미모를 소문으로 듣고 장 한림의 육촌 장준을 청하여 대접한 뒤에 말하였다. \"그대의 종형이 일찍 세상을 떠났으니 집안의 모든 일은 그대가 주관할 것이오. 나를 위하여 중매가 되어 내 아들 석연과 그대의 종질녀가 혼인하게 해 주시오.\" 장준이 기뻐하며 허락하고 집에 돌아와 아내 진씨를 보내 소저와 이야기를 나누게 하였다.","sp":[[3,6,"P","이익"],[7,9,"P","왕희"],[28,30,"P","왕석연"],[72,74,"P","왕희"],[95,97,"P","왕석연"],[119,121,"P","장애황"],[138,142,"P","장화"],[147,149,"P","장준"],[231,233,"P","왕석연"],[257,259,"P","장준"],[281,283,"P","진씨"]]},{"c":1,"sub":"","t":"진씨가 이야기 끝에 혼인하자는 사연을 전하니 소저가 얼굴빛을 바로 하고 대답하였다. \"숙모께서는 나를 위하여 고마운 말씀으로 타이르시지만, 부모님 살아 계실 때 모란동 이 시랑의 아들과 혼약하였으니 이 일은 따를 수 없습니다.\" 진씨가 무안하여 돌아와 소저의 말을 장준에게 전하였다. 장준이 몸소 소저에게 가니 소저가 맞이하였다. 장준이 소저에게 말하였다. \"부부의 분별은 인륜의 당연한 일이다. 슬프다, 인생이여. 사람의 일이 뒤집히고 조물주가 시기하여 형님이 일찍 세상을 떠나시니, 친척이라고는 다만 너와 나뿐이로구나.","sp":[[0,2,"P","진씨"],[94,98,"P","이익"],[128,130,"P","진씨"],[148,150,"P","장준"],[159,161,"P","장준"],[185,187,"P","장준"]]},{"c":1,"sub":"","t":"내가 너를 위하여 봉황의 짝을 구하였는데, 우승상 왕희의 아들 석연은 글과 재주를 겸하고 빼어난 호걸이라 참으로 너의 짝이다. 너는 고집을 부리지 말고 하늘이 정한 인연을 어기지 말아라. 또 이 시랑 부자는 만 리 귀양지로 갔으니 살았는지 죽었는지 어찌 알겠느냐. 죽을 땅에 간 사람을 생각하며 세월을 보내면 고운 얼굴이 지는 해처럼 시들고, 무정한 세월이 흐르는 물결 같음을 한탄하게 될 것이다. 고운 얼굴이 점점 쇠하고 흰머리가 어지러워지면 무슨 영화를 보겠느냐.\" 하고 이런저런 말로 갖가지로 달래었다. 소저가 대답하였다. \"팔자가 기구하여 부모를 여의고 홑몸으로 의지할 데가 없으니, 제가 옳지 못한 행실을 하려 하더라도 옳은 일로 이끌어 주시는 것이 마땅할 터입니다. 하물며 왕희는 나와 원수인데, 소인에게 아첨하여 외로운 조카를 꾀어내려 하시니 몹시 언짢습니다. 앞으로는 우리 집에 발걸음을 하지 마십시오.\"","sp":[[24,27,"P","이익"],[28,30,"P","왕희"],[35,37,"P","왕석연"],[107,111,"P","이익"],[383,385,"P","왕희"]]},{"c":1,"sub":"","t":"장준이 소저의 눈서리 같은 절개에 탄복하고 돌아와 승상을 보고 앞뒤 사정을 이야기하니, 승상은 \"아무쪼록 혼사를 주관하라.\" 하였다. 장준이 한 꾀를 생각해 내어 왕희와 의논하니, 왕희가 크게 기뻐하여 길일을 받고 장준과 약속을 정하였다.","sp":[[0,2,"P","장준"],[28,30,"P","왕희"],[49,51,"P","왕희"],[75,77,"P","장준"],[91,93,"P","왕희"],[101,103,"P","왕희"],[120,122,"P","장준"]]},{"c":1,"sub":"","t":"이때 대봉 부자가 바다에 빠졌는데, 서해 용왕이 두 동자를 불러 말하였다. \"대명국의 충신 이익과 만고의 영웅 대봉이 소인의 참소를 만나 귀양 가다가 물속에서 죽게 되었으니 급히 가서 구하라.\" 두 동자가 작은 배를 타고 서남쪽으로 따라갔다. 이때 시랑이 물결에 밀려 한곳에 이르니 밤이 이미 삼경이었다. 정신이 혼미한 가운데 바라보니 동남쪽 큰 바다에서 한 동자가 작은 배를 타고 바람같이 오더니 시랑을 건져 배에 싣고 위로하였다. 시랑이 정신을 가다듬어 동자에게 사례하니 동자가 대답하였다. \"소자는 서해 용왕의 명을 받아 상공을 구하였으니 다행입니다.\" 하며 눈 깜짝할 사이에 한곳에 배를 대고 내리기를 청하였다. 시랑이 좌우를 살펴보니 만경창파 넓은 물 가운데 섬 하나가 있었다. \"여기서 황성이 얼마나 됩니까?\" 동자가 대답하였다. \"중원까지 삼천 리입니다.\" 시랑이 배에서 내리자 동자는 하직하고 화살같이 떠나갔다. 섬에 들어가니 과일나무가 빽빽하였다. 과일로 양식을 삼고 죽은 물고기를 주워 먹으며, 사람 없는 바닷가에 찬 바람은 쓸쓸한데 산의 나무 열매에 목숨을 붙여 세월을 보내며 아내와 자식을 생각하여 울음으로 날을 보냈다.","sp":[[3,5,"P","이대봉"],[20,25,"P","서해 용왕"],[27,31,"P","두 동자"],[51,53,"P","이익"],[62,64,"P","이대봉"],[109,113,"P","두 동자"],[139,141,"P","이익"],[201,203,"P","두 동자"],[223,225,"P","이익"],[243,245,"P","이익"],[256,258,"P","두 동자"],[266,268,"P","두 동자"],[282,287,"P","서해 용왕"],[347,349,"P","이익"],[404,406,"P","두 동자"],[431,433,"P","이익"],[443,445,"P","두 동자"]]},{"c":1,"sub":"","t":"이때 부인은 남편과 대봉을 생각하여 하늘을 우러러 신세를 한탄하며 눈물로 세월을 보내니 그 참혹한 모습을 어찌 다 말로 하겠는가. 이때 대봉은 물속에 빠져 정신을 잃고 풍랑에 밀려 떠내려가니 대봉의 귀한 목숨이 경각에 달렸다. 남쪽 큰 바다에서 난데없는 작은 배 한 척이 화살같이 떠오더니 대봉을 급히 건져 올렸다. 이윽고 정신을 차려 동자를 살펴보니, 푸른 옷에 달 모양 패옥을 차고 왼손에는 금빛 옥결을 쥐고 오른손으로는 계수나무 노를 저으며 앉아 있었다. 대봉이 일어나 동자에게 사례하였다. \"동자는 누구시기에 죽을 목숨을 구하십니까?\" 동자가 대답하였다. \"서해 용궁에 사는데 왕명을 받들어 공자를 구하였습니다.\" 대봉이 감사하며 말하였다. \"용왕의 덕택과 동자의 은덕은 백골이 되어도 잊기 어렵습니다. 어느 때에 만분의 일이나 갚겠습니까.\" 하고 물었다. \"이곳 지명을 알지 못하니 동자께서 가르쳐 주시면","sp":[[3,5,"P","마고선녀"],[11,13,"P","이대봉"],[76,78,"P","이대봉"],[107,109,"P","이대봉"],[162,164,"P","이대봉"],[188,190,"P","두 동자"],[258,260,"P","이대봉"],[266,268,"P","두 동자"],[279,281,"P","두 동자"],[304,306,"P","두 동자"],[348,350,"P","이대봉"],[364,366,"P","서해 용왕"],[372,374,"P","두 동자"],[443,445,"P","두 동자"]]},{"c":1,"sub":"","t":"알고 싶습니다.\" 동자가 대답하였다. \"이 땅은 천축국입니다.\" 하며 내리기를 청하였다. 대봉이 배에서 내려 물었다. \"어디로 가야 남은 목숨을 보전하겠습니까?\" 동자가 대답하였다. \"저 산은 금화산이고 그 안에 절이 있는데 절 이름은 백운암입니다. 그 절을 찾아가면 구해 줄 사람이 있을 것이니 그리로 가십시오.\" 하고 배를 저어 갔다. 동자가 가르쳐 준 길로 금화산을 찾아가니, 흰 구름은 맑게 떠 있는 명산이요 물은 잔잔한 별천지였다. 나무마다 피는 꽃은 가지마다 봄빛이요, 맑은 시내는 골짜기 어귀로 흘러 극락세계를 이루었다. 층층 바위와 깎아지른 벼랑은 하늘 가운데로 솟았는데, 청학과 백학은 쌍쌍이 오가고, 그윽한 두견새 소리는 나의 시름을 자아낸다. 산수도 좋지만 부모를 생각하니 좋은 풍경이 도리어 회포가 되어 눈물을 금하지 못하였다. 구름을 따라 한곳에 이르니 아득한 선경이었다. 은은한 종소리와 경쇠 소리가 바람결에 들려왔다.","sp":[[10,12,"P","두 동자"],[50,52,"P","이대봉"],[91,93,"P","두 동자"],[190,192,"P","두 동자"]]},{"c":1,"sub":"","t":"천천히 들어가니 황홀한 단청 누각이 구름 속에 보였다. 절 문에 이르니 황금 큰 글자로 뚜렷하게 '금화산 백운암'이라 쓰여 있었다. 해 질 녘에 바쁜 나그네가 주인을 찾으니, 한 노승이 아홉 폭 가사에 팔각 두건을 쓰고 아홉 마디 대지팡이를 짚고 나왔다. 동자를 맞아 인사를 마친 뒤에 말하였다. \"귀한 손님이 누추한 곳에 오셨는데 소승이 미처 알지 못하여 멀리 나가 맞지 못하였으니 무례함을 용서하십시오.\" 공자가 절하며 말하였다. \"곤궁한 길손을 이렇게 대접하시니 도리어 불안합니다.\" 노승이 대답하였다. \"오늘 이리 오신 것은 밝은 하늘이 지시한 바입니다.\" 하고 \"공자는 소승과 인연이 있으니 머무는 것을 허물로 여기지 마십시오.\"","sp":[[100,102,"P","백운암 노승"],[143,145,"P","두 동자"],[274,276,"P","백운암 노승"]]},{"c":1,"sub":"","t":"하니 공자가 일어나 두 번 절하고 대답하였다. \"어린것의 보잘것없는 목숨을 아끼시어 이렇게 불쌍히 여기시니 감격스럽습니다.\" 노승이 웃으며 말하였다. \"공자는 기주 땅 모란동 이 시랑 댁 공자 대봉이 아닙니까?\" 공자가 크게 놀라 말하였다. \"스님은 어찌 소동의 사는 곳과 이름을 아십니까?\" 노승이 말하였다. \"소승이 공자 댁에 다녀간 지 십여 년입니다. 상공께서 황금 오백 냥과 흰쌀 삼백 석, 황촉 삼천 자루를 시주하시어, 절이 비바람에 허물어져 무너질 지경이던 것을 부처님을 편히 모시게 되었으니 그 은덕을 어찌 잊겠습니까.\" \"공자의 말씀을 들으니 작은 것으로 큰 인사를 받는 것이라 감사합니다.\"[?] 노승이 대답하였다. \"공자는 나이가 어리니 지난 일을 어찌 알겠습니까.\" 하고 상좌에게 명하여 저녁밥을 들이게 하였다. 받아 보니 정결함이","sp":[[70,72,"P","백운암 노승"],[98,102,"P","이익"],[108,110,"P","이대봉"],[164,166,"P","백운암 노승"],[343,345,"P","백운암 노승"]]},{"c":1,"sub":"","t":"이때 왕석연이 길일을 맞아 하인들과 가마와 말을 거느리고 장미동에 이르니 밤이 이미 삼경이었다. 한림 댁에 들어가 소저를 겁탈하여 데려가려 하였다. 이때 소저는 촛불을 밝히고 《예기》 〈내칙〉 편을 보고 있었는데, 사랑채에서 전에 없던 사람과 말 소리가 나므로 급히 시비 난향을 불러 그 까닭을 알아보게 하였다. 난향이 급히 들어와 아뢰었다. \"왕 승상 집 하인들이 가마와 말을 거느리고 사랑채에 와서 머뭇거리고 있습니다.\" 소저가 크게 놀라 얼굴빛이 변하며 말하였다. \"한밤 삼경에 온 것은 분명 억지로 혼인하려는 것이다. 이렇게 급박하니 장차 어찌하랴.\" 하며 수건으로 목을 매어 자결하려 하였다. 난향이 위로하였다. \"소저는 잠깐 진정하십시오. 소저께서 만일 이렇게 죽으면 부모님과 낭군의 원수를 누가 갚겠습니까. 소비가 소저의 옷을 입고 앉아 있다가 소저의 화를 대신 감당하겠으니, 급히 남자 옷으로 갈아입으시고 담장을 넘어 화를 피하십시오.\"[?]","sp":[[3,6,"P","왕석연"],[54,56,"P","장화"],[152,154,"P","난향"],[175,177,"P","난향"],[195,197,"P","왕희"],[337,339,"P","난향"]]},{"c":1,"sub":"","t":"소저가 말하였다. \"나는 그렇게 하겠지만 너는 나 때문에 아름다운 청춘을 보존하지 못하겠구나.\" 하며 곧 남자 옷을 갖추어 입고 사당에 하직한 뒤 후원 담을 넘어 동산에 올라섰다. 아득한 달빛 아래 어느 곳을 향하랴. 서남쪽을 바라보고 정처 없이 가는 신세는 푸른 하늘의 외기러기가 짝을 찾아 소상강으로 가는 듯 가련하고 슬펐다. 장 한림 댁 무남독녀가 이리될 줄 누가 알았으랴. 이때 난향은 소저를 애처롭게 떠나보내고, 자기는 소저의 옷을 입고 침방에 들어가 소저인 양 태연히 앉아 있었다. 왕희 집 시비가 소저의 침실에 들어와 자세한 말로 갖가지로 달래며 가마를 들이고 말하였다. \"소저는 하늘이 정한 인연을 어기지 마십시오.\"","sp":[[185,189,"P","장화"],[216,218,"P","난향"],[276,278,"P","왕희"]]},{"c":1,"sub":"","t":"하며 오르기를 간청하자, 난향이 촛불을 밝히고 시비를 꾸짖었다. \"너희가 한밤 삼경에 사대부 댁 안채에 들이닥쳐 나를 해치려 하느냐. 깊은 규방에서 자란 몸이 집을 버리고 어디로 가겠느냐. 너희가 돌아가지 않으면 너희 눈앞에서 죽어 원수를 지으리라.\" 하고 수건으로 목을 조르니, 석연의 하인들이 수건을 빼앗고 가마에 태웠다. 난향 홑몸으로 강약이 같지 않아 가마에 실려 장안으로 갔다. 장미동을 떠나 백화정 이십 리를 가니 동쪽 하늘이 밝아 오려 하였다. 늙은이 젊은이 할 것 없이 백성들이 \"장 한림 댁 장 소저가 왕 승상 댁 며느리가 되어 신행 간다.\" 하였다. 승상 댁에 이르러 좌우를 살펴보니 큰 잔치를 차려 놓아 술잔과 접시가 어지러이 널려 있었다. 늙은 부인 젊은 부인들이 난향을 칭찬하였다. \"어여쁘구나. 애황 소저는 참으로 왕 공자의 짝이로다.\"","sp":[[14,16,"P","난향"],[157,159,"P","왕석연"],[183,185,"P","난향"],[277,281,"P","장화"],[292,294,"P","왕희"],[318,320,"P","왕희"],[373,375,"P","마고선녀"],[379,381,"P","마고선녀"],[384,386,"P","난향"],[403,405,"P","장애황"],[414,418,"P","왕석연"]]},{"c":1,"sub":"","t":"모두 칭송할 때 난향이 잔치 자리에 나아가니 온 집안이 크게 놀라고 손님들이 술렁였다. 난향이 왕희를 돌아보며 말하였다. \"소비는 소저의 시비 난향입니다. 외람되이 소저의 이름으로 승상을 속였으니 죽어도 죄가 남습니다. 승상은 부귀가 천하에 으뜸이니, 혼사를 하려면 중매를 보내 혼인 날짜를 정하여 인연을 맺고 여섯 가지 혼례를 갖추는 것이 옳거늘, 무도한 행실로 사대부 댁 안채에 한밤 삼경에 들이닥쳐 나무하는 종 따위를 데려다가 무엇을 하려 하십니까. 우리 소저는 어젯밤 오경 깊은 밤에 어디로 가셨는지, 반드시 원통한 혼이 되실 것입니다.\" 하며 통곡하였다. 승상이 크게 놀라 위로하며 말하였다. \"소저가 눈서리 같은 몸을 천한 난향에게 견주었으니[?] 그 절행을 알 만하다.\" 하고 장준을 불러 소저의 진위를 알아보게 하니 과연 난향이었다. 승상이 크게 노하여 죽이려 하자 자리에 있던 손님들이 말하였다. \"난향은 참으로 충성스러운 종이요, 모기를 보고 칼을 뽑는 격이니[?] 용서하십시오.\"","sp":[[9,11,"P","난향"],[49,51,"P","난향"],[53,55,"P","왕희"],[80,82,"P","난향"],[101,103,"P","왕희"],[123,125,"P","왕희"],[316,318,"P","왕희"],[355,357,"P","난향"],[386,388,"P","장준"],[412,414,"P","난향"],[419,421,"P","왕희"],[456,458,"P","난향"]]},{"c":1,"sub":"","t":"하니 승상이 장준을 꾸짖고 난향을 돌려보냈다. 이때 애황 소저는 집을 떠나 남쪽으로 정처 없이 가더니, 여러 날 만에 여남 땅에 이르렀다. 한곳에 다다르니 산천이 수려하고 만 길 절벽은 하늘 가운데로 솟아 있고, 산 그림자는 엄숙한데 수목이 빽빽하고 온갖 꽃이 만발하였다. 점점 들어가니 경치가 빼어나고 물빛도 그윽하였다. 꽃가지에 앉은 새는 봄빛을 자랑하고, 누런 벌과 흰 나비는 향기를 찾아 오가며, 물총새와 공작은 쌍쌍이 날아들고, 수양버들 천만 가지는 어귀에 늘어지고, 금의공자 꾀꼬리 소리는 푸른 숲 속에서 처량하고, 흐르는 물은 잔잔하여 거문고 소리를 돕는다. 점점 들어가니 사방에 사람 없이 적막하고 석양은 서쪽으로 기울었는데,","sp":[[3,5,"P","왕희"],[7,9,"P","장준"],[15,17,"P","난향"],[29,31,"P","장애황"]]},{"c":1,"sub":"","t":"자는 새는 숲으로 들고 소쩍새는 슬피 울며, 해가 함지에 지고 황혼이 되니 동쪽 고개에 비친 달빛이 금수강산을 비춘다. 밤은 깊어 삼경인데 갈 곳이 어디인가. 수풀에 의지하여 몸을 숨기고 앉았을 때, 빈 산 달밤 깊은 밤에 두견새가 슬피 울어 이내 간장을 다 녹인다. 십이 장강 푸른 물결 위에 쌍쌍이 오가는 갈매기들은 짝을 찾는 모습이로다. 슬프다, 원숭이 울음은 나의 시름을 자아내고, 강마을의 고기잡이 피리 소리가 들리니 시름이로다. 이러한 가운데 굶주림과 목마름이 심하여 잠깐 앉아 졸고 있었는데, 꿈인 듯 생시인 듯한 사이에 한 노인이 흰머리를 휘날리며 유건을 쓰고 가을 도포에 검은 띠를 두르고 청려장을 짚고 산 위에서 내려와 말하였다. \"애황아, 잠을 깨어라. 저 무덤을 넘어가면 한 집이 있을 것이다. 그 집은 장애황이 공부할 곳이다. 어서 급히 가거라. 너의 스승이 거기 있다.\" 바람 소리에 잠을 깨니 생생한 꿈이었다.[?]","sp":[[364,366,"P","장애황"],[406,409,"P","장애황"]]},{"c":1,"sub":"","t":"노인이 가르쳐 준 무덤을 넘어 수십 걸음을 내려가니 초가 몇 칸이 보였다. 문 앞에 이르자 한 늙은 여인이 나오며 손을 잡고 반기고, 대청으로 들어가 자리를 내어 앉혔다. 애황이 일어나 두 번 절하고 물었다. \"부인은 누구신데 남은 목숨을 구해 주십니까. 감사합니다.\" 그 부인이 웃으며 대답하였다. \"나는 본래 정해진 곳 없이 천태산에 머물러 있었는데, 백운암 세존께서 이곳으로 가라 하시며 이르기를, 오늘 밤 오경쯤 장미동 장애황이 그곳에 갈 것이니 보살피라 하시기에 기다린 지 오래다.\"","sp":[[53,58,"P","마고선녀"],[96,98,"P","장애황"],[118,120,"P","마고선녀"],[153,155,"P","마고선녀"],[203,205,"P","백운암 노승"],[239,242,"P","장애황"]]},{"c":1,"sub":"","t":"하며 계집아이를 재촉하여 저녁밥을 들이니 음식이 정결하고 먹으니 향기가 배에 가득하였다. 이 부인은 마고선녀였다. 애황을 데리고 도학을 가르치니 총명함이 견줄 데 없었다. 선녀가 더욱 사랑하여 상전벽해의 술수 놓기와 온갖 법술을 가르치고, 천문과 지리, 둔갑하여 몸을 감추는 술법이며 병서를 익히게 하니, 삼 년 사이에 위로는 천문에 통하고 아래로는 지리에 통달하며 가운데로는 사람의 일을 살피게 되었다. 병법은 관중이라도 당하지 못할 정도였다. 지혜가 활달하여 모든 일에 두려운 것이 없었다. 이럭저럭 애황의 나이가 열아홉 살이 되었다. 하루는 부인이 애황을 불러 말하였다. \"이제 네 나이가 장성하였고 또한 좋은 때를 만났으니 산중을 떠나 평생의 소원을 이루어라. 나도 말년의 기한이 가까웠다. 너는 비록 여자이나 과거에 올라 귀한 몸이 되어 대장의 절월을 들고 띠며 황금 인끈을 허리에 비껴 차고,","sp":[[52,54,"P","마고선녀"],[56,60,"P","마고선녀"],[64,66,"P","장애황"],[200,202,"P","통달"],[282,284,"P","장애황"],[306,308,"P","마고선녀"],[310,312,"P","장애황"]]},{"c":1,"sub":"","t":"백만 군병을 거느려 사해를 평정하고 이름을 기린각에 올려 천추에 전하라.\" 하고는 그대로 간 데가 없었다. 애황이 허망함을 이기지 못하여 공중을 향하여 수없이 사례하고, 그곳을 떠나 마을길로 나아갔다. 한곳에 이르러 주인을 찾아 요기를 청하였는데, 이 집은 서주 최 어사 댁이었다. 어사는 일찍 세상을 떠나고 다만 딸 하나를 두었는데, 용모가 비범하여 태임의 덕과 아황·여영의 절행이며 태사의 온화하고 순한 덕과 장강의 미색을 품고 있었다. 부인 호씨는 딸과 함께 날마다 봉황 같은 짝을 얻어 딸의 일생을 맡기고자 하였다. 이때 마침 애황은 산중에서 나올 때 이름을 고쳐 해운이라 하였다.","sp":[[60,62,"P","장애황"],[247,249,"P","마고선녀"],[250,252,"P","호씨"],[299,301,"P","장애황"],[320,322,"P","장애황"]]},{"c":1,"sub":"","t":"호씨가 해운을 보고 속으로 기뻐하여 사랑채에 앉히고 물었다. \"수재는 어디 살며 성은 무엇이고 이름은 무엇인가?\" 해운이 대답하였다. \"소자는 일찍 부모를 여의고 길에서 떠돌아다니고 있습니다.\" 부인이 말하였다. \"우리 집에는 남자가 없으니 초당에 머물며 나를 위로하는 것이 어떠한가?\" 해운이 대답하였다. \"의지할 데 없는 사람을 불쌍히 여기시니 어찌 사양하겠습니까.\" 그날부터 초당에 머무르니 부인이 많은 책을 내어 주었다. 살펴보니 육도삼략과 손자·오자의 병서가 있어 병서를 살피며 세월을 보냈다. 이때 대봉은 본래 지혜가 활달한 데다 살아 있는 부처를 만났으니, 신통한 술법과 신묘한 재주는 당시에 견줄 이가 없었고 마음은 오자서를 압도할 만하였다.","sp":[[0,2,"P","호씨"],[4,6,"P","장애황"],[64,66,"P","장애황"],[109,111,"P","마고선녀"],[161,163,"P","장애황"],[222,224,"P","마고선녀"],[285,287,"P","이대봉"],[303,311,"P","백운암 노승"]]},{"c":1,"sub":"","t":"이때는 성화 19년 정해년 봄 3월 15일이었다. 황제가 하교하였다. \"왕자(王者)에게는 문(文)을 귀히 여기는 것만 한 것이 없고, 백성에게는 '어제환'만 한 것이 없다[?] 하니, 어진 신하가 많으면 천하를 아우르는 데 더욱 좋다.\" 하시고 장차 과거를 보이시니 천하의 선비가 모여들었다. 이때 해운이 과거 소식을 듣고 호씨에게 아뢰었다. \"황성에서 태평과를 연다 하니 한번 나가 구경하고자 합니다.\" 부인이 허락하고 종이와 붓, 금은과 옥촉을 많이 주며 말하였다. \"내 신세가 박명하여 남편을 여의고 또 아들도 없다. 다만 딸 하나를 두었는데, 덕과 미모는 없으나 수건과 빗을 받들 만은 하니 공자의 뜻은 어떠한가?\" 공자가 흔쾌히 허락하니 부인이 크게 기뻐하며 빨리 돌아오기를 당부하였다.","sp":[[28,30,"P","천자"],[167,169,"P","장애황"],[181,183,"P","호씨"],[227,229,"P","마고선녀"],[362,364,"P","마고선녀"]]},{"c":1,"sub":"","t":"그날로 길을 떠나 여러 날 만에 기주에 이르니 옛일을 생각하여 눈물을 금치 못하였다. 장미동에 들어서며 좌우를 살펴보니 예전에 보던 좌우의 청산은 어제 본 듯 반가웠다. 전날 보던 푸른 대와 푸른 소나무는 군자의 절개를 지켜 꿋꿋이 서 있는데, 집에 들어가니 쓸쓸한 마음이 저절로 났다. 사방을 살펴보니 왕석연의 화를 피하여 간신히 넘던 담장이 비바람에 허물어져 반이나 무너져 있었다. 이때 난향이 홀로 집을 지키고 있었는데, 어떤 공자가 안채로 들어오므로 크게 놀라 급히 몸을 피하였다. 그 공자가 곧장 침방에 들어와 난향의 손을 잡고 통곡하였다. \"난향아, 너는 나를 모르겠느냐?\" 난향이 그제야 자세히 보니 예전 보던 얼굴이 은은하고 목소리에 드러나니, 꽃 같은 얼굴 달 같은 자태 고운 모습이 분명 우리 소저였다.","sp":[[170,173,"P","왕석연"],[219,221,"P","난향"],[291,293,"P","난향"],[309,311,"P","난향"],[328,330,"P","난향"]]},{"c":1,"sub":"","t":"소저의 목을 안고 목 놓아 통곡하며 하는 말이, \"우리 소저, 산 몸으로 오셨는가, 영혼이 오셨는가, 바람과 구름에 싸여 오셨는가. 〇반갑구나 반갑구나, 더디도다 더디도다. 소저의 걸음 더디도다. 어이 그리 더디셨던고. 소상강의 얼룩 대나무가 되어 아황·여영을 위로하셨던가. 〇오랑캐 땅에 지내다가 왕소군을 위로하셨던가. 〇해성(垓城) 달밤에 가서 우미인을 위로하셨던가. 〇은하수 오작교에 다다라 견우직녀를 만나셨던가. 〇진시황이 신선을 구하려고 불사약을 구하던가. 〇천태산 마고선녀 따라가 상전벽해를 겪어 보셨던가. 〇북해의 소무 따라 여자의 절개를 본받으셨던가. 〇수양산의 백이숙제 따라 고사리를 캐셨던가. 〇채석강 가을 달밤에 풍월을 싣고 가셨던가. 〇상공 벼슬을 마다하고","sp":[[266,270,"P","마고선녀"]]},{"c":1,"sub":"","t":"동강 칠리탄에서 낚싯대를 드리우셨던가[?]. 〇예양처럼 비수를 들고 다리 밑에 숨으셨던가. 〇장량의 철퇴가 되어 박랑사 가운데를 다니셨던가. 〇진나라 자객이 되어 형세를 엿보셨던가. 〇위수의 여상(강태공)이 되어 고기에게 밥을 주셨던가. 〇어이 그리 더디셨던고. 박명한 난향이는 홀로 푸른 무덤(청총)을 본받고[?], 옥 같은 얼굴 우리 소저는 여자가 남자가 되셨으니 하늘이 낸 영웅의 엄한 위풍을 그 누가 알아보리. 우리 소저와 이별한 뒤 밤낮으로 생각이 끊이지 않아 미친 듯 취한 듯 지냈는데, 밝은 하늘이 도우시어 존귀해지신 뒤 우리 소저를 오늘 또 보게 하니, 반갑기는 예사요 슬프기 한량없네.\" 둘이 서로 통곡하다가 정신을 가다듬고 그간의 일을 이야기하며 애달프게 눈물을 흘렸다. 소저는 사당에 들어가 통곡하며 두 번 절하고,","sp":[[151,153,"P","난향"]]},{"c":1,"sub":"","t":"물러 나와 난향에게 말하였다. \"내가 본래 마음을 지켜 규방에서 늙는다면 누가 나의 원한을 풀어 주겠느냐. 지금 과거가 있으니 과장에 들어가 다행히 급제하면 평생의 한을 풀 것이다. 너는 나의 종적을 누설하지 말고 집을 지키며 나를 대신하여 제사를 착실히 받들어라.\" 하며 난향과 작별하고 그날 장미동을 떠나 황성에 이르렀다. 이때는 여름 4월 초파일이었다. 과거 날이 되자 황제가 황극전에 나와 앉으시고 과장의 모든 선비가 글제를 기다리는데, 궁중 음악이 맑게 울리고 앵무새가 춤을 추었다. 조정 백관이 모시는 가운데 대제학을 뽑아 황제가 글제를 내리시니, 세 당상관이 받들어 내어 과장 문에 높이 거는데 글제에 '성화춘과택인재(成化春科擇人才)'라 하였다. 이때 해운이 글제를 살핀 뒤 시상을 생각하여 옥 같은 손으로 산호 붓을 잡고 한 폭 꽃종이에 단숨에 써 내려가니 용과 뱀이 날아오르는 듯하였다. 맨 먼저 글을 바치니 시관이 글을 보고 천자 앞에 올려놓았다. 글에는 점 하나 찍을 데가 없고 글자마다 비점이요 구절마다 관주였다.","sp":[[6,8,"P","난향"],[153,155,"P","난향"],[210,212,"P","천자"],[299,301,"P","천자"],[372,374,"P","장애황"],[472,474,"P","천자"]]},{"c":1,"sub":"","t":"황제가 크게 칭찬하였다. \"짐이 어진 인재를 보려 하였더니 과연 얻었도다.\" 하시고 봉해 둔 이름을 뜯어 보시니 '여남 장미동 장해운'이라 하였다. 급제자를 섬돌 아래로 불러내니 해운이 들어가 섬돌 아래 엎드렸다. 폐하께서 친히 불러 해운의 손을 잡고 어주 석 잔을 권하신 뒤 등을 어루만지며 말씀하셨다. \"전날 한림학사 장화는 짐의 기둥 같은 신하였다. 이제 경이 그 아들이라 하니 어찌 기쁘지 않겠는가.\" 하시고 곧 한림 벼슬을 내리셨다. 한림이 은혜에 감사하는 절을 올리고 대궐 문을 나설 때, 머리에는 어사화요 몸에는 앵삼이었다. 푸른 비단 금포에 옥띠를 두르고 금 안장 준마에 시원스레 높이 앉아 장안 큰길로 천천히 나오는데, 비단옷 입은 꽃 같은 동자들은 쌍쌍이 앞에서 인도하고, 푸른 비단 일산과 권마성은 하늘 가운데 높이 떠서 성 안이 떠들썩하니 장안 모든 집이 한소리로 놀랐다. 좌우에서 구경하는 사람들 가운데 누가 칭찬하지 않으랴. 옥 같은 얼굴에 신선 같은 풍모, 고운 얼굴에 위풍이 늠름하니 푸른 산 같은 눈썹 사이에 조화를 감추었고, 단산 봉황의 눈은 이 세상의 영웅이었다.[?]","sp":[[0,2,"P","천자"],[71,74,"P","장애황"],[100,102,"P","장애황"],[131,133,"P","장애황"],[175,177,"P","장화"],[180,182,"P","장화"],[235,237,"P","장화"],[248,250,"P","장화"],[368,370,"P","두 동자"]]},{"c":1,"sub":"","t":"사흘 동안 유가(遊街)를 한 뒤 폐하께 절하고 기주 고향으로 돌아와 사당에 절하여 뵙고 산소에 성묘하니 한편으로 기쁘고 한편으로 슬펐다. 누가 소저라고 하겠는가. 홀로 난향만이 한편으로 기뻐하고 한편으로 슬퍼하였다. 사당과 무덤에 하직하고 난향을 불러 집안일을 당부한 뒤 여남으로 갔다. 이때 우승상 왕희가 황제께 아뢰었다. \"전 한림 장화는 아들이 없는데, 여남의 장해운이 스스로 장화의 아들이라 일컬어 한림이 되었습니다. 엎드려 바라건대 폐하께서는 해운을 국문하시어 속인 죄를 경계하시고 조정을 바로잡으소서.\" 황제가 크게 노하여 말하였다. \"부자 사이는 남이 말할 바가 아니라 하였거늘, 경이 어찌 자세히 알아 해운을 해치려 하느냐.\" 하시니 왕희가 땀을 흘리며 사죄하였다.","sp":[[94,96,"P","난향"],[134,136,"P","난향"],[164,167,"P","이익"],[168,170,"P","왕희"],[172,174,"P","천자"],[185,187,"P","장화"],[188,190,"P","장화"],[205,208,"P","장애황"],[214,216,"P","장화"],[227,229,"P","장화"],[253,255,"P","장애황"],[288,290,"P","천자"],[345,347,"P","장애황"],[363,365,"P","왕희"]]},{"c":1,"sub":"","t":"이때 장 한림이 여남 최 어사 댁에 이르러 부인 호씨를 뵈니, 부인이 한림의 손을 잡고 몹시 사랑하며 기뻐하는 모습을 어찌 다 말로 하겠는가. 이어 딸의 혼사를 이루고자 하였는데, 이때 황제가 한림을 총애하시어 사자를 보내 부르시므로 한림이 명을 받들고 급히 떠날 채비를 하였다. 호씨가 빨리 다시 보기를 당부하였다. 한림이 황성에 이르러 황제 앞에 절하니 황상께서 말씀하셨다. \"경은 짐의 기둥 같은 신하이니 곁을 떠나지 말고 짐의 밝지 못함을 바른말로 간하라.\" 하시고 벼슬을 올려 예부시랑 겸 간의대부를 제수하시니 명망이 조정에 떨쳤다.","sp":[[3,7,"P","장화"],[24,26,"P","마고선녀"],[27,29,"P","호씨"],[35,37,"P","마고선녀"],[39,41,"P","장화"],[104,106,"P","천자"],[108,110,"P","장화"],[131,133,"P","장화"],[157,159,"P","호씨"],[178,180,"P","장화"],[190,192,"P","천자"],[200,202,"P","천자"],[274,276,"P","이익"]]},{"c":1,"sub":"","t":"이때는 성화 22년 10월 19일이었다. 황제가 어양궁에 나와 앉아 백관을 모아 잔치를 베풀고 나랏일을 의논하시는데, 뜻밖에 해남 절도사 이성태가 장계를 올렸다. 곧 뜯어보니 이렇게 쓰여 있었다. \"남선우가 강성하여 역모의 뜻을 품고 철기 십만과 정병 팔십만을 일으키고 장수 천여 명을 거느려 촉담과 거란퇴를 선봉으로 삼아 국경을 침범하였습니다. 여남 칠십 성을 쳐서 항복을 받고 백성을 노략하니 창고의 곡식이 바닥나고, 적병이 이르는 곳마다 백성의 주검이 산 같으며, 여남 태수 정모를 죽이고 해남 지경을 침범하였으니 입술이 없어지면 이가 시린 격입니다. 엎드려 바라건대 폐하께서는 명장을 뽑아 적병을 막으소서.\"[?]","sp":[[23,25,"P","천자"],[111,114,"P","남선우"],[164,166,"P","촉담"],[168,171,"P","거란퇴"]]},{"c":1,"sub":"","t":"황제가 다 보시고 크게 놀라 적을 막을 방도를 의논하는데, 또 풍성 태수 설만취가 장계를 올렸다. 곧 뜯어보니 이렇게 쓰여 있었다. \"남선우는 여남을 쳐서 함락하고 해남 지경을 침범하여 남관을 쳐서 항복을 받고 관중에 웅거하여 군사를 먹이고[?] 황성으로 진군하는데, 정병과 철기가 백여만이라 가는 곳마다 대적할 자가 없습니다. 엎드려 바라건대 황상께서는 명장을 뽑으시어 적병의 큰 세력을 막으소서.\" 황상이 다 보시고 얼굴빛을 잃고 좌우를 돌아보시니, 조정이 어지럽고 장안이 술렁여 신하와 백성이 허둥지둥하였다. 좌승상 유원진과 병부상서 진태열이 조정을 부추겨 함께 아뢰었는데, 황제가 해운을 총애하는 것을 시기하였기 때문이었다. 여러 신하가 함께 아뢰었다. \"충신은 국가의 근원이요 난적은 국가의 근심입니다. 사나운 도적의 선봉장 촉담과 거란퇴는 당대의 명장이니 이 두 장수를 누가 당하겠습니까. 원컨대 폐하께서는, 예부시랑 해운은 지략이 남보다 뛰어나고 문무를 겸하였으니 참으로 적장의 적수가 될 것이므로, 그를 불러 적병을 깨뜨리게 하시어 만백성의 실망과 탄식이 없게 하소서.\"","sp":[[0,2,"P","천자"],[75,78,"P","남선우"],[193,195,"P","천자"],[225,227,"P","천자"],[288,291,"P","유원진"],[292,295,"P","유원진"],[297,301,"P","진태열"],[302,305,"P","진태열"],[325,327,"P","천자"],[329,331,"P","장애황"],[411,413,"P","촉담"],[415,418,"P","거란퇴"],[461,463,"P","이익"],[464,466,"P","장애황"]]},{"c":1,"sub":"","t":"황상께서 말씀하셨다. \"해운의 빼어난 풍모와 지략은 짐이 알지만, 만 리 싸움터에 그 나이 어린 것이 걱정이로다.\" 해운이 엎드려 아뢰었다. \"소신은 시골의 미천한 신하로서 하늘 같은 은혜를 입어 과거에 오르고 벼슬이 높아졌습니다. 나라의 운수가 망극한 이때를 당하여 폐하의 성은을 만분의 일이라도 갚고자 하니, 엎드려 바라건대 황상께서 군병을 주시면 한번 북을 쳐 적의 목숨을 물리치고 난적을 베어 천하를 평정하고자 합니다.\" 황상께서 크게 기뻐하시어 곧 해운을 상장군으로 삼아 대원수에 봉하시고 황금 인끈과 대장의 절월을 주시며 \"군중에 만일 태만한 자가 있으면 그 자리에서 베라.\" 하셨다. 군병을 모아 정병 팔십만을 일으키고 군대의 대오를 정돈하는데, 원수는 칠성 투구에 용문 전포를 입고 허리에 황금 인끈을 두르고,","sp":[[0,2,"P","천자"],[13,15,"P","장애황"],[65,67,"P","장애황"],[184,186,"P","천자"],[240,242,"P","천자"],[256,258,"P","장애황"]]},{"c":1,"sub":"","t":"대장의 절월을 띠고 오른손에 참사검을 잡고 왼손에 지휘 깃발을 들고 천리준총을 비껴 타고 군사를 호령하여, 황성 밖 십 리 모래사장에 진을 치고 군호를 시험하였다. 용과 봉황을 그린 깃발과 기치 창검은 해와 달을 가리고[?], 흰 깃대 장식과 누런 도끼는 가을 서리 같아서 백 리에 이어졌다. 남쪽은 주작, 북쪽은 현무, 동쪽은 청룡기, 서쪽은 백호기로 응하게 하고 가운데 황기는 본진의 깃발로 삼아 각 방위를 정돈하였다. 장수들을 뽑아 한능을 선봉으로, 황신을 좌익장으로, 장관을 우익장으로, 조선을 후군장으로, 호신을 남주작으로, 한통을 북현무로 삼고, 사마장군 한주와 포기장군 마맹덕을 두고, 남주를 군사마로 삼았다. 원수가 황제 앞에 들어가 출정을 아뢰니,","sp":[[245,247,"P","한능"],[353,355,"P","천자"]]},{"c":1,"sub":"","t":"황상께서 친히 원수를 따라 진문에 납시었다. 원수가 군사장군 남주를 불러 진문을 크게 열고 황상을 모셔 장대에 앉으시게 한 뒤 진법을 구경하시게 하였다. 원수가 황상께 아뢰었다. \"북두에 비록 칠성이 있으나 그 아래 이십팔수가 있어 절후를 짓습니다. 나라의 신하들도 또한 이와 같아야 하거늘, 이른바 조정 대신들은 몸을 닦고 집안을 다스릴 줄만 알고 나라를 다스리고 천하를 평안하게 할 줄 아는 신하는 적으니 답답합니다. 병부상서 진태열은 문무를 겸하고 위인이 엄하고 씩씩하니 군대의 고된 일을 맡을 만합니다. 엎드려 바라건대 폐하께서는 그를 소신에게 허락하소서.\"","sp":[[0,2,"P","천자"],[51,53,"P","천자"],[90,92,"P","천자"],[236,240,"P","진태열"],[241,244,"P","진태열"]]},{"c":1,"sub":"","t":"황상께서 말씀하셨다. \"짐이 덕이 없어 도적이 강성하므로 원수를 부득이 만 리 싸움터로 보내는데, 어찌 신하 하나를 허락하지 않겠는가.\" 하시고 곧 허락하신 뒤 궁으로 돌아가셨다. 원수가 곧 통지문을 만들어 선봉 한능을 불러 진태열을 데려오라 하였다. 한능이 명을 받들고 병부에 이르러 통지문을 태열에게 들이니, 병부상서 진태열은 오만한 마음이 높은 사람이었다. 통지문을 뜯어보니 이렇게 쓰여 있었다. \"한림 겸 예부시랑 대원수 병마상장군 장해운은 병부상서 진태열 휘하에 부치노라. 나라의 운수가 불행하여 외적이 난을 일으켜 세상을 어지럽히니, 나라의 운수가 망극하여 외람되이 상장의 절월과 대원수의 인신을 받아 만 리 싸움터로 간다. 임금에게 충성을 다하는 것은 장부의 할 바라, 그대를 군량관 겸 총독장으로 정하니 통지문을 보고 곧 대령하라. 만일 태만하면 군법으로 시행하리라.\"","sp":[[0,2,"P","천자"],[119,121,"P","한능"],[126,129,"P","진태열"],[141,143,"P","한능"],[175,179,"P","진태열"],[180,183,"P","진태열"],[226,228,"P","장화"],[233,235,"P","이익"],[246,249,"P","장애황"],[251,255,"P","진태열"],[256,259,"P","진태열"],[386,389,"P","진태열"]]},{"c":1,"sub":"","t":"태열이 통지문을 보고 분기가 하늘을 찔러 황제께 들어가 사연을 아뢰고 통지문을 올리며 분해하였다. 황상께서 한참 말없이 계시다가 말씀하셨다. \"조정의 여러 신하 가운데 해운의 위엄을 당할 자가 있는지 알지 못하겠노라. 그대가 가서 면하여 보라.\" 하시니, 여러 신하 가운데 누가 두려워하지 않겠는가. 태열이 하릴없이 식구들에게 하직하고 곧 갑옷과 투구를 갖추고 한능을 따라 진문에 이르러 이름을 아뢰었다. 원수가 장대에 높이 앉아 포기장군 마맹덕을 불러 오방 깃발을 방위대로 벌여 세우고 군대의 대오를 갖추게 한 뒤, 좌익장 조선에게 명하여 진문을 크게 열고 태열을 잡아들이라 하니 호령이 가을 서리 같았다. 조선이 명을 받들어 태열을 잡아들여 장대 아래 꿇리니 원수가 크게 노하여 말하였다. \"너는 전날 병권을 잡고 교만이 심하였지만, 이제 내가 황명을 받아 대병을 거느리고 군령을 세웠거늘 너는 어찌 거만하냐. 이제야 들어오니 너는 군율을 우습게 여기고 나를 능멸하는 것이다. 너를 베어 군법에 복종하게 하리라.\" 하고 좌우 장수들에게 진문 밖에서 베라고 호령하며 \"만일 영을 어기는 자가 있으면 그 자리에서 베리라.\" 하니, 장수들과 온 군중이 두려워하지 않는 자가 없었다.","sp":[[23,25,"P","천자"],[55,57,"P","천자"],[94,96,"P","장애황"],[202,204,"P","한능"]]},{"c":1,"sub":"","t":"태열이 엎드려 아뢰었다. \"소장은 나이 쉰이 된 늙은 몸입니다. 늙은 신하를 어디에 쓰겠습니까. 엎드려 바라건대 원수께서는 용서하시고 한 가지 소임을 맡기시면 정성을 다해 감당하겠으니 남은 목숨을 아껴 주소서.\" 하며 애걸하였다. 또 장수들이 한꺼번에 애걸하였다. \"엎드려 바라건대 원수께서는 깊이 생각하십시오. 아직 도적과 맞서 싸우지도 않았으니 용서하소서.\" 하며 저마다 애걸하였다. 원수가 노여움을 참고 말하였다. \"너를 베어 군율을 세울 것이로되 장수들이 간하므로 용서하겠다. 그러나 네가 만일 이후에 죄를 범하면 앞의 죄까지 아울러 용서하지 않으리라.\" 하고, 군령을 그냥 거둘 수 없어 곤장 열 대를 쳐서 내보냈다가 다시 들여 군량관으로 삼고, 설원을 총독장으로 삼아 대군을 거느리고 진군하게 하였다. 원수가 대군을 거느리고 대궐로 들어가 황제께 하직을 아뢰니,","sp":[[357,360,"P","진태열"],[420,422,"P","천자"]]},{"c":1,"sub":"","t":"황상께서 친히 조정 백관을 거느리고 십 리 밖까지 나와 전송하시며, 원수의 손을 잡고 친히 잔을 들어 석 잔을 권하시고 \"만 리 싸움터에서 큰 공을 이루고 무사히 돌아와 짐의 근심을 덜게 하라.\" 하며 애틋하게 작별하셨다. 군대의 대오를 살펴보니 진세가 굉장하고, 장수와 군사가 드나들고 나아가고 물러나는 법은 옛날 한신도 당하지 못할 정도였다. 흰 깃대 장식과 누런 도끼, 용과 봉황을 그린 깃발과 긴 창과 칼은 해와 달을 가리고, 북과 징 소리와 함성은 천지를 진동하며, 목탁과 나팔 소리에 강산이 메아리쳤다. 대원수는 갑옷을 갖추고 오른손에 일곱 자 참사검을 쥐고 왼손에 지휘 깃발을 들고 장수들을 호령하며 천리준총에 날렵하게 앉아 진군을 재촉하였다. 여러 날 만에 양무에 이르러 군사를 먹이고 곧 출발하여 능무를 지나 해하에 들어가 군사를 쉬게 하고[?], 이튿날 진군하여 하남 지경에 이르러 적의 형세를 알아보니,","sp":[[0,2,"P","천자"]]},{"c":1,"sub":"","t":"정탐꾼이 아뢰었다. \"적병이 하남을 휩쓸고 여남관에 웅거하다가 성주로 갔습니다.\" 원수가 장수들을 불러 군사를 재촉하여 성주로 진군하되 사흘 안에 이르게 하라 하였다. 장수들이 명을 받들어 밤낮으로 진군하여 사흘 만에 이르러 적의 형세를 알아보았다. 이때 선우는 성안에 들어가 군사를 쉬게 하며 원수를 기다리고 있었는데, 원수가 지경에 이르자 격서를 명나라 진으로 보내 싸우기를 재촉하였다. 원수가 격서를 보고 좌익장 한능을 불러 말하였다. \"반적은 들으라. 네가 하늘의 위엄을 거슬러 감히 황제의 군대에 맞서려 하니 죽어도 죄가 남는다. 오늘은 해가 서산에 졌으니 내일 너희를 깨뜨리리라.\" 원수가 백사장에 영채를 세우고 총독장 설원을 불러 \"이경에 밥을 지어 삼경 초에 군사를 먹이고 사경 초에 나의 명령을 기다리라.\" 하였다. 이때 선우는 명나라 진을 보고 장수들을 모아 군호를 정돈하고 성문을 굳게 닫고 밤을 지냈다.","sp":[[143,145,"P","남선우"],[234,236,"P","한능"],[275,277,"P","천자"],[413,415,"P","남선우"]]},{"c":1,"sub":"","t":"이때 원수가 장대에 올라 성주의 지도를 살핀 뒤 사경이 되자 친히 장대에서 내려와 장수들을 모아 군호를 단속하였다. 선봉장 한능을 불러 \"너는 갑군 오천을 거느리고 북쪽으로 십 리를 가서 금산 작은 길에 매복하였다가 적병이 그리로 가거든 이리이리 하라.\" 하고, 또 좌익장 황신을 불러 \"너는 철기 오천을 거느리고 북쪽 십 리 큰길을 막아 이리이리 하라.\" 하고, 또 우익장 장관을 불러 \"너는 궁노수 오천을 거느리고 동문 십 리에 산이 있으니 산골짜기에 매복하였다가 도적이 몰려오거든 일제히 쏘라.\" 하고, 또 사마장군 한주를 불러 \"너는 정병 오천을 거느리고 동문 왼편에 매복하였다가 이리이리 하라.\" 하고, 또 포기장군 마맹덕을 불러 \"너는 복병 오천을 거느리고 서문 남쪽에 매복하였다가 북소리가 나거든 곧 서문을 취하라.\" 하고,","sp":[[69,71,"P","한능"]]},{"c":1,"sub":"","t":"또 총독장 설원을 불러 \"너는 정병 오천을 거느리고 서문 북쪽에 매복하였다가 맹덕을 접응하라.\" 하고, 후군장 조선을 불러 \"너는 본진을 지키라.\" 하였다. 모두 각기 나누어 보내고 \"나머지 장수는 나의 명령을 기다리라.\" 하였다. 날이 밝기 전에 군사에게 아침밥을 먹이고 날이 밝자 갑옷과 투구를 갖추고 오른손에 참사검을 쥐고 왼손에 철퇴를 들고 몸을 날려 말에 올라 진문을 크게 열고 진 앞에 나섰다. 좌우를 호령하여 남주작과 북현무를 응하게 하고 장사진과 일자진을 쳐서 머리와 꼬리가 서로 맞게 한 뒤 소리를 높여 크게 외쳤다. \"반적 오랑캐야, 하늘의 때를 거슬러 세상을 어지럽히니 황제께서 크게 노하시어 나로 하여금 반적을 쓸어 없애고 사해를 평정하라 하셨기에 내가 황명을 받아 왔다. 내 칼이 싸움터에 처음 나왔으니 네 머리를 베어 네 피로 내 칼을 씻으리라.\"","sp":[[330,332,"P","천자"]]},{"c":1,"sub":"","t":"하고 천둥같이 호통을 치니 강산이 무너지는 듯 천지가 진동하였다. 이때 선우가 선봉장 촉담을 불러 대적하라 하니, 촉담이 갑옷을 갖추고 성문을 열고 나와 응하였다. 원수가 말을 채찍질하여 촉담과 맞붙어 싸우는데, 두 장수의 고함 소리에 천지가 진동하고 말굽이 어지러워 누가 누구인지 알 수 없었다. 이때 후군장 조선이 장대에 올라 북을 치니, 서문 좌우에서 북과 나팔과 함성이 진동하며 두 장수가 서문을 깨뜨리고 일만 군을 몰아 마구 쳐 죽였다. 원수는 주작군과 현무군을 몰아 마구 치니, 선우와 촉담, 거란퇴가 장수들을 몰아 죽기로 막았다. 촉담은 당대의 명장이라 원수를 맞아 십여 합을 싸워도 승부가 나지 않았다. 원수가 좌우를 호령하며 동쪽으로 치닫고 서쪽으로 내달으니, 주작 호신은 삼만 군을 몰아 원수의 왼편을 돕고, 현무 한통은 삼만 정병을 몰아 원수의 오른편을 도왔다.","sp":[[40,42,"P","남선우"],[48,50,"P","촉담"],[64,66,"P","촉담"],[105,107,"P","촉담"],[274,276,"P","남선우"],[278,280,"P","촉담"],[282,285,"P","거란퇴"],[304,306,"P","촉담"]]},{"c":1,"sub":"","t":"제아무리 명장인들 원수의 용맹을 당하겠는가. 이때 선우가 서쪽을 바라보니 함성이 크게 일며 두 장수가 쳐들어오는데, 이는 포기대장 마맹덕과 총독장 설원이었다. 선우가 장수 몇을 거느리고 두 장수를 막은들 어찌 당하겠는가. 앞에서는 대원수가 날랜 용맹으로 좌우익을 몰아치고 서쪽에서는 두 장수가 몰아치니, 군사의 주검이 산 같고 피가 흘러 내를 이루었다. 형세가 점점 위태로웠다.","sp":[[28,30,"P","남선우"],[89,91,"P","남선우"]]},{"c":1,"sub":"","t":"원수가 이긴 기세를 타고 동쪽으로 가는 듯하다가 서쪽 장수를 베고, 앞으로 가는 듯하다가 북쪽 장수를 베고, 서쪽으로 번뜻 동쪽 장수를 치고, 북쪽으로 번뜻 남쪽 장수를 짓치며 좌우로 치닫다가 중군 장수를 베어 들고 촉담의 앞으로 짓쳐 달려들었다. \"울지 못하는 닭이요 짖지 못하는 오랑캐야, 빨리 나와 항복하라.\" 호통 소리는 우레와 벼락같이 진동하고, 적진 한가운데로 달려들어 좌충우돌 거침없이 다니니, 사람은 천신 같고 달리는 말은 나는 용 같았다. 누가 능히 당해 내랴. 거란퇴가 원수를 대적하였으나 반 합도 못 되어 호통 한 소리에 거란퇴를 베어 들었다. 총독과 포기의 군사가 합세하니 이긴 기세가 더욱 등등하고, 네 장수의 고함 소리에 강산이 메아리쳤다. 원수의 엄한 위풍은 단산 밑에서 범을 치는 듯하니, 적진 선봉 촉담이 원수 앞을 막은들 어찌 당하겠는가. 선우의 팔십만 병은 대오를 차리지 못하였다. 선우가 장대에 올라 북을 울리며 깃발을 휘둘러 군사로 원수를 에워싸게 하자, 원수가 장수들을 호령하여 촉담의 좌우를 치게 하니 촉담이 어찌 네 장수를 당하겠는가. 원수는 후군으로 달려들어 필마단검으로 군사를 짓치며 거침없이 다니니 가련하다.","sp":[[121,123,"P","촉담"],[268,271,"P","거란퇴"],[303,306,"P","거란퇴"],[408,410,"P","촉담"],[410,414,"P","이대봉"],[432,434,"P","남선우"],[457,459,"P","남선우"],[514,516,"P","촉담"],[528,530,"P","촉담"]]},{"c":1,"sub":"","t":"선우의 장졸은 팔공산을 두른 초목이 구시월에 시드는 것과 같았다. 원수의 일곱 자 참사검이 햇빛을 따라 번뜩이자 오랑캐 적이 스러지는 것이 가을바람에 낙엽이 날리는 듯하여, 군사가 죽어 산을 이루고 피는 흘러 내를 이루었다. 원수가 입은 전포는 피가 묻어 붉은 꽃 같고, 나는 용같이 달리는 말의 굽에는 피가 엉겨 모란꽃 같았다. 후군을 다 짓치고 중군으로 달려드니, 촉담이 네 장수를 맞아 싸우다가 원수가 중군으로 들어오는 것을 보고 네 장수를 버리고 중군으로 들어와 원수와 자웅을 겨루려 하였다. 촉담이 쇠활에 봉뇌살을 먹여 원수의 가슴을 쏘자, 원수는 날아오는 살을 철퇴로 막으면서 봉황 같은 눈을 부릅뜨고 꾸짖었다. \"개 같은 적장 놈은 빨리 나에게 항복하라. 네가 만일 더디면 사정없는 내 칼이 네 목에 빛나리라.\" 이때 선우는 거란퇴의 주검을 보고 원수를 당하지 못할 줄 알고 도망하려 하였으나, 서쪽과 남쪽은 네 장수가 막고 있고 원수는 진중에서 거침없이 날뛰니[?]","sp":[[0,2,"P","남선우"],[206,208,"P","촉담"],[280,282,"P","촉담"],[409,411,"P","남선우"],[413,416,"P","거란퇴"]]},{"c":1,"sub":"","t":"갈 바를 모르다가 동북쪽이 비어 있으므로, 선우가 선봉군을 수습하여 북문을 열고 달아나며 거륜과 촉마로 하여금 뒤를 막게 하였다. 촉담은 원수를 대적하다가 당하지 못할 줄 알고 장졸을 거느려 동문을 열고 달아났다. 이때 원수가 큰 싸움 팔십여 합에 선우와 촉담을 잡지 못하자, 포기·총독·현무 세 장수에게 선우를 쫓아 마구 치라 하고, 자신은 군사마 남주를 데리고 곧장 촉담의 뒤를 따랐다. 촉담이 힘이 다하여 한곳에 이르니 문득 한 떼의 군마가 내달았다. 이는 사마장군 한주였다. 쌍봉 투구에 녹운갑을 입고 왼손에 방패를 들고 오른손에 긴 창을 들고 내달아 크게 꾸짖었다. \"무지한 도적은 어디로 가려 하느냐. 목숨이 아깝거든 말에서 내려 항복하라.\" 이때 촉담이 크게 노하여 한주와 맞붙어 싸우는데, 몇 합이 못 되어 한주가 거짓 패하여 달아났다.","sp":[[24,26,"P","남선우"],[73,75,"P","촉담"],[139,141,"P","남선우"],[143,145,"P","촉담"],[171,173,"P","남선우"],[207,209,"P","촉담"],[219,221,"P","촉담"],[369,371,"P","촉담"]]},{"c":1,"sub":"","t":"촉담이 한주를 쫓으려 하는데 문득 산 뒤에서 북소리와 함성이 천지를 진동하며 한 장수가 나왔다. 이는 우익장 장관이었다. 봉천 투구에 백운갑을 입고 왼손에 지휘 깃발을 들고 오른손에 장금사모창을 들고 말 위에 높이 앉아 궁노수를 재촉하여 활을 일제히 쏘게 하니 화살이 비 오듯 하였다. 촉담이 당황하던 차에 한주의 군사가 합세하고 두 장수가 앞을 막아 항복을 재촉하는데, 뒤에서 함성이 크게 일며 진의 기세가 하늘을 찌르는 가운데 한 대장이 왔다. 이는 바로 장 원수였다. 크게 외쳤다. \"적장은 달아나지 말고 말에서 내려 항복하여 죽음을 면하라.\" 하며 비바람같이 달려오니, 그 가운데 들었으니 제아무리 명장인들 견디겠는가. 군사를 거의 다 잃고 원수를 막아서려 하였으나 화살과 돌이 어지러워 갈 바를 모르던 차에, 천둥 같은 소리 끝에 일곱 자 칼이 번뜩이며 촉담의 머리가 칼빛을 따라 떨어졌다. 원수가 칼끝에 머리를 꿰어 들고 적군을 호령하니 일시에 항복하였다. 적장 십여 명과 군사 천여 명을 사로잡고 무기를 빼앗아 본진으로 돌아오니, 후군장 조선이 진문을 크게 열고 나와 원수를 맞아 장대로 들어가 축하하였다. 원수는 \"모두 황상의 덕이다.\" 하였다.","sp":[[0,2,"P","촉담"],[160,162,"P","촉담"],[257,261,"P","장애황"],[427,429,"P","촉담"],[579,581,"P","천자"]]},{"c":1,"sub":"","t":"이때 선우는 북문으로 도망하여 한곳에 이르러 군사를 점검하는데, 문득 북소리와 함성이 나며 한 장수가 황금 투구에 녹포운갑을 입고 갑군 오천을 거느려 마구 쳐 왔다. 이는 선봉장 한능이었다. 천사검을 높이 들고 큰 소리로 \"네가 어디로 가려느냐. 빨리 나와 항복하라.\" 하고 우레같이 호령하였다. 또 문득 북쪽에서 함성이 천지를 진동하며, 용봉 투구에 흑운갑을 입고 오른손에 천강검을 들고 왼손에 철퇴를 쥐고 철기 오천을 몰아 성화같이 들어오는데, 문득 뒤에서 북과 나팔과 함성이 진동하였다. 선우가 바라보니 세 대장이 대군을 거느리고 물밀듯 들어오므로 선우가 겁에 질려 어찌할 줄 몰랐다. 촉마와 거륜 등 십여 명이 뒤를 막고 선우는 한 무리 군사를 거느리고 동쪽으로 달아났다. 이때 다섯 장수가 합세하여 선우의 후군을 짓쳐 무찌르고 군량과 기계를 모두 빼앗고 장수 일곱 명과 군졸 천여 명을 사로잡아 낱낱이 묶었다. 다섯 장수가 군사를 재촉하여 본진으로 들어와 원수 휘하에 바치니, 원수가 크게 기뻐하여 대 아래로 내려와 장수들을 위로하고 선봉을 불러 장졸을 점검하였다. 한 명도 다친 자가 없으니 온 군중이 원수의 덕을 칭송하였다.","sp":[[3,5,"P","남선우"],[100,102,"P","한능"],[276,278,"P","남선우"],[310,312,"P","남선우"],[352,354,"P","남선우"],[396,398,"P","남선우"],[565,569,"P","이대봉"]]},{"c":1,"sub":"","t":"원수가 후군장을 불러 깃발과 수레를 벌여 세우고 군대의 대오를 갖추게 한 뒤, 장대에 높이 앉아 적장 수십 명을 잡아들이라 하였다. 좌우 장수들이 명을 받들어 적장을 잡아들이니 원수가 크게 노하여 말하였다. \"너희 왕이 외람되이 강포함을 믿고 하늘의 위엄을 범하였으니 너희 왕은 이제 사로잡겠거니와, 너희들도 다 죽일 것이로되 사람의 목숨을 생각하여 특별히 놓아 보낸다.\" 하고 곤장 서른 대씩 매우 쳐서 내보내며 말하였다. \"다시는 분수에 넘치는 마음을 먹지 말고 집에 가서 농사를 지으라.\" 또 군사들을 일제히 잡아들여 좋은 말로 타이르고 내보내라 하니, 적진 장졸들이 원수의 덕을 칭송하며 하늘을 부르고 땅을 두드리며 서로 만세를 부르고 \"원수는 천만세토록 길이 전하소서.\" 하며 갔다.","sp":[[319,323,"P","이대봉"]]},{"c":1,"sub":"","t":"이때 원수가 성안에 들어가 큰 잔치를 베풀어 온 군사를 위로하고 백성을 진무하니, 늙은이 젊은이 할 것 없이 모든 백성이 즐겨 배불리 먹고 마시며 만세를 부르고, 군사들도 즐겨 배불리 먹으며 원수의 덕을 칭송하였다. 이레 만에 진군하는데 위의가 장하였다. 승전고와 행군고 소리는 원근에 진동하고, 용봉 깃발과 칼과 창이며 흰 깃대 장식과 누런 도끼는 서리 같고, 열 길 붉은 털 장식의 사명기는 그 가운데 세워 갔다. 늠름한 명장들이 진을 지어 나아갈 때 갑옷이 선명하여 햇빛을 희롱하고, 행군 취타와 쟁과 북소리는 충성심을 돋우었다. 대원수 병마상장군은 맹렬한 기운과 빼어난 풍모, 높은 재주로 천리마 위에 비껴 앉아 위엄을 사해에 떨쳤다. 선우를 잡으려고 그 뒤를 따랐다.","sp":[[360,362,"P","남선우"]]},{"c":1,"sub":"","t":"이때 선우는 목숨만 건져 도망하여 남해에 이르러 패한 군사를 점검하니, 그때 다친 장졸까지 합하여 불과 삼만이었다. 선우가 \"백만 병을 명나라 진에서 다 죽이고 명장 백여 명과 손발 같은 촉담과 거란퇴를 죽였으니 어찌 분하지 않겠는가.\" 하고 \"다시 군사를 일으켜 천하의 명장을 얻어 명나라 진을 쳐부수고 상장군 장해운을 사로잡아 간을 꺼내고 남은 고기는 포를 떠서 죽은 장졸을 위로하여 수륙재를 지내리라.\" 하고 이를 갈며 본국으로 들어갔다. 이때 원수가 대군을 거느리고 남해에 이르러 적의 형세를 알아보니 본국으로 들어간 뒤였다. 원수가 장수들을 모아 의논하였다. \"이제 선우가 본국에 들어갔으나 그대로 두고 군사를 돌리면 뒷날 반드시 후환이 있을 것이다.\" 하니 장수들이 한입으로 같은 말을 하였다. 원수가 \"배를 준비하여 교지국에 들어가 선우를 사로잡고 남쪽 적의 항복을 받고 남만 다섯 나라를 함께 쳐서 하늘의 위엄을 베풀어 다시는 딴마음을 먹지 못하게 하리라.\" 하고, 이 뜻을 황제께 장계로 올리고 남해에 머물러 배를 준비하였다.","sp":[[3,5,"P","남선우"],[65,67,"P","남선우"],[105,107,"P","촉담"],[109,112,"P","거란퇴"],[175,178,"P","장애황"],[322,324,"P","남선우"],[417,419,"P","남선우"],[498,500,"P","천자"]]},{"c":1,"sub":"","t":"한편 황제는 원수를 만 리 싸움터에 보내고 소식을 몰라 잠자리와 식사가 편치 않으시던 차에 원수의 장계가 올라오자 곧 뜯어보셨다. 이렇게 쓰여 있었다. \"원수 겸 상장군 도총독장 신 해운은 글월로써 머리를 조아려 백 번 절하옵니다. 선우를 쳐서 적군을 깨뜨리고 촉담과 거란퇴를 베고 장수 백여 명을 베었으며, 선우를 찾았으나 도망하여 제 나라로 들어갔으므로 뒤를 따라가 선우를 잡고 남만 다섯 나라를 아울러 하늘의 위엄을 떨쳐 감히 요동하지 못하게 한 뒤 차차 군사를 돌리겠습니다. 엎드려 바라건대 폐하께서는 근심하지 마소서.\" 황상께서 크게 칭찬하여 마지않으시고 원수가 어서 돌아오기를 기다리셨다.","sp":[[3,5,"P","천자"],[102,104,"P","장애황"],[130,132,"P","남선우"],[146,148,"P","촉담"],[150,153,"P","거란퇴"],[173,175,"P","남선우"],[207,209,"P","남선우"],[296,298,"P","천자"]]},{"c":1,"sub":"","t":"이때 북흉노가 강성하여 역모의 뜻을 두고 중원을 빼앗고자 자주 엿보고 있었는데, 마침 남선우가 군사를 일으켜 중원을 범하였다는 소식을 듣고 흉노가 크게 기뻐하여 말하였다. \"때가 왔도다, 때가 왔도다. 급히 쳐서 놓치지 말리라.\" 명장을 골라 선봉으로 삼고 장수 천여 명과 군사 일백삼십만을 일으켜 진군하는데, 호왕이 의기양양하여 말하였다. \"내가 북을 한 번 쳐 유약한 명나라 황제의 항복을 받고 쇠잔한 선우를 잡아 그 땅을 넓히리라[?].\" 하며 스스로 중군이 되어 밤낮으로 진군하니, 그 세력의 장함은 한 입으로 다 말할 수 없었다. 깃발과 창검은 가을 서리 같고, 북과 징 소리와 함성은 천지를 흔드는 듯하며, 장수의 갑옷은 햇빛을 희롱하니 누가 능히 당하겠는가. 가는 곳마다 대적할 자가 없었다. 여러 날 만에 중원 지경에 이르러 군사를 일으켜 공격하니 이르는 곳마다 주검이 무덤 같고 항복하지 않는 자가 없었다.","sp":[[3,6,"P","북흉노"],[48,51,"P","남선우"],[78,80,"P","북흉노"],[174,176,"P","북흉노"],[212,214,"P","천자"],[227,229,"P","남선우"]]},{"c":1,"sub":"","t":"연경 육십여 주의 항복을 받고 정군 칠십여 성의 항복을 받아 의기가 등등하여 백성을 노략하니, 창고의 곡식이 바닥나고 닭과 개까지 다 없어졌다. 정남관에 웅거하여 군사를 먹이고 장졸을 쉬게 하였다. 이때 황제는 해운의 장계를 보고 근심을 덜었는데, 뜻밖에 정남 절도사가 장계를 올렸다. \"북흉노가 강성하여 정병과 철기 일백삼십만을 일으켜 국경을 범하여 연경 육십여 성을 빼앗고 정남 칠십여 성의 항복을 받아 남관에 웅거하였습니다. 그 세력이 장하여 능히 당하지 못하여 황급히 장계를 올리니, 엎드려 바라건대 폐하께서는 나라의 군사를 일으켜 도적을 막으소서.\" 황제가 다 보시고 크게 놀라 얼굴빛을 잃으시고 곧 공부상서 곽태효를 원수로 삼아 군병 삼십만을 일으켜 북으로 진군하게 하였다. 이때 흉노는 가는 곳마다 대적할 자가 없었다. 목탁과 묵특을 좌우 선봉으로 삼고 통달을 후군장으로 삼아 하북으로 진군하여 삼십여 성을 쳐서 얻으니 누가 능히 대적하겠는가.","sp":[[114,116,"P","천자"],[118,120,"P","장애황"],[161,164,"P","북흉노"],[313,315,"P","천자"],[346,349,"P","곽태효"],[387,389,"P","북흉노"],[414,416,"P","묵특"],[429,431,"P","통달"]]},{"c":1,"sub":"","t":"이때는 기축년 10월 보름 무렵이었다. 나랏일이 어지러워 크게 근심하시니 조정이 진동하고 백성이 술렁였다. 날마다 나랏일을 의논하시는데 문득 하북 절도사 이동식이 장계를 올렸다. 뜯어보니 이렇게 쓰여 있었다. \"북흉노가 일백삼십만 군을 일으켜 국경을 범하여 연경 육십여 주와 정남 칠십여 성의 항복을 받고, 또 하북을 침범하여 삼십여 성을 빼앗았습니다. 형세가 당할 수 없고 힘이 미치지 못하여 머지않아 황성 지경을 범할 것이니 급히 막으소서.\" 황상께서 다 보시고 크게 놀라시니 조정이 어지러웠다. 유성장과 유진장을 모으고 각 도에 공문을 보내 군사를 거느리게 하였다.","sp":[[118,121,"P","북흉노"],[250,252,"P","천자"]]},{"c":1,"sub":"","t":"이때 곽태효가 상군에 이르러 군사를 쉬게 하고 있었는데, 흉노가 군사를 거느리고 상군에 이르렀다. 원수 곽태효가 격서를 전하자 흉노가 통달에게 명하여 북을 한 번 쳐서 원수를 사로잡고 성안으로 쳐들어가니 황제의 군대 장졸이 일시에 항복하였다. 흉노가 상군을 얻고, 이튿날 건주를 쳐서 얻고, 또 이튿날 환주를 쳐서 들어가니, 절도사 이동식이 군사를 거느리고 대적하다가 당하지 못하여 패하여 달아났다. 하북을 얻고 옥문관을 취하여 쉰 뒤 곧장 동정 북문을 깨뜨리고 기주로 들어가 스스로 천자라 일컫고 노략하니, 백성이 난을 만나 사방으로 흩어졌다.[?]","sp":[[3,6,"P","곽태효"],[32,34,"P","북흉노"],[58,61,"P","곽태효"],[71,73,"P","북흉노"],[75,77,"P","통달"],[114,116,"P","천자"],[136,138,"P","북흉노"],[271,273,"P","천자"]]},{"c":1,"sub":"","t":"이때 이 시랑 부인이 도망하여 한곳에 이르러 장미동 장 한림 댁 시비 난향을 만나 서로 의지하였다. 여러 날 만에 천축 땅에 이르니, 길가의 한 여승이 부인과 난향을 이끌어 갔다. 부인과 난향이 노승에게 사례하였다. \"난세를 만나 가족을 잃고 갈 곳을 몰라 죽게 된 목숨을 구해 주신 은덕을 어찌 갚기를 바라겠습니까.\" 하고 수없이 사례한 뒤 여승을 따라 봉명암에 들어가 머리를 깎고 중이 되었다. 부인과 난향이 스승과 상좌가 되어, 난향은 소저를 생각하여 밤낮으로 부처님 앞에 축원하고 눈물로 세월을 보냈다.[?]","sp":[[3,10,"P","양씨"],[29,33,"P","장화"],[39,41,"P","난향"],[85,87,"P","마고선녀"],[89,91,"P","난향"],[101,103,"P","마고선녀"],[105,107,"P","난향"],[109,111,"P","백운암 노승"],[223,225,"P","마고선녀"],[227,229,"P","난향"],[243,245,"P","난향"]]},{"c":1,"sub":"","t":"이때 대봉은 금화산 백운암에 있으면서 노승과 함께 갖가지 술법과 육도삼략이며 천문을 익혀 통달하고 신묘한 병서에 마음을 기울이니, 지모와 장략이 당대에 짝이 없었다. 큰 재주와 큰 지략을 지니고 산중에서 세월을 보내던 중, 하루는 화산 도사가 공자에게 말하였다. \"공자는 급히 세상에 나아가라. 원래 정해진 기한이 가까웠으니 급히 가야 하거니와, 간밤에 천기를 보니 각 별자리의 방위가 두서를 잡지 못하고 북방의 오랑캐 별이 중원을 범하였으니 시절이 크게 어지럽다. 급히 세상에 나가 중원에 이르러 황상을 도와 큰 공을 이루고, 이어 부모를 만나 보고 인연을 찾아 약속을 이루면 그대 마음속에 맺힌 한을 풀 것이다. 지체하지 말고 가라. 헤어지기 섭섭하지만 장부의 좋은 때를 어찌 놓치겠는가.\" 하며 재촉하였다. 공자가 물었다. \"황성이 얼마나 됩니까?\" 도사가 말하였다. \"중원이 여기서 일만 팔천육백 리요, 농서는 일천칠백 리이니 농서로 급히 가면 중원에 자연히 이를 것이다.\" 하고 바랑을 열어 과일을 주며 말하였다. \"가는 길에 몸이 고단하거든 요기하라.\"[?]","sp":[[3,5,"P","이대봉"],[21,23,"P","백운암 노승"],[50,52,"P","통달"],[129,134,"P","백운암 노승"],[279,281,"P","천자"]]},{"c":1,"sub":"","t":"하며 손을 잡고 몹시 서러워하며 뒷날의 기약을 당부하고 애틋하게 작별하였다. 공자가 행장을 차려 길을 떠나니 서로 놓지 못하는 정은 비할 데가 없었다. 이날 산문을 하직하고 농서를 바라고 풀밭에서 자고 이슬을 맞으며 밤낮으로 길을 재촉하였다.","sp":[]},{"c":1,"sub":"","t":"이때 흉노가 대병을 몰아 황성으로 쳐들어가니, 함성은 천지를 진동하고 깃발과 칼과 창은 해와 달을 희롱하였다. 큰 소리로 외치기를 \"명나라 황제는 옥새를 바삐 바쳐 남은 목숨을 보전하고, 가엾은 백성을 부질없이 상하게 하지 말라. 네가 만일 더디면 죽음을 면치 못하리라.\" 하고 물밀듯 들어오니 감히 대적할 자가 없었다. 황제가 몹시 다급하여 유성장을 일으켜 막으라 하였으나 반 합도 못 되어 패하였고, 또 병부시랑 진태열에게 명하여 막으라 하였으나 이 역시 싸우는 척하다가 달아났다. 조정에 있는 신하들은 처자만 생각하니 충신은 전혀 없고 자잘한 소인만 많은 조정에서 누가 사직을 받들겠는가. 형세가 급하므로 몇몇 군사를 거느리고 남성으로 도망하여 금릉으로 달아났다. 이날 흉노가 성안에 들어가 종묘와 사직에 불을 놓고 대궐 전상에 높이 앉아 호령하니 가을 서리 같았다. 통달이 군사를 몰아 천자의 뒤를 쫓아 금릉으로 가니, 슬프다, 대명의 사직이 억만년 이어 갈 나라로서 하루아침에 개돼지 같은 흉노에게 사직을 잃었으니 어찌 분하지 않겠는가. 누가 강한 적을 쓸어 없애고","sp":[[3,5,"P","북흉노"],[78,80,"P","천자"],[180,182,"P","천자"],[228,232,"P","진태열"],[233,236,"P","진태열"],[378,380,"P","북흉노"],[433,435,"P","통달"],[444,446,"P","천자"],[503,505,"P","북흉노"]]},{"c":1,"sub":"","t":"중원의 사직을 회복하겠는가. 이때 황제가 금릉으로 피하였는데, 오랑캐 병사가 뒤를 쫓아 들어와 몇 안 되는 군사를 마구 쳐 죽이니 누가 능히 막겠는가. 백성을 죽이며 황제를 찾아 거침없이 다니니 사방에 있는 것은 모두 달단 오랑캐 도적이었다. 이날 황제가 삼경에 도망하여 양성으로 가시는데 따르는 자는 불과 백 명이었다. 한심하다. 대명 천자가 이렇게 되었으니 밝은 하늘도 무심하고 강산의 신령도 헛것이었다. 양성에 들어가 밤을 지내는데, 양성 태수 장원이 군사 삼천을 거느리고 호위하므로 황제가 크게 기뻐하시어 양성 태수 장원을 선봉으로 삼고 황상께서 친히 중군이 되고자 하셨다. 이날 밤 날이 밝기 전에 문득 군마 소리가 요란하므로 오랑캐가 오는가 하여 크게 놀라 보니, 해남 절도사 장연이 정병 삼만을 거느리고 성 밖에 와 있었다.","sp":[[19,21,"P","천자"],[93,95,"P","천자"],[139,141,"P","천자"],[189,191,"P","천자"],[274,276,"P","천자"],[305,307,"P","천자"],[385,387,"P","장연"]]},{"c":1,"sub":"","t":"황상께서 크게 기뻐하시어 장연을 중군으로 정하시고 적의 형세를 알아보게 하니, \"오랑캐 적이 지경에 와 있습니다.\" 하고 보고하였다. 온 군사가 크게 놀라 천자를 모시고 양성을 버리고 능주로 가서 성 아래에 이르니, 능주 자사가 한 무리 군사를 거느리고 성 밖으로 나와 천자를 모셔 성안에 들어가 관사에 모시고, 성문을 굳게 닫고 쇠통같이 지켰다. 이때 도적이 양성으로 달려들어 천자를 찾았으나 성안이 고요하고 백성이 없었다. 성안에 들어가 알아보니 능주로 갔다 하므로, 묵특이 철기 삼천을 거느리고 능주로 쫓아와 곧장 성 아래에 이르러 소리를 높였다. \"명나라 황제는 부질없이 세상을 어지럽히지 말고 항서를 쓰고 옥새를 바쳐 목숨을 보존하고 백성을 편안케 하라. 우리 대왕은 하늘에서 명을 받아 사해를 평정하고 억조창생을 위하여 덕을 닦아 만승천자가 되셨으니, 천고에 없는 영웅은 우리 왕상뿐이로다.","sp":[[0,2,"P","천자"],[14,16,"P","장연"],[87,89,"P","천자"],[151,153,"P","천자"],[212,214,"P","천자"],[264,266,"P","묵특"],[315,317,"P","천자"],[417,419,"P","천자"]]},{"c":1,"sub":"","t":"지체하지 말고 항복하라.\" 이렇듯 의기양양하였다. 천자가 분부하셨다. \"적장의 적수가 없으니 성문을 굳게 지켜 도적이 성에 들지 못하게 하라.\" 문득 사방에서 티끌이 하늘을 찌르며 흉노군이 들어와 성을 에워싸고 싸우기를 재촉하였으나 맞서 싸울 장수가 없었다. 사방을 에워쌌으니 벗어날 길이 아득하였다. 흉노가 장수들에게 분부하였다. \"능주성을 에워싸고 화약과 염초를 준비하여 여덟 문의 장수들은 성 둘레를 한 자 다섯 치씩 땅을 파고 화약과 염초를 묻고 불을 놓아 성을 깨뜨리고 명나라 황제를 잡으라.\" 천자며 따르던 군사와 백성이 이 말을 듣고 몹시 당황하고 망극하여 울음소리가 푸른 하늘에 사무쳤다. 천자는 음식을 전혀 드시지 않고 자결하려 하셨는데, 호위하던 장수들이 위로하여 겨우 보존하셨으나 형세가 몹시 위태로웠다. 우승상 왕희가 간하였다. \"하늘의 운수가 불행하고 폐하의 덕이 적어 도적이 저절로 강성해지니 종묘와 사직을 받들기 어렵습니다. 엎드려 바라건대 폐하께서는 깊이 생각하시어 항서를 쓰고 옥새를 전하여 목숨을 보전하시고 억조창생을 건지소서.\"","sp":[[28,30,"P","천자"],[101,103,"P","북흉노"],[169,171,"P","북흉노"],[272,274,"P","천자"],[282,284,"P","천자"],[338,340,"P","천자"],[406,409,"P","이익"],[410,412,"P","왕희"]]},{"c":1,"sub":"","t":"하고, 또 병부시랑 진태열이 함께 아뢰었다. 황상께서 아무리 생각하셔도, 원수 해운은 수만 리 남쪽 선우를 치러 가 있고 형세는 급하니, \"짐의 덕이 없어 하늘이 망하게 하시는 것이다.\" 하시고 하늘을 우러러 탄식하셨다. 이날 왕희를 불러 항서를 쓰라 하시고, 옥새를 목에 걸고 왼손에 항서를 들고 오른손으로 가슴을 두드리며 황후와 태자를 어루만지며 말씀하셨다. \"이 몸은 하늘에 죄를 얻어 죽을 땅으로 들어가지만, 황후는 태자를 생각하여 귀한 몸을 보전하소서.\" 하며 서로 목을 안고 통곡하시니 하늘과 땅인들 어찌 무심하겠는가.","sp":[[6,10,"P","진태열"],[11,14,"P","진태열"],[25,27,"P","천자"],[44,46,"P","장애황"],[56,58,"P","남선우"],[127,129,"P","왕희"]]},{"c":1,"sub":"","t":"이때 대봉이 여러 날 만에 농서에 이르니 해가 서산에 지고 먹구름이 먼 하늘에 가득하여 지척을 분별하지 못하였고 몹시 고단하였다. 바위에 의지하여 날이 새기를 기다리는데, 삼경이 지나자 구름과 안개가 흩어지고 달이 떠올라 영롱하며 천지가 밝았다. 무심히 앉아 있는데 한 여인이 앞으로 들어와 보였다. 살펴보니 초록 저고리에 붉은 치마는 달빛을 희롱하고, 눈 같은 살결에 꽃 같은 얼굴은 백옥이 비친 듯하며, 자연스러운 태도와 황홀한 자색이 사람의 정신을 어지럽게 하였다. 대봉이 봉황 같은 눈을 부릅뜨고 크게 꾸짖었다. \"너는 어떤 계집이기에 한밤 삼경에 남자를 찾아왔느냐?\" 여인이 대답하였다. \"공자의 길이 적막하시기에 위로하고자 왔습니다.\" 대봉이 분명 귀신인 줄 짐작하고","sp":[[3,5,"P","이대봉"],[264,266,"P","이대봉"],[362,364,"P","이대봉"]]},{"c":1,"sub":"","t":"눈을 부릅뜨고 벼락같이 호통을 치니 문득 간 데가 없었다. 이윽고 풍채 좋은 선비가 푸른 비단 금포에 검은 띠를 두르고 들어오는데, 살펴보니 자연스러운 얼굴이 진평이나 한나라 동통보다 나았다. 귀신인 줄 알고 크게 꾸짖었다. \"너는 어떤 요망한 귀신이기에 대장부가 앉은 자리 앞에 감히 들어오느냐?\" 하니 무슨 소리가 나며 간 데가 없었다. 이윽고 천지가 어두워지고 우레와 벼락이 천지를 진동하며, 비바람이 크게 일어 나무가 부러지고 집이 뽑히며 모래가 날고 돌이 구르더니, 한 대장이 앞에 섰다. 살펴보니 월각 투구에 용린갑을 입고 긴 창과 큰 칼을 들고 우레 같은 소리를 천둥같이 지르며 바람을 따라 날뛰더니 해치려 하였다. 대봉이 정신을 가다듬어 얼굴빛을 변하지 않고 단정히 앉아 호령하였다.[?]","sp":[[352,354,"P","이대봉"]]},{"c":1,"sub":"","t":"\"삿된 것은 바른 것을 범하지 못하거늘[?], 너는 어떤 흉한 귀신이기에 요망한 행실로 장부의 절개를 굽히려 하느냐?\" 그 장수가 대답하였다. \"소장은 한나라 장수 이릉입니다. 그해 천자께 자원하여 군사 오천 명을 거느리고 싸움터에 나갔다가 흉노에게 해를 입어 속절없이 황천의 나그네가 되었고 또한 노예로 평생 욕을 입었으니[?] 마음속에 원한이 가득하여 하소연할 곳이 없었습니다. 마침 공자를 만나니 나의 원한을 풀 때가 왔습니다. 공자는 소장의 갑옷과 투구를 가져다 흉노를 베어 큰 공을 이루고 소장의 수천 년 원혼을 위로해 주시기 바랍니다.\" 하고 월각 투구와 용린갑을 바치며 말하였다. \"이 갑옷과 투구를 간수하여 급히 길을 떠나십시오.\"","sp":[[92,94,"P","이릉"],[102,104,"P","천자"],[135,137,"P","북흉노"],[263,265,"P","북흉노"]]},{"c":1,"sub":"","t":"하고는 그대로 간 곳이 없었다. 곧 길을 떠나 사흘 만에 평사에 이르니 사방에 사람 없이 적막한데 벼락 같은 소리가 났다. 자세히 살펴보니 강변에 난데없는 오추마가 내달아 네 굽을 허우적이며 번개같이 뛰놀다가 공자를 보고 반기는 듯하였다. 공자가 행장을 벗어 길가에 놓고 평사로 나아가 타일렀다. \"오추마야, 네가 대봉을 아느냐. 알거든 피하지 말라.\" 하며 달려들어 목을 안으니, 오추마가 대봉을 보고 고개를 숙이고 네 굽을 허우적이며 반기는 듯하였다. 대봉이 오추마의 목을 안고 강변에 이르니 황금 굴레와 은 안장이 놓여 있었다. 대봉이 반겨 굴레를 씌우고 안장을 갖추고 행장을 수습하여 오추마 위에 번뜻 올라 천기를 살펴보니, 북방의 오랑캐 별이 황성에 비쳐 있고 천자의 자미성은 도성을 떠나 능주에 잠겨 있었다. 대봉이 탄식하며 말에게 일렀다. \"밝은 하늘은 대봉을 내시고 용왕은 너를 내셨으니, 이는 천자의 급한 때를 구하게 하신 것이다.","sp":[[176,178,"P","이대봉"],[219,221,"P","이대봉"],[255,257,"P","이대봉"],[299,301,"P","이대봉"],[375,377,"P","천자"],[403,405,"P","이대봉"],[429,431,"P","이대봉"],[437,439,"P","서해 용왕"],[453,455,"P","천자"]]},{"c":1,"sub":"","t":"지금 도적이 황성에 들어왔으니 천자의 위급함이 경각에 달렸다. 이때를 놓치면 대명 천지에 이대봉이 쓸 곳이 전혀 없고, 나는 용 같은 조화를 지닌 너의 용맹도 세상에 내신 것은 사직을 위함이니 때를 놓쳐 쓸모없게 되면 쓸 곳이 어디 있겠느냐. 대봉이 품은 뜻을 펴게 되었으니[?] 어찌 반갑지 않으랴. 항우가 타던 용총마가 오강에 들어가 떠 있다가 대명의 대봉이 나니 나를 도우러 나왔구나.\" 이렇듯 기뻐하며 황성으로 올라가니, 사람은 천신 같고 말은 정녕 나는 용이었다. 이날 칠백 리 상군을 지나고 이튿날 일천삼백 리 하서를 지나니 황성이 장차 가까워졌다.","sp":[[17,19,"P","천자"],[50,53,"P","이대봉"],[136,138,"P","이대봉"],[199,201,"P","이대봉"]]},{"c":1,"sub":"","t":"여러 날 만에 화룡도에 이르니 밤이 이미 삼경이었다. 천지가 아득하며 비바람이 크게 일어 지척을 분별하지 못하여 머뭇거리는데, 길가에 빈집이 있어 그 집에 들어가 잠깐 쉬었다. 문득 천병만마가 나오더니 그 집을 에워싸 진을 쳤다. 자세히 살펴보니 진법은 팔진도였다. 그 가운데 한 대장이 낯빛은 무르익은 대추 빛 같고 눈썹은 하늘을 덮을 듯하며, 황금 투구에 녹포운갑을 입고 청룡도를 비껴 들고 적토마를 빨리 몰아 봉황 같은 눈을 부릅뜨고 삼각 수염을 거스르며 그 집으로 들어왔다. 대봉이 정신을 수습하여 팔괘를 벌여 놓고 단정히 앉아 있으니, 그 장수가 곁에 와서 크게 외쳤다. \"대봉아, 네가 세상을 평정하고 큰 공을 이루려면 지혜와 도략을 써야 하거늘, 한갓 담대함만 믿고 남의 집 주인을 알지 못하고 거만하게 앉아 있느냐?\" 대봉이 일어나 엎드려 사례하였다. \"장군의 존호를 어찌 알겠습니까. 소자가 나이 어려 빈집의 주인을 알지 못하고 손님의 예를 잃었으니, 엎드려 바라건대 장군께서는 용서하시고 뜻을 이루게 해 주소서.\"","sp":[[270,272,"P","이대봉"],[326,328,"P","이대봉"],[410,412,"P","이대봉"]]},{"c":1,"sub":"","t":"그 장군이 말하였다. \"나는 한수정후 관운장이다. 삼국 시절에 조조와 손권을 잡아 우리 어진 주인의 은덕을 갚고자 하였으나 하늘의 운수가 불행하여 천하를 평정하지 못하고 여몽의 흉계에 속절없이 죽었다. 원통하다, 청룡도는 쓸 곳이 전혀 없고, 슬프다, 적토마는 먹지 않고 굶어 죽었다[?]. 황천의 지친 혼이 이 집에 의지하여 옛 땅을 지키고 있었는데, 오늘 너를 보니 당대의 영웅이다. 내가 쓰던 청룡도를 줄 것이니 능주로 급히 가서 사직을 보전하고, 흉노의 피로 청룡도를 씻어 영웅의 원혼을 위로하라.\" 하고 주므로 받아 들고 사례하니 문득 간 데가 없었다. 대봉의 급한 마음은 일각이 삼 년 같았다. 월각 투구에 용린갑을 입고 청룡도를 비껴 들고 만 리 준총에 비껴 타고 비바람같이 달려가며 말에게 일렀다. \"오추야, 너는 알리라.","sp":[[16,20,"P","관운장"],[21,24,"P","관운장"],[254,256,"P","북흉노"],[315,317,"P","이대봉"]]},{"c":1,"sub":"","t":"천자의 급하심과 대장부의 급한 마음을 네 이미 모르겠느냐. 천지가 감응하시어 너와 나를 내셨으니, 능주에 이르러 대봉의 용총마의 날랜 용맹과 청룡도의 날랜 칼로 도적을 물리치고 사직의 충신이 되면, 천추에 빛나는 이름을 기린각 제일층에 새길 때 내 이름을 새긴 뒤에 오추마 너의 행적도 나를 따라 빛나리라. 지체하지 말고 어서 가자.\" 오추마가 이윽히 듣더니 말이 능주로 달려가는데, 오추마의 날랜 용맹은 샛별 같은 두 눈에 바람과 구름의 조화가 어려 있고 둥근 네 굽에는 강산의 정기를 감추었도다. 대운산을 넘어 양주를 지나 운주역에서 말을 먹이고, 계천강을 건너 앵무주를 지나 봉황대에 이르니 해가 거의 서산에 지고 있었다.[?]","sp":[[0,2,"P","천자"],[63,65,"P","이대봉"]]},{"c":1,"sub":"","t":"여산 능주에 이르러 산 위에 높이 올라 진세를 살펴보니, 중원의 사람은 보이지 않고 십 리 모래사장에 오랑캐 병사가 가득하여 이긴 기세가 등등하고 살기가 가득하며 함성이 크게 일었다. 오랑캐 장수 묵특이 북문을 깨뜨리고 철기를 몰아 성안으로 달려들어 마구 치며 \"명나라 황제야, 항복하라.\" 외치는 소리가 강산이 무너지는 듯하였다. 이때 천자는 도적의 세력을 당하지 못하여 형세가 매우 급하였다. 하릴없이 옥새를 목에 걸고 항서를 손에 들고 항복하러 나오셨다.","sp":[[110,112,"P","묵특"],[151,153,"P","천자"],[189,191,"P","천자"]]},{"c":2,"sub":"리ᄃᆡ봉젼하(李大鳳傳下)","t":"이때 대봉이 산 위에서 그 모습을 보고 분기가 하늘을 찔러 월각 투구에 용린갑을 입고 청룡도를 높이 들고 나는 용 같은 말 위에 번뜻 올라 봉황 같은 눈을 부릅뜨고 천둥 같은 소리를 지르며 외쳤다. \"반적 묵특은 빨리 나와 나의 날랜 칼을 받으라.\" 그 소리에 적진의 장졸이 넋을 잃어 대오를 분별하지 못하였다. 묵특이 이 말을 듣고 분기가 하늘을 찔러 크게 외쳤다. \"너 이름 없는 저 장수야, 하늘의 위엄을 모르고 큰소리를 하느냐.\" 하며 서로 싸우는데, 한 합도 못 되어 대봉의 청룡도 날랜 칼이 공중에 번뜩이며 묵특의 머리가 칼빛을 따라 말 아래로 떨어졌다. 대봉이 크게 외치며 묵특의 머리를 칼끝에 꿰어 들고 적진 가운데를 거침없이 다니며 좌충우돌하다가 본진으로 돌아왔다.","sp":[[3,5,"P","이대봉"],[115,117,"P","묵특"],[175,177,"P","묵특"],[267,269,"P","이대봉"],[290,292,"P","묵특"],[317,319,"P","이대봉"],[328,330,"P","묵특"]]},{"c":2,"sub":"","t":"이때 천자는 형세가 궁하고 힘이 다하여 옥새를 목에 걸고 항서를 손에 들고 용포를 벗고 평복 차림으로 나오시는데, 난데없는 한 대장이 묵특의 목을 베어 들고 나는 듯이 본진으로 들어오더니 말에서 내려 황상 앞에 하늘을 부르며 통곡하고 엎드려 아뢰었다. \"소장은 기주 땅 모란동에 살던 전 시랑 이익의 아들 대봉입니다. 불행히 폐하께 죄를 얻어 먼 곳으로 쫓겨나는데, 강 위에서 사공 놈의 해를 입어 부자가 물에 빠져 아비는 바닷속에서 죽고 소신은 다행히 살아나 천축국 금화산 백운암의 부처 같은 중을 만나 칠 년을 의지하였습니다. 약간의 지략을 배우며 세월을 보내다가 이때를 당하여 폐하를 도와 사직을 보전하고, 간신을 물리치고 소신의 아비를 모해한 소인을 잡아 평생의 원수를 갚고, 조정을 밝혀 사해를 평정하고자 왔습니다. 엎드려 바라건대 폐하께서는 너무 슬퍼하지 마소서.\"","sp":[[3,5,"P","천자"],[75,77,"P","묵특"],[112,114,"P","천자"],[161,163,"P","이익"],[164,166,"P","이익"],[171,173,"P","이대봉"]]},{"c":2,"sub":"","t":"황상께서 대봉의 손을 잡고 말씀하셨다. \"짐이 밝지 못하여 소인의 말을 듣고 충의로운 대신을 멀리 귀양 보내고 소인을 가까이하여 나라가 어지러운데도 사직을 받들 신하가 없어 태평과를 보였더니, 마침 장해운을 얻어 짐의 뜻을 이루었다. 그런데 나라의 운수가 불행하고 짐에게 덕이 없어 곳곳에 도적이 강성해져, 남선우가 반하여 백만 대병을 거느리고 변방을 범하여 백성을 노략하므로 해운을 상장으로 삼아 군병을 거느리고 수만 리 남쪽으로 보냈더니, 싸움에 이기고 또 선우를 쫓아 교지국으로 갔다. 그래서 조정에 명장이 없고 지모 있는 선비가 없어 근심하던 차에 또 북흉노가 강성하여 강병을 거느리고 쳐들어오니 능히 당할 자가 없어 도적에게 사직을 빼앗기고 장안을 버리고 금릉으로 피하였다. 적병이 금릉을 마구 치므로 양성으로 피하였더니 또 양성을 범하니","sp":[[0,2,"P","천자"],[5,7,"P","이대봉"],[111,114,"P","장애황"],[172,175,"P","남선우"],[211,213,"P","장애황"],[258,260,"P","남선우"],[313,316,"P","북흉노"]]},{"c":2,"sub":"","t":"견디지 못하고 이곳으로 피하였다. 각처 제후 가운데 해남 절도사가 한 무리 군사를 거느리고 오고 양성 태수가 삼천 군을 거느리고 능주로 오니, 자사가 한 무리 군사를 거느리고 나와 합세하여 성안에 들어와 성문을 굳게 닫고 군사로 성을 지켰다. 흉노가 대군을 몰아 성안에 들어가 종묘에 불을 놓고 스스로 천자라 일컬으며 백관을 호령하고, 대군을 보내 능주성을 에워싸고 화약과 염초를 준비하여 성을 깨뜨리려 하였다. 그 세력을 당하지 못하고 가엾은 백성이 가련하여 항서를 쓰고 옥새를 넘겨주어 억조창생을 건질까 하여 나왔는데, 밝은 하늘이 도우시어 그대를 대명에 내시니 이같이 급한 때를 당하여 짐의 쇠진한 목숨을 구하였구나. 천지가 다시 밝아졌다.\" 하시며 손을 잡고 들어가 장대에 앉히고 말씀하셨다. \"장군이 짐을 도와 천하를 평정한 뒤에 할 말이 많을 것이다.\" 하시고 부끄러워하심을 마지않으셨다. 대봉이 엎드려 아뢰었다. \"지금 형세가 위급하니 폐하께서는 진정하소서.","sp":[[136,138,"P","북흉노"],[169,171,"P","천자"],[448,450,"P","이대봉"]]},{"c":2,"sub":"","t":"소장이 비록 재주는 없으나 마음을 다하여 폐하를 도와 평정하고 사직을 보전한 뒤에 소장의 원한을 풀고자 하니, 엎드려 바라건대 황상께서는 옥체를 보전하시고 소장의 장략을 보소서.\" 황상께서 몹시 기뻐하시고 중군에 분부하여 칠성단을 높이 쌓아 방위를 정돈하게 하셨다. 천자가 대봉의 손을 잡고 단 위에 올라 하늘에 제사하고 대봉을 봉작하시니, 대명국 대원수 겸 충의대장 병마도총독 겸 충위행원후 상장군에 봉하시고, 황금 인끈과 대장의 절월, 봉작 문서를 함께 봉하여 전해 주시며 말씀하셨다. \"짐의 밝지 못함을 허물하지 말고 충성을 다하여 사해를 평정하면 천하를 반으로 나누리라.\" 원수가 하늘 같은 은혜에 감사하여 머리를 조아려 사례하고 장대로 나와 장수와 군졸을 점검하니,[?]","sp":[[71,73,"P","천자"],[101,103,"P","천자"],[149,151,"P","천자"],[153,155,"P","이대봉"],[180,182,"P","이대봉"]]},{"c":2,"sub":"","t":"지친 군사와 장졸이 불과 삼백이었다. 원수가 중군장 장연을 불러 분부하였다. \"진중에 장수가 없고 군사가 잔약하니 너는 방위를 정돈하고 대오를 잃지 말라. 흉노의 억만 대병이 아홉 산같이 쌓였으나 내가 능히 당적하리니 장졸은 동요하지 말라.\" 하고 진법을 시험하였다. 〇동방 청기 일곱 면에는 각·항·저·방·심·미·기 별자리를 응하게 하고, 〇남방 적기 일곱 면에는 두·우·여·허·위·실·벽을 응하게 하고, 〇서방 백기 일곱 면에는 규·루·위·묘·필·자·삼을 응하게 하고, 〇북방 흑기 일곱 면에는 정·귀·유·성·장·익·진을 응하게 하고, 〇가운데에는 황신기를 세워 오방의 깃발을 방위에 벌여 세우니 이는 제갈무후의 팔진이었다. 진세를 살펴보니 귀신도 헤아리지 못할 정도였다. 이때 흉노는 장대에 높이 앉아 승전고를 울리며 항복을 재촉하는데, 문득 우레 같은 소리가 천둥같이 들렸다.","sp":[[29,31,"P","장연"],[87,89,"P","북흉노"],[382,384,"P","북흉노"]]},{"c":2,"sub":"","t":"살펴보니 한 대장이 월각 투구를 쓰고 용린갑을 입고 오른손에는 청룡도를 들고 봉황 같은 눈을 부릅뜨고 왼손에 채찍을 들고 오추마를 비껴 타고 들어오는데, 위엄은 서리와 눈 같고 목소리는 웅장하여 강산이 무너지는 듯하며 단산의 사나운 범이 장수를 치는 듯하였다. 순식간에 달려들어 호통 한 소리에 선봉장 묵특을 베어 들고 선봉을 짓쳐 성안으로 들어가자, 흉노가 크게 놀라 장수들을 모아 의논하였다. \"그 장수의 용맹을 보니 범상한 장수가 아니다. 사람은 천신 같고 말은 보니 오추마요 칼은 보니 청룡도라, 분명한 명장이니 가볍게 대적하지 못하리라.\" 팔십만 병을 일시에 벌여 세워 안팎으로 음양진을 치고, 목탁을 선봉으로 정하고, 통달을 우선봉으로, 달수를 좌선봉으로, 돌통을 후군장으로, 맹통을 군사마로 삼아 군대의 대오를 정돈하였다. 진문에 깃발을 세우고 흉노가 친히 중군이 되어 싸움을 돋우었다.","sp":[[169,171,"P","묵특"],[197,199,"P","북흉노"],[352,354,"P","통달"],[424,426,"P","북흉노"]]},{"c":2,"sub":"","t":"이때 대원수가 진세를 벌이고 적진의 형세를 살펴보니, 흉노는 목탁에게 장안을 지키게 하고 자신은 스스로 중군이 되어 장대에 높이 앉아 싸움을 돋우었다. 원수가 말을 타고 나가 응하여 진 앞에 나서며 소리를 높여 크게 꾸짖었다. \"개 같은 오랑캐야, 네가 하늘의 위엄을 범하여 세상을 어지럽히니 죽어도 죄가 남고, 황제를 욕보이고 스스로 천자라 일컬으니 한 하늘 아래 어찌 천자가 둘 있겠느냐. 내가 하늘에서 명을 받아 너 같은 반적을 쓸어 없앨 것이니, 네가 만일 두렵거든 빨리 나와 항복하고 그렇지 않거든 빨리 나와 대적하라.\" 흉노가 통달을 불러 대적하라 하니 통달이 내달아 외쳤다. \"어린아이 대봉아, 너는 하늘의 때를 모르는구나. 불행하여 우리 선봉은 죽었지만 네 청춘이 아깝구나.\" 하며 달려들었다. 원수가 분노하여 적장을 취하는데, 반 합도 못 되어 고함 소리가 진동하며 청룡도가 번뜩여 통달의 머리를 베어 들고 좌충우돌하니 군사의 주검이 무덤 같았다.","sp":[[30,32,"P","북흉노"],[175,177,"P","천자"],[188,190,"P","천자"],[208,210,"P","천자"],[297,299,"P","북흉노"],[301,303,"P","통달"],[316,318,"P","통달"],[335,337,"P","이대봉"],[447,449,"P","통달"]]},{"c":2,"sub":"","t":"칼끝에 꿰어 적진에 던지며 말하였다. \"반적 흉노야, 네가 어찌 살기를 바라겠느냐. 빨리 나와 죽기를 대령하라.\" 천둥같이 호령하며 선봉을 짓치니, 흉노가 크게 놀라 돌통에게 대적하라 하고 맹통·동철·동기 등 여덟 장수에게 명하여 접응하라 하였다. 이때 원수가 선봉을 짓치다가 바라보니 적장 돌통이 여덟 장수를 거느리고 나오며 외쳤다. \"너는 무슨 용맹이 그리 넉넉하냐. 만일 부족하거든 항복하라.\"","sp":[[25,27,"P","북흉노"],[83,85,"P","북흉노"]]},{"c":2,"sub":"","t":"원수가 크게 노하여 필마단창으로 달려들어 싸우는데, 천자가 군사를 거느리고 싸움을 구경하시고 두 진의 군사들도 큰 싸움 구경이 처음이라 서로 다투어 보았다. 명나라 진의 대원수가 오랑캐 장수 아홉을 맞아 싸우는데, 월각 투구와 용린갑은 햇빛을 희롱하고 엄장한 청룡도는 동쪽 하늘에 번뜻하면 백호를 베고, 서쪽 하늘에 번뜻하면 청룡을 베고, 남쪽에 번뜻 현무를 베고, 북쪽에 번뜻 주작을 벤다. 청룡도 날랜 칼빛은 한수정후가 가지고 쓸 때에 형주성에 빛나더니, 이번에 대원수에게 와서는 다시 빛나는 청룡도로다[?]. 대원수의 날랜 풍모로 서리와 눈 같은 청룡도를 오른손에 비껴 들고 오추마를 높이 타고 군중을 달리는 모습은 동해의 청룡이 구름 속에서 꿈틀거리는 듯하였다. 사정없는 청룡도가 공중에 번뜩이자 오랑캐 적이 쓰러지니, 번개같이 날랜 칼은 능주성에 빛이 났다. 이십여 합에 이르러 중군으로 가는 듯하다가 선봉장 돌통을 베어 들고 여덟 장수를 대적하니, 여덟 장수가 능히 당하지 못할 줄 알고 본진으로 달아나려 하였다. 원수가 소리를 높였다. \"무지한 적장은 달아나지 말라. 내가 너희를 이기고자 하여 다섯 장수를 먼저 베었는데 끝내 항복하지 않으니 분하도다.\"","sp":[[29,31,"P","천자"],[231,235,"P","관운장"]]},{"c":2,"sub":"","t":"하며 달려드니 노선·동기 등 네 장수가 맞아 싸웠다. 청룡도가 번뜩이며 노선의 머리를 베어 본진에 던지고, 왼편으로 가는 듯하다가 동기 등 세 장수를 베어 본진에 던지고, 선봉진으로 달려들어 군사를 짓찌르니 구시월 나뭇잎이 서리 바람을 만나 떨어지듯 하여 피가 흘러 내를 이루었다. 흉노가 크게 놀라 맹통과 동철에게 대적하라 하니, 두 장수가 내달아 맞붙어 싸울 때 칼빛은 햇빛을 희롱하고 말굽은 어지러웠다. 세 장수의 고함 소리에 군졸들이 넋을 잃어 대오를 분별하지 못하였다. 원수가 말을 채찍질하여 공중으로 솟더니 청룡도가 번뜩이며 두 장수의 머리가 칼빛에 싸여 떨어졌다. 원수가 이긴 기세가 등등하여 동서로 치달으며 \"적장이 얼마나 남았거든 급히 나와 대적하라.\" 외치는 소리가 진동하였다. 흉노는 또 장수들을 호령하여 진세를 더욱 굳게 하고,","sp":[[158,160,"P","북흉노"],[390,392,"P","북흉노"]]},{"c":2,"sub":"","t":"맹조·맹주·영인 등 여덟 장수를 급히 불러 \"정병 삼십만과 철기 십오만을 거느리고 군사를 합세하여 명나라 진의 대원수를 잡아 나의 분을 풀게 하라.\" 하였다. 여덟 장수가 명을 받들고 군사를 벌여 사방으로 둘러쳐 들어오며 명나라 진을 겁박하려 하였다. 원수가 이때 본진에 돌아가 잠깐 쉬고 있었는데, 적병이 물밀듯 들어오므로 크게 노하여 말하였다. \"내 결단코 흉노를 사로잡아 황상의 분을 씻으리라.\" 노기가 하늘을 찔러 월각 투구와 용린갑을 여미고 봉황 같은 눈을 부릅뜨고 청룡도를 비껴 들고 오추마 위에 번뜻 올라 진문 밖에 나서니, 적장이 외쳤다. \"명나라 황제야, 네가 항복하는 것이 옳거늘 조그마한 아이 대봉을 얻어 우리의 큰 세력을 모르고 분수없이 침범하여, 우리 진중의 이름 없는 장수 수십 명을 죽이고 승전을 자랑하니","sp":[[202,204,"P","북흉노"],[211,213,"P","천자"],[315,317,"P","천자"],[343,345,"P","이대봉"]]},{"c":2,"sub":"","t":"가히 우습구나.\" 하며 \"명나라 진 상장군 대봉아, 빨리 나와 대적하라. 만일 겁나거든 말에서 내려 항복하여 죽음을 면하고, 그렇지 않으면 빨리 나와 죽기를 재촉하라.\" 하며 물밀듯 들어왔다. 이날 원수가 분기가 하늘을 찔러 필마단창으로 말을 채찍질하여 적진에 달려들어 여덟 장수와 싸우는데, 서로 나아가고 물러나기를 오십여 합에 승부가 나지 않았다. 원수가 노기가 등등하여 천둥같이 호통을 지르고 청룡도를 높이 들어 앞을 짓찌르니 여덟 장수가 일시에 달려들었다. 원수가 적진으로 돌출하여 청룡도가 번뜩이자 노선과 맹주 두 장수의 머리가 말 아래로 떨어지고, 또 뒤로 가는 듯 앞에 번뜻 칼빛이 일어나며 적장의 머리가 칼빛을 따라 떨어지고, 왼편에 번뜻 오른편으로 나며 칼빛이 번뜻 맹주를 베고, 앞에 번뜻 뒤로 나며 영인을 베어 들고, 중진에 번뜻 동쪽으로 나며 문영과 문수 두 장수를 베고, 적진의 장졸을 썩은 풀 베듯 짓치며 거침없이 다녔다.","sp":[[24,26,"P","이대봉"]]},{"c":2,"sub":"","t":"초나라 항 장군이 강동 팔천 자제를 거느리고 오강을 건너와 함곡관을 부수는 듯, 상산 땅 조자룡이 장판교 큰 싸움에서 삼국의 정병을 짓치는 듯하니, 흉노의 백만 대병이 대오를 분별하지 못하였다. 청룡도의 날랜 칼빛은 하늘에 어려 있고, 오추마가 달리는 앞에 대적할 자가 누가 있으랴. 우레 같은 호통 소리는 푸른 하늘에 메아리치며 좌충우돌 거침없이 다니니 적군이 겁에 질려 칼빛을 따라 스러지니, 비유하자면 푸른 하늘에 어린 먹구름이 바람결에 몰리는 듯하였다. 중군으로 달려드니 흉노가 크게 놀라 얼굴빛을 잃고 군사를 거느리고 장안으로 도망하였다. 뒤를 쫓아 마구 치니 흉노의 백만 병이 싸우다 달아나는구나. 오추마가 달리는 곳에 적진 장졸의 머리가 칼빛을 따라 떨어지니, 이르자면 구월 강산을 두른 초목이 서리 바람에 낙엽 지는 듯하여 적의 주검이 산 같으니 가련하다.[?]","sp":[[83,85,"P","북흉노"],[268,270,"P","북흉노"],[319,321,"P","북흉노"]]},{"c":2,"sub":"","t":"흐르는 것은 피라. 피가 흘러 내를 이루니 무릉도원의 붉은 물이로다. 사납던 저 흉적은 사나움도 쓸데없고 백만 대병도 소용없다. 단출하다, 원수의 행장이여, 필마단창을 당하지 못하고, 포악한 저 도적이 의기양양 강성하더니 밝은 하늘이 도우시어 대명이 회복되니 반갑구나, 군사와 백성의 노래로다. 이때 오랑캐 장수 특탈이 도성을 지키고 있었는데, 흉노의 급한 형세를 보고 군병을 거느려 장졸을 합세하여 백사장에 진을 치고 원수를 대적하려 하니, 진의 강병은 모두 오랑캐 적이었다[?]. 이때 원수가 적군을 물리치고 본진으로 돌아오니, 천자가 대 아래로 내려와 원수의 손을 잡고 기뻐하며 몹시 사랑하셨고, 장수와 군졸들도 백 번 절하여 사례하며 수없이 기뻐하고 덕을 칭송하였다. 원수가 말하였다.","sp":[[193,195,"P","북흉노"],[298,300,"P","천자"]]},{"c":2,"sub":"","t":"\"도적이 멀리 가지 않았으니 적진에 가서 군장과 기계를 거두어 본진의 병기와 합하라.\" 하고 중군을 불러 \"너는 여러 군의 장졸을 거느리고 황상을 모시고 후군이 되어 내 뒤를 따르라. 나는 필마단검으로 적진에 들어가 장졸을 무찌르고 흉노를 사로잡아 황상의 분하심을 풀리라.\" 하고 말을 채찍질하여 흉노를 쫓아 도성에 이르니, 도적이 십 리 평사에 진을 치고 군호를 엄숙히 하고 있었다. 자세히 살펴보니 남은 군사가 팔십여만이었다. 원수가 이긴 기세를 타고 크게 외쳤다. \"반적 흉노야, 네가 끝내 항복하지 않고 나와 자웅을 겨루고자 하니 분하도다.\"","sp":[[78,80,"P","천자"],[130,132,"P","북흉노"],[139,141,"P","천자"],[166,168,"P","북흉노"],[267,269,"P","북흉노"]]},{"c":2,"sub":"","t":"하고 청룡도를 높이 들고 용총마 위에 번뜻 올라 우레같이 호통하며 달려들었다. 이때 적진에서 서른여섯 장수가 합세하고 군사를 정돈하여 원수를 에워싸고 좌우로 치자, 원수가 크게 노하여 용맹을 떨쳐 청룡도 드는 칼로 적장 십여 명을 베고 진중으로 달려들어 군사를 짓찔렀다. 적장들이 달려들어 좌우로 에워싸자 청룡도가 번뜩이며 적장 여덟을 베어 들고, 팔십여 합을 싸워 적장 삼십여 명을 베었다. 또 중군으로 달려드니 한 장수가 나와 맞서는데, 한 소리 높은 고함에 칼빛이 번뜩이더니 적장을 베어 들고 사방으로 치달으니 사방이 모두 원수였다. 오추마의 함성 소리는 칼빛을 따라 일어나고 원수의 호령 소리는 하늘에 진동하니, 제아무리 강병인들 누가 능히 당하겠는가. 장졸의 주검이 아홉 산같이 쌓이고 십 리 모래사장에 피가 흘러 모래를 물들이고, 남은 피는 말굽을 적셨다. 용린갑에 뜬 피는 소상강 대숲에 가랑비가 맺혀 떨어지듯 점점이 맺혀 있었다. 이때 흉노는 형세가 매우 급하여 얼마 남지 않은 장졸을 거느리고 샛길로 도망하여 북쪽으로 달아났다.","sp":[[476,478,"P","북흉노"]]},{"c":2,"sub":"","t":"가련하다. 흉노의 일백삼십만 병 가운데 살아 돌아가는 자가 삼천도 되지 못하였다. 칼 하나로 정벌하여 평정하는 일[?]을 오늘에야 보겠구나. 원수가 적병을 깨뜨리고 군장과 기계를 거두어 성에 들어가 천자를 모셔 환궁하고 백성을 편안케 하니, 성 안팎의 백성들이 원수의 덕을 칭송하며 기뻐하였다. 이때 원수가 장수들을 모아 군문에서 군사를 먹이고 위로한 뒤, 황제께 들어가 말미를 청하고 기주로 내려가 살던 집을 찾아보니, 높은 누각과 넓은 집은 빈터만 남았구나. 옛일을 생각하고 부모를 생각하니","sp":[[6,8,"P","북흉노"],[111,113,"P","천자"],[144,148,"P","이대봉"],[200,202,"P","천자"]]},{"c":2,"sub":"","t":"쓸쓸한 마음이 저절로 났다. 말에서 내려 앉아 소리 높여 크게 울며 말하였다. \"우리 아버지가 나라에 바른말로 간하다가 소인의 참소를 만나 만 리 귀양길에 부자가 함께 가다가, 무도한 뱃사람 놈의 해를 입어 천 리 바다 깊은 물에 부자가 함께 빠졌는데, 대봉은 다행히 용왕의 덕을 입어 살아났다. 천지신령이 도우시어 대원수 상장이 되어 오랑캐 적을 깨뜨리고 살던 집을 찾아오니 빈터만 남았구나. 상전벽해라는 말은 나를 두고 이른 말이로다. 가련하다, 우리 어머니가 집을 지키고 계시더니 흉적의 난을 만나 죽었는지 살았는지, 언제 나를 만나 보실까.\" 가슴을 두드리며 하늘을 우러러 통곡하고 황성으로 올라가 황제께 절하니, 황상께서 크게 칭찬하여 마지않으시고 대궐 안에 큰 잔치를 베풀어 원수의 공을 크게 치하하셨다. 원수가 아뢰었다.","sp":[[142,144,"P","이대봉"],[150,152,"P","서해 용왕"],[339,341,"P","천자"],[348,350,"P","천자"]]},{"c":2,"sub":"","t":"\"그 가운데 승상 왕희는 없습니까?\" 이때 왕희가 스스로 죄를 알고 대 아래로 내려와 엎드려 죄를 청하였다. 원수가 크게 노하여 청룡도를 겨누면서 말하였다. \"너는 나와 하늘을 함께 이고 살 수 없는 원수이니 이 자리에서 죽일 것이로되, 흉노를 잡아 사해를 평정한 뒤에 죽일 것이니 잠시 용서하노라.\" 하고 옥에 가두라 하였다. 그리고 황상께 아뢰었다. \"흉노가 비록 패하여 갔으나 후환을 알 수 없으니 소장이 필마단창으로 오랑캐 나라에 들어가 흉노를 잡아 후환이 없게 하겠습니다.\" 황상께서 크게 칭찬하며 말씀하셨다. \"원수는 곧 짐의 손발이다. 만일 가서 더디 오면 내 어찌 잠자리와 식사가 편하겠는가.\" 원수가 대답하였다. \"빨리 돌아와 폐하를 모실 것이니 너무 근심하지 마소서.\" 하고 백관을 호령하여 황상을 편안히 모시라고 당부한 뒤, 필마단창으로 만 리 오랑캐 나라로 가려 하였다. 천자와 조정 백관이 반정까지 나와 전송하며 만 리 먼 땅에서 무사히 돌아오기를 천만 당부하시니, 원수가 은혜에 감사하고 하직하여 길을 떠나 흉노를 쫓아갔다.[?]","sp":[[7,9,"P","왕희"],[10,12,"P","왕희"],[24,26,"P","왕희"],[133,135,"P","북흉노"],[188,190,"P","천자"],[199,201,"P","북흉노"],[249,251,"P","북흉노"],[271,273,"P","천자"],[397,399,"P","천자"],[444,446,"P","천자"],[522,524,"P","북흉노"]]},{"c":2,"sub":"","t":"한편 장 원수는 배를 준비하여 여러 날 만에 군사를 거느리고 교지국으로 들어갔다. 이때 선우는 본국에 들어와 남만 다섯 나라에 군사를 청하는 패문을 보내고 군사를 다시 정돈하고 있었는데, 뜻밖에 명나라 대원수가 대병 팔십만을 거느리고 들어왔다. 선우가 군사를 거느리고 막다가 당하지 못하자 항서와 예물을 갖추어 성 밖으로 나와 항복하였다. 원수가 크게 꾸짖었다. \"네 죄상을 따지면 죽여 마땅하나, 이른바 항복한 자는 죽이지 않는다 하였으므로 십분 용서한다. 이후로는 분수에 넘치는 뜻을 두지 말고 천자를 섬기라.\" 하고 항서와 예물을 받았다. 선우의 성안에 들어가 소와 양을 잡아 군사를 먹이고 위로하며, 중군에 분부하여 장졸을 편히 쉬게 하고 원수도 갑옷과 투구를 벗고 며칠 머물렀다. 하루는 원수가 선우를 불러 \"내 이제 남만을 쳐서 멸할 것이니 그대는 나의 격서를 남만 다섯 나라에 전하라.\" 하니 선우가 명을 받들었다.","sp":[[3,7,"P","장애황"],[49,51,"P","남선우"],[137,139,"P","남선우"],[279,281,"P","천자"],[305,307,"P","남선우"],[394,396,"P","남선우"],[451,453,"P","남선우"]]},{"c":2,"sub":"","t":"남만 다섯 나라는 곧 선우의 패문을 보고 머뭇거리며 결정하지 못하던 차에, 명나라 대원수가 교지국에 들어와 선우의 항복을 받고 격서를 보내왔다. 뜯어보니 이렇게 쓰여 있었다. \"천조의 한림 겸 예부시랑 대원수 병마도총독 상장군은 황명을 받아 반적 선우의 항복을 받고 남만으로 간다. 만일 항복하여 하늘의 명에 순종하지 않으면 곧 팔십만 대병을 거느리고 군사를 일으켜 칠 것이니 곧 답하라.\" 다섯 나라 왕이 다 보고 선우를 원망하며 각각 바칠 예물을 갖추고 항서를 써서 사신을 교지국으로 보내 항복하였다. 원수가 군대의 대오를 갖추고 군사를 벌여 안팎으로 음양진을 치고 갑옷을 선명하게 하며, 장수들은 오방 깃발 아래 각각 말을 타고 창검을 높이 들어 나는 듯이 세우고, 진문을 크게 열어 다섯 나라 사신을 들여 앞뒤 일을 묻고 항서와 예물을 받은 뒤 후하게 대접하여 보냈다. 다섯 나라 사신이 돌아가 그 위엄을 각각 자기 왕께 아뢰니, 항복한 것을 다행으로 알았다.","sp":[[12,14,"P","남선우"],[60,62,"P","남선우"],[103,105,"P","장화"],[110,112,"P","이익"],[138,140,"P","남선우"],[233,235,"P","남선우"]]},{"c":2,"sub":"","t":"이때 장 원수가 너덧 달 만에 교지국을 떠나 진군하여 여러 날 만에 남해에 이르러 평사에 진을 치고, 가까운 고을 수령을 불러 소와 양을 잡아 군사를 먹이라 하니 군령의 시행이 서리 같았다. 이때 원수는 만 리 밖에 가서 공을 세웠으나 황성 소식을 어찌 알겠는가. 천자가 큰 난을 만난 줄은 모르고 선우와 남만 다섯 나라의 항복을 받은 승전 첩서를 장계로 올리고 쉬고 있었다. 하루는 생각하였다. '이제 내가 큰 공을 이루고 돌아간들 무슨 즐거움이 있으랴. 부모는 모두 돌아가시고 또 시부모와 낭군도 죽었으니 속절없이 유정한 세월을 무정하게 보내겠구나.","sp":[[3,7,"P","장애황"],[148,150,"P","천자"],[167,169,"P","남선우"]]},{"c":2,"sub":"","t":"내 이제 올라가 원수 왕희와 군량관 진태열을 죽여 원수를 갚고, 벼슬을 내놓고 깊은 규방에 들어가 다음 생에 부모와 낭군을 만나리라[?].' 또 생각하니 '낭군은 분명 물속의 외로운 넋이 되었을 것이니, 내가 이곳에서 시아버지와 낭군의 혼백을 위로하리라.' 하였다. 생각하니 쓸쓸한 마음이 저절로 났다. '위로는 황상께서 내가 여자인 줄 모르시고 장수와 군졸도 모르는데, 무슨 비계로 남이 모르게 남편의 혼백을 위로하겠는가.' 하고 혼자 깊이 생각하다가 한 꾀를 생각해 내어 중군에 분부하였다. \"내가 간밤에 꿈을 하나 얻어 전생의 일을 알았노라.","sp":[[12,14,"P","왕희"],[16,19,"P","진태열"],[20,23,"P","진태열"],[175,177,"P","천자"]]},{"c":2,"sub":"","t":"내 몸이 전생에 여자로서 낭군을 정하였는데, 그 부모가 나라에 바른말로 간하다가 소인의 참소를 만나 귀양 가던 길에 바다에서 풍파를 만나 부자가 다 물에 빠져 죽었다. 나는 혼인도 이루지 못하고 깊은 규방에서 늙어 죽었는데, 간밤에 꿈을 꾸니 그 낭군이 와서 '전생에 혼인하지 못한 정을 원수는 수고롭게 생각하지 말고, 여자 옷을 입고 수륙재를 지내 살아서와 죽어서 맺힌 원혼을 풀어 달라.' 하니 내 어찌 무심하겠는가. 수륙재를 지내면 다만 그 혼백뿐 아니라","sp":[]},{"c":2,"sub":"","t":"모든 충혼이 많으니, 내가 친히 여자 옷을 입고 영위를 차려 전생의 서러움을 풀리라.\" 하니, 장수와 군졸들이 다 신기하게 여겨 원수를 칭찬하였다. 곧 태수를 불러 제물을 갖추게 하고 강가로 나아가 십 리 모래사장에 흰 포장을 둘러치고 영위를 차리는데, 왼편에는 시랑의 영위를 차리고 오른편에는 낭군의 영위를 차렸다[?]. 모든 장수가 다 \"예로부터 처음 보는 제사다. 우리 원수는 전생의 일을 아시고 전생의 시아버지와 전생의 낭군을 생각하시니 만고에 처음이다. 원수의 신기한 재주를 누가 능히 알겠는가.\" 하며 온 군사가 다 두려워하였다.","sp":[[147,149,"P","이익"]]},{"c":2,"sub":"","t":"이때 원수가 제사 음식을 갖추어 진설하는데, 물고기는 동쪽 고기는 서쪽, 붉은 것은 동쪽 흰 것은 서쪽, 포는 왼쪽 식혜는 오른쪽으로 방위를 차려 진설하고, 지방으로 혼백을 삼고 친히 축관이 되어 제석에 나아갔다. 장수들을 나누어 보내 오방 깃발을 선명하게 하고, 좌우익장과 선봉장, 후군장을 불러 \"사방 장막 삼십 보 안에는 장수와 군졸이 들어오지 못하게 하라.\" 하였다. 갑옷과 투구를 벗어 놓고 여자 옷을 차리니 제사의 소복으로 낭자가 되었다. 축문을 손에 들고 시랑의 영위에 들어가 분향하고 두 번 절하고 예로 곡한 뒤 꿇어앉아 축문을 읽었다. \"유세차 기축년 삼월 무진삭 십오일 신사에, 효부 애황은 제사 음식을 갖추어 바다의 외로운 넋을 위로하오니 흠향하옵소서. 현고 예부시랑 이모(李某)께서는, 해와 달이 머물지 않아 문득 제삿날이 다시 이르니 길이 사모함을 이기지 못하여 삼가 맑은 술과 여러 음식으로 공경히 제사를 올리오니 흠향하소서.\" 하고 물러 나와, 〇낭군의 영위에 들어가 분향하고 두 번 절한 뒤 꿇어앉아 축문을 읽었다. 〇\"유세차 기축년 삼월 무진삭 십오일 신사에, 아내 장씨는 제사 음식을 갖추어 낭군의 바다의 외로운 넋을 위로하오니 흠향하옵소서.","sp":[[262,264,"P","이익"],[337,339,"P","장애황"],[382,384,"P","이익"]]},{"c":2,"sub":"","t":"삼가 맑은 술과 여러 음식으로 공경히 올리오니 흠향하소서.\" 축문을 다 읽은 뒤 원수가 저절로 슬퍼져 옥 같은 손으로 가슴을 두드리며 소리 높여 통곡하였다. \"인생이여, 죽으면 귀신이요 살면 사람이라[?]. 음양이 달라 저승과 이승이 길이 다르니 오시는지 안 오시는지, 가시는지 안 가시는지 능히 알지 못하여 가슴이 답답하고, 사정을 생각하니 정신이 아득하다. 옛일을 사모하니 어찌 통분하지 않겠는가. 떠다니는 부평초 같은 인생이라 인생의 부귀는 한때의 변화로다. 앞뒤 일을 생각하니 부귀도 뜻이 없고 영화도 귀하지 않다. 삼생의 가약 중한 맹세를 조물주가 시기하고 귀신이 해코지하여 아침저녁 문안의 정성도 이루지 못하고, 하늘이 맺은 인연이 끊어지고 유언이 허사가 되니 한심하다. 애황이는 제사를 받들 후손도 없으니 슬프도다.","sp":[[382,384,"P","장애황"]]},{"c":2,"sub":"","t":"봉황대 위에 봉황이 놀더니 봉황은 가고 대는 비어 강물만 절로 흐른다. 하늘 위에 놀던 봉황이 이 세상에 내려와 봉은 날아가고 황은 처졌으니, 한 몸의 부귀가 지극하다 한들 무슨 재미가 있다 하리. 바다에 뜬 해는 끝없는 정이 아니던가[?]. 맑은 달빛은 삼경의 촛불이 되어 앉은 시름이 곧 일어나고, 눈앞에 보이는 것이 모두 시름이로다. 우리 황상 나라를 다스릴 조정에서 사직의 충신이 누구이런가. 조정의 모든 백관 가운데 곧은 신하는 멀리 귀양 가고 소인의 조정이 되어 나랏일이 매우 위태로웠더니, 하늘의 때가 불행하여 남만을 평정하고 황상 앞에 들어간들 한편으로 기쁘고 한편으로 슬플 뿐이로다. 폐하 앞에 아뢰고","sp":[[193,195,"P","천자"],[302,304,"P","천자"]]},{"c":2,"sub":"","t":"우승상 왕희를 잡아내어 앞뒤 죄를 따진 뒤 일곱 자 드는 칼로 왕희 놈의 간을 꺼내 씹은 뒤에 몸은 포를 떠서 충혼당을 차리고 제사를 지낸 뒤에, 가련한 이내 신세와 앞뒤 일을 황상 앞에 아뢰고 옛 옷을 갖추어 입은 뒤 부귀영화를 다 버리고 고향에 돌아가서 남은 생을 보낼 때에, 한마음으로 정성을 들여 살아서와 죽어서 맺힌 원한을 다음 생에 다시 만나 평생 함께 즐기리라. 한마음으로 정성껏 염불하면 다음 생의 길을 닦으리라.\" 이렇듯 통곡하니 좌우의 장수와 온 군사가 눈물을 흘리며 말하였다. \"우리 원수의 장한 위풍이 부인으로 모습을 바꾸니 고운 거동과 애처로운 모습이 참으로 얌전하고 정숙한 여인이로다.\" 애원한 곡성에 푸른 하늘도 흐느끼고 강산과 물결도 서러워하며 초목과 금수도 다 서러워하는 듯하였다.","sp":[[0,3,"P","이익"],[4,6,"P","왕희"],[35,37,"P","왕희"],[99,101,"P","천자"],[293,295,"P","마고선녀"],[343,345,"P","난향"]]},{"c":2,"sub":"","t":"이때 원수가 제사를 마치고 장대에 들어가 중군에 분부하여 군졸을 먹이고 위로하게 하며, 제물을 많이 싸서 바닷속에 넣고 행군을 재촉하여 길을 떠났다. 이때 원수가 바닷가에서 수륙재를 지낸다는 소식이 자자하여 가까운 고을 백성들이 다투어 구경하였는데, 또 봉명암 중들이 구경하러 네댓 명이 짝을 지어 와서 제사 지내는 것을 구경하였다. 애원이 원수의 거동과 목소리를 듣고 저절로 슬퍼지고 명자도 또한 슬퍼져 저절로 통곡하니 슬픈 울음소리가 강가 하늘에 낭자하였다. 원수가 듣고 중군장을 불러 말하였다. \"저 어떤 사람이 우는지 자세히 알아 들이라. 울음소리가 매우 오래되었다.\" 중군장이 명을 받들고 곧 나아가 알아보니 봉명암 여승들이었다. 물었다. \"너희는 무슨 일로 와서 군중을 요란하게 하며","sp":[[187,189,"P","난향"],[189,193,"P","이대봉"],[216,218,"P","양씨"]]},{"c":2,"sub":"","t":"우느냐?\" 중들이 대답하였다. \"소승들은 본래 중이 아닙니다. 소승은 기주 장미동에 살았는데 이번 난리 중에 피란하다가 도중에 기주 모란동 이 시랑 댁 부인을 만나 서로 의지하게 되었습니다. 넓은 천지에 의탁할 곳이 없어 이름을 바꾸었는데, 부인의 법명은 명자라 하고 소비의 법명은 애원이라 합니다. 전 한림학사 장모 댁 시비 난향입니다.\" 중군장이 들어와 사연을 자세히 아뢰니, 원수가 버선발로 장대에서 뛰어내려 진문을 열고 명자와 애원을 들이라 하였다. 진중이 술렁이는 가운데 들어오니 과연 난향이 머리를 깎고 검은 장삼에 송낙을 쓰고 일곱 폭 바랑을 둘러메고 스승을 모시고 들어왔다. 원수가 난향의 손을 잡고 소리 높여 크게 우니 난향도 기절하듯 통곡하고 명자도 눈물을 흘리니 온 군사가 또한 서러워하였다.","sp":[[78,82,"P","이익"],[85,87,"P","마고선녀"],[135,137,"P","마고선녀"],[143,145,"P","양씨"],[158,160,"P","난향"],[170,172,"P","장화"],[183,185,"P","난향"],[239,241,"P","양씨"],[243,245,"P","난향"],[277,279,"P","난향"],[334,336,"P","난향"],[356,358,"P","난향"],[370,372,"P","양씨"]]},{"c":2,"sub":"","t":"부인과 난향을 위로하여 장대에 들어가 예를 마치고 앉은 뒤 대강 지난 일을 이야기하였다. 곧 분부하여 가마를 갖추어 부인과 난향을 태우고 바로 진군하여 몇 달 만에 형주에 이르렀다. 군사 오십 기에게 명하여 부인과 난향을 기주 장미동으로 모셔다 두고 오라 하고, 난향을 불러 \"곧 만나 볼 것이니 부인을 착실히 모셔라.\" 하며 애틋하게 보냈다. 장수들이 물었다. \"그들이 다 누구입니까?\" 원수가 말하였다. \"애원은 우리 집 시비요, 그 부인은 이 시랑 집 부인이다. 이번 난리에 화를 피하여 산중에 들어가 중을 만나 머리를 깎고 중이 되었다 한다. 그 집과 우리 집은 대대로 내려오는 가까운 사이이니 어찌 모시기를 소홀히 하겠는가.\" 장수와 군졸들이 다 원수가 기주에 사는 줄 알고 문벌을 짐작하니 무슨 의심이 있겠는가. 차차 길을 떠나 진군하였다.","sp":[[0,2,"P","마고선녀"],[4,6,"P","난향"],[65,67,"P","마고선녀"],[69,71,"P","난향"],[116,118,"P","마고선녀"],[120,122,"P","난향"],[147,149,"P","난향"],[166,168,"P","마고선녀"],[229,231,"P","난향"],[245,247,"P","마고선녀"],[249,253,"P","이익"],[256,258,"P","마고선녀"]]},{"c":2,"sub":"","t":"한편 황제는 두 원수의 소식이 끊어져 밤낮으로 잠자리와 식사가 편치 않으셨는데, 하루는 장 원수가 장계를 올렸다. 뜯어보시니 승전 첩서와 선우의 항서, 다섯 나라 왕의 항서를 함께 봉하고 받은 예물과 금과 비단을 바쳤다. 천자가 크게 칭찬하였다. \"원수가 한번 가서 적병을 깨뜨리고 선우를 사로잡고 또 남만 다섯 나라의 항복을 받아 이기고 온다 하였으니 원수의 공을 어찌 다 말하겠는가.\" 하시고 어서 돌아오기를 기다리시며, 또 이 원수가 오랑캐 나라에 들어간 뒤로 소식이 없음을 더욱 근심하셨다.","sp":[[3,5,"P","천자"],[49,53,"P","장애황"],[77,79,"P","남선우"],[124,126,"P","천자"],[158,160,"P","남선우"],[240,244,"P","이대봉"]]},{"c":2,"sub":"","t":"이때 이 원수가 흉노를 쫓아 서릉 땅에 이르니, 흉노가 원수가 오는 것을 보고 배를 타고 서릉도로 들어갔다. 원수도 배를 타고 곧장 쫓아 서릉에 들어가 호통 한 소리에 청룡도를 높이 들어 흉노의 목을 치니 머리가 말 아래로 떨어졌다. 적군을 호령하니 모두 항복하였다. 원수가 적군을 잡아들여 죄를 따지고 장수들은 곤장 서른 대를 쳐서 내보내니, 적진의 장수들이 원수의 인후한 덕택을 칭송하며 물러갔다. 이날 원수가 곧 길을 떠나 황성으로 향하는데, 큰 강 한가운데에 이르자 큰 바람이 일어나며 푸른 물결이 뒤집히고 풍랑이 도도하여 원수가 탄 배가 바람을 따라 정처 없이 떠갔다. 며칠 만에 한곳에 닿으니 조그마한 섬이었다. 자세히 살펴보니 괴이한 것이 있는데 온몸에 털이 나서 전신을 덮었으니 귀신도 아니고 사람도 아니었다.","sp":[[3,7,"P","이대봉"],[9,11,"P","북흉노"],[27,29,"P","북흉노"],[105,107,"P","북흉노"],[200,204,"P","이대봉"]]},{"c":2,"sub":"","t":"무엇인지 알 수 없었다. 원수가 배에서 내려 언덕에 오르니 그것이 점점 가까이 와서 곁에 앉으며 말을 하는데 목소리를 들으니 사람이었다. 원수에게 물었다. \"상공은 무슨 일로 이 험한 곳에 오셨습니까?\" 원수가 대답하였다. \"나는 중원에 사는데 흉노의 난을 만나 도적을 쫓아 서릉도에 와서 잡고 돌아가는 길에 강 위에서 풍랑을 만나 이곳에 왔소. 노인은 본래 이곳에 계셨습니까?\" 그 노인이 원수의 목소리를 듣고 흰 수염에 눈물이 비 오듯 하며 말하였다. \"나도 본래 중원 사람으로 우연히 이곳에 들어와 적적하게 고생하고 있었습니다. 이곳은 사람 없는 땅이라 사방에 사람 하나 없이 적막하고 날짐승 길짐승도 없습니다. 고국의 말소리를 들으니 어찌 반갑지 않겠습니까. 한편으로 기쁘고 한편으로 슬픕니다.\" 하며 통곡하였다. 원수도 슬퍼져 눈물을 흘리며 대답하였다. \"중원에 사셨다면 어느 땅에 사셨으며 성명은 무엇이라 하십니까?\" 노인이 대답하였다. \"나는 기주 땅 모란동에 살던 이익입니다. 나라에 바른말로 간하다가","sp":[[137,139,"P","북흉노"],[217,221,"P","이대봉"],[492,494,"P","이익"]]},{"c":2,"sub":"","t":"소인의 참소를 만나 만 리 귀양지로 부자가 함께 가다가 큰 바다 가운데서 사공 놈의 해를 입어 우리 부자가 물에 빠졌습니다. 다행히 나는 용왕이 구해 준 덕분에 살아나 이곳에 와서 산과일을 주워 먹고 죽은 물고기를 건져 먹으며 지낸 지 거의 팔 년입니다.\" 원수가 다시 물었다. \"아들을 하나 두었다 하시니 이름이 무엇입니까?\" \"자식의 이름은 대봉입니다. 열세 살에 이별하였으니 올해 스물한 살입니다.\" 대봉이 그제야 부친인 줄 분명히 알고 엎드려 통곡하였다. \"과연 소자가 대봉입니다. 아버지는 자식을 모르십니까?\" 시랑도 대봉이라는 말을 듣고 크게 놀라 얼굴빛이 변하며 달려들어 대봉의 몸을 안고 뒹굴며 통곡하였다. \"대봉아, 네가 죽어 영혼이냐, 살아 육신이냐. 이것이 꿈이냐 생시냐. 꿈이거든 깨지 말고, 혼이라도 함께 가자.\" 이렇듯 서로 붙들고 통곡하였다.","sp":[[77,79,"P","서해 용왕"],[193,195,"P","이대봉"],[227,229,"P","이대봉"],[267,269,"P","이대봉"],[291,293,"P","이익"],[295,297,"P","이대봉"],[327,329,"P","이대봉"],[349,351,"P","이대봉"]]},{"c":2,"sub":"","t":"원수가 부친을 위로하고 자세히 살펴보니 부친의 얼굴이 털 속에 은은하고 애달픈 정이 목소리에 드러나니 이것이 천륜이 아니겠는가. 원수가 말하였다. \"저도 물속에 빠졌다가 용왕이 구해 준 덕분에 살아나 백운암에 들어가 공부하고, 도사의 지휘대로 중원에 들어가 흉노군을 깨뜨리고 벼슬을 하였습니다. 흉노를 쫓아 서릉에 들어가 흉노를 잡고 가는 길에 밝은 하늘이 도우시어 우리 부자가 서로 만나니 하늘의 위엄과 신령의 도움입니다.\" 부자가 서로 앞뒤 일을 이야기하고, 시랑과 원수는 부인의 생사를 몰라 한탄하고 장 소저가 시집갔는지를 몰라 탄식하였다.","sp":[[95,97,"P","서해 용왕"],[144,146,"P","북흉노"],[165,167,"P","북흉노"],[180,182,"P","북흉노"],[259,261,"P","이익"],[267,269,"P","마고선녀"]]},{"c":2,"sub":"","t":"이때 원수가 부친을 위로하며 모시고 배를 재촉하여 중원으로 향하는데, 문득 강 위에서 푸른 옷 입은 동자 한 쌍이 작은 배를 저어 오더니 시랑과 원수에게 읍하였다. 자세히 살펴보니 한 아이는 시랑을 구하던 동자요 한 아이는 공자를 구하던 동자였다. 지난 일을 이야기하며 은혜를 크게 치하하여 수없이 사례하니, 두 동자가 두 번 절하고 말하였다. \"소동들은 우리 대왕의 명을 받아 장군을 모시러 왔습니다. 엎드려 바라건대 장군께서는 수고를 생각하지 마시고 함께 가시기를 바라니 깊이 생각해 주십시오.\"","sp":[[56,58,"P","두 동자"],[77,79,"P","이익"],[107,109,"P","이익"],[115,117,"P","두 동자"],[133,135,"P","두 동자"],[173,177,"P","두 동자"]]},{"c":2,"sub":"","t":"원수가 대답하였다. \"용왕의 덕택과 동자의 은혜는 백골이 되어도 잊기 어렵습니다. 우리 부자의 죽을 목숨이 용왕의 넓으신 덕을 입어 살았는데 어찌 수고라 하겠습니까.\" 하고 부친을 모시고 그 배에 올라 한곳에 이르니, 해와 달이 비추고 천지가 밝아 별천지요 인간 세상이 아니었다. 하늘은 높고 땅은 넓은데 단청한 누각과 높은 집들이 즐비하고, 황금 큰 글자로 '서해용궁'이라 뚜렷하게 써 붙여 있었다. 궐문에 이르니 용왕이 통천관을 쓰고 용포를 입고 마주 나와 맞는데, 수궁의 백관과 백만 비늘 갑옷 입은 무리이며 푸른 치마 붉은 치마의 시녀들이 옹위하고 나와 시랑과 원수를 맞아 옥탑에 모셨다. 예를 마친 뒤 용왕이 말하였다. \"과인이 앉아서 장군을 청하였으니 허물을 용서하소서.\"","sp":[[12,14,"P","서해 용왕"],[20,22,"P","두 동자"],[60,62,"P","서해 용왕"],[233,235,"P","서해 용왕"],[314,316,"P","이익"],[342,344,"P","서해 용왕"]]},{"c":2,"sub":"","t":"원수가 말하였다. \"소장 부자의 남은 목숨이 대왕의 은덕을 입어 보존되었으니 은혜는 백골이 되어도 잊기 어렵습니다. 만분의 일이나마 어찌 갚기를 바라던 차에 이렇게 대접하시니 도리어 감사합니다.\" 용왕이 대답하였다. \"과인이 박하여 덕이 적어 남해왕이 강병을 거느리고 지경을 범하였습니다. 원컨대 장군은 한번 수고를 아끼지 마시고 용맹을 떨쳐 형세가 궁하고 힘이 다한 과인을 생각해 주시기 바랍니다.\" 원수가 대답하였다. \"티끌 세상의 인생이 비록 힘이 있다 한들 어찌 용궁의 조화를 가진 남해 용왕을 당하겠습니까마는, 마음을 다하여 대왕의 은덕을 만분의 일이라도 갚겠습니다.\" 용왕이 크게 기뻐하여 곧 원수를 대사마 대장군에 봉하여 대장의 절월을 주었다. 원수가 곧 월각 투구에 용린갑을 입고 오추마를 비껴 타고 청룡도를 높이 들고 수궁의 정병 팔십만을 거느리고 싸움터로 나아가니, 북과 나팔과 함성은 천지를 진동하고 깃발과 창검은 해와 달을 희롱하였다.","sp":[[110,112,"P","서해 용왕"],[136,139,"P","남해왕"],[274,279,"P","남해왕"],[324,326,"P","서해 용왕"]]},{"c":2,"sub":"","t":"서해 군사를 거느리고 남해 지경에 이르니 남해왕이 이미 진을 쳐 놓았다. 격서를 전하니 싸움을 청하였다. 남해의 진을 살펴보니 군사가 진을 치고 있었다. 원수는 어진을 쳐서[?] 승부를 겨루려 하였다. 남해 용왕이 쌍 투구에 운문갑을 입고 천사검을 들고 교총마를 타고 진문에 나서며 외쳤다. \"대명의 대봉아, 너는 무슨 재주를 믿고 감히 나의 대병에 맞서려 하느냐.\" 하며 바람과 구름을 부려 원수를 에워쌌다. 원수가 육정육갑을 베풀어 남해의 진을 헤치고 금사진을 깨뜨리고 어관진으로 들어가 북을 한 번 쳐서 남해 용왕의 군사를 물리쳤다. 우레 같은 소리를 천둥같이 지르니, 월각 투구와 용린갑은 조화 속에 비쳐 있고 청룡도와 오추마는 구름과 안개 속에서 어지러우니, 남해왕이 견디지 못하여 진문을 열고 나와 항복하였다. 원수가 항서를 받아 가지고 승전고를 울리며 서해로 돌아오니, 용왕이 마주 나와 원수를 치하하고 원수의 공에 사례하며 칭송을 마지않고, 시랑도 몹시 기뻐하였다.","sp":[[23,26,"P","남해왕"],[113,118,"P","남해왕"],[168,170,"P","이대봉"],[285,290,"P","남해왕"],[374,377,"P","남해왕"],[438,440,"P","서해 용왕"],[479,481,"P","이익"]]},{"c":2,"sub":"","t":"이튿날 용왕이 태평연을 베풀고 사자에게 명하여 선관과 선녀를 청하니, 선관과 선녀와 모든 충신 열사가 일시에 들어와 동서로 나누어 앉았다. 용왕이 주인 자리에 앉은 뒤 원수의 공을 자랑하자, 원수도 일어나 예를 마친 뒤 용왕께 말하였다. \"소장은 세상 사람으로서 높은 자리에 참예하니 감격스럽습니다. 감히 묻사오니 이 자리에 계신 여러 선생의 존호를 알고 싶습니다.\" 용왕이 말하였다. \"동편의 여러 선생은 안기생, 적송자, 왕자진, 굴원이요, 서편의 여러 선녀는 항아, 직녀, 서왕모, 능옥이요, 만고의 충신 오자서와 여러 충신이요, 곁에 앉은 이는 송임[?], 마고선녀, 낙포선녀, 아황과 여영이로다.\" 백옥병을 기울여 술을 부어 서로 권하며 풍류를 벌이는데, 왕자진의 봉피리며 성연자의 거문고와 적타고, 쌍옥적과 능파사, 보허사와 우의곡, 채란곡을 곁들여 노래하니 풍류도 장하였다. 오자서는 칼춤을 추며 나랏일을 의논하고, 이태백은 술이 반쯤 취하여 접리관을 모로 쓰고 좌중에 꿇어앉아 스스로 술 속의 신선이라 일컬으니 좌중이 크게 웃었다.","sp":[[4,6,"P","서해 용왕"],[78,80,"P","서해 용왕"],[123,125,"P","서해 용왕"],[206,208,"P","서해 용왕"],[316,320,"P","마고선녀"]]},{"c":2,"sub":"","t":"아황과 여영은 남풍시를 읊조리니 소상강 저문 날에 백학이 우는 듯, 무산의 나비가 봄바람에 우는 듯하였다. 잔치를 마치고 각각 돌아가는데, 흰 노새를 탄 여동빈, 고래를 탄 이적선, 사자를 탄 갈선옹, 적송자는 구름을 타고 청학을 탄 장여는 날아 하늘로 오르는구나. 모든 선관과 선녀가 저마다 원수에게 정표를 주는데, 적송자는 옷을 주고 안기생은 대추를 주며 말하였다. \"이 과실이 비록 작으나 먹으면 빠진 이가 다시 나니 가져가소서.\"[?]","sp":[]},{"c":2,"sub":"","t":"하고, 왕자진은 단저를 주고, 굴원은 난초를 주고, 용녀는 연적을 주고, 오자서는 병서를 주고, 능옥은 옥패를 주고, 이태백은 술을 주며 \"이 병이 비록 작으나 날마다 삼백 잔을 마셔도 마르지 않으리라.\" 하고, 항아는 계수나무 꽃 한 가지를 주고, 직녀는 수건 한 채를 주고, 아황과 여영은 얼룩 대나무 한 가지를 주고 각각 작별하였다. 원수도 떠나기를 청하니 용왕이 말리지 못하여 전송하며 황금 오백 냥을 주었으나 굳이 사양하고 받지 않으니 야광주 두 개를 주었다. 받아서 행장에 간수하고 부친을 모시고 용궁을 떠나 궐문을 나오니, 용왕이 백관을 거느리고 반정까지 나와 애틋하게 작별하니 그 정은 비할 데가 없었다. 차차 길을 떠나 황성으로 올라왔다.[?]","sp":[[203,205,"P","서해 용왕"],[300,302,"P","서해 용왕"]]},{"c":2,"sub":"","t":"이때 원수가 군사를 재촉하여 몇 달 만에 황성에 이르니 황상께서 친히 백관을 거느리고 반정에서 맞으셨다. 원수가 말에서 내려 엎드리니 황제가 원수의 손을 잡고 \"먼 원정에서 큰 공을 세우고 무사히 돌아오니 다행이로다.\" 하시고 또 장수와 군졸을 위로하셨다. 대궐로 들어갈 때 위의가 장하였다. 원수는 갑옷을 단단히 여미고 봉황 같은 눈을 반쯤 뜨고 일곱 자 참사검을 비껴 들고, 장수들은 차례로 모시고, 깃발과 창검과 삼천 병마가 앞뒤로 대오를 짓고, 열 길 붉은 털 장식의 사명기는 한가운데 세워 오고, 승전고와 행군고는 원근에 진동하였다. 성 안팎의 백성들이 다투어 구경하며 친척을 찾아 부르며 나오니 참으로 장관이었다. 궐문에 이르러 군사를 진에 머무르게 하고 대궐 안으로 들어가니, 황제가 원수를 위로하여 태평연을 베풀고","sp":[[31,33,"P","천자"],[75,77,"P","천자"],[386,388,"P","천자"]]},{"c":2,"sub":"","t":"정서문에 황제가 친히 앉으시고 온 군사를 위로하셨다. \"너희가 만 리 원정에서 원수와 고생을 함께하였으니 짐이 어찌 무심하겠는가.\" 하시며 술과 고기를 많이 내리시고, 궁중 음악을 갖추어 태평곡을 부르며 원수의 공적을 칭송하며 사흘 동안 즐기셨다. 이때 이 원수가 부친을 모시고 여러 날 만에 성 아래에 이르렀다. 조정 백관과 온 군사가 놀라 바라보니, 월각 투구에 용린갑을 입고 오추마 위에 높이 앉아 청룡도를 비껴 들고 날렵하게 들어오는데 위엄이 엄숙하고 거동이 웅장하였다. 필마단창으로 오추마의 날랜 걸음이 순식간에 도성에 이르자 황제와 백관이 크게 놀라고 크게 기뻐하여 일시에 맞으니, 잔치 자리가 분주하고 장수와 군졸들이 두려워하였다.","sp":[[5,7,"P","천자"],[142,146,"P","이대봉"],[300,302,"P","천자"]]},{"c":2,"sub":"","t":"황상께서 친히 나아가시니 이 원수가 말에서 내려 엎드려 죄를 청하였다. \"신이 분수없이 무인 절도에서 죽게 된 아비를 명도 받지 않고 데리고 왔으니 죽어도 죄가 남습니다.\" 황상께서 원수의 손을 잡고 위로하셨다. \"원수는 진정하라. 짐의 밝지 못함을 너무 탓하지 말고 그 부친을 함께 모셔 짐의 부끄러움을 덜게 하라.\" 이때 이 시랑이 들어와 엎드려 통곡하였다. \"소신이 충심이 부족하여 황상을 곁에서 모시며 환난에 서로 구하지 못하였으니 어찌 신하의 도리라 하며 무슨 면목으로 황상을 뵙겠습니까.\" 황상께서 시랑의 손을 잡고 위로하시며 잔치 자리에 들어가셨다. 황상께서 전교하시어 두 원수를 칭찬하시고 문무 장수들을 봉작하시는데, 시랑을 우승상에 봉하시고 말씀하셨다. \"한나라의 소무는 북해 위에서 절개를 지키다가 십 년 만에 고향에 돌아와 한 무제를 뵈었으니, 이제 승상도 그와 같도다.\"","sp":[[0,2,"P","천자"],[14,18,"P","이대봉"],[97,99,"P","천자"],[182,186,"P","이익"],[217,219,"P","천자"],[268,270,"P","천자"],[280,282,"P","천자"],[285,287,"P","이익"],[315,317,"P","천자"],[354,356,"P","이익"],[358,361,"P","이익"],[431,433,"P","왕희"]]},{"c":2,"sub":"","t":"하시고, \"짐이 박하여 충신을 멀리 귀양 보내고 나라의 변을 만나 사직이 위태롭게 되었는데, 원수를 만나 사직을 보전하고 오랑캐 적을 깨뜨리고 짐을 환궁하게 하고, 또 오랑캐 나라에 들어가 흉노를 잡아 평정하여 짐의 근심을 없게 하니, 만고에 이런 충신은 드물 것이다.\" 하셨다. 또 두 원수를 봉작하시는데, 대봉을 병부상서 겸 대사마 대장군으로 삼아 초왕에 봉하시고, 장 원수를 예부상서 겸 연국공 연왕에 봉하셨다. 두 원수와 승상은 청량궁에 잠시 머물게 하시고, 출전한 장수들에게도 각각 봉작하여 원망이 없게 하시고 군사들도 모두","sp":[[106,108,"P","북흉노"],[173,175,"P","이대봉"],[177,181,"P","진태열"],[197,199,"P","이대봉"],[207,211,"P","장애황"],[224,226,"P","장애황"],[240,242,"P","왕희"],[261,263,"P","출전"]]},{"c":2,"sub":"","t":"각각 문서를 내리시고 부역과 잡세를 면제하셨다. 승상과 두 왕이 하늘 같은 은혜에 절하여 사례하고 천양궁으로 물러 나와, 장수와 군졸을 불러 집으로 돌아가라 하니, 성은에 감사하며 원수의 공덕을 일컬어 서로 만세를 부르고 각기 돌아갔다. 그 뒤 황상께서 큰 잔치를 베풀고 조정 백관을 모아 종일 즐기신 뒤 말씀하셨다. \"짐에게 공주가 둘 있는데, 하나는 화양공주로 나이 열여덟이요, 또 하나는 화평공주로 나이 열여섯이다. 부마를 정하고자 밤낮으로 근심하였는데, 이때를 당하여 두 왕의 사정을 보니 혼인 전이라, 화양공주를 초왕의 비로 정하고 화평공주를 연왕의 비로 정하여 짐의 뜻을 이루고자 하니 경들의 생각은 어떠한가.\" 조정이 모두 기뻐하고, 승상과 초왕은 하늘 같은 은혜에 사례하였다. \"소신이 무슨 공덕으로 봉작과 왕의 이름도 지중하온데 겸하여 공주의 부마로 정하시니 황공하고 감사합니다.\" 하며 성은에 크게 사례하였다. 연왕은 엎드려 아뢰었다. \"신은 물러가 황상께 아뢸 사정이 있으니 잠시 용서하소서.\"","sp":[[27,29,"P","왕희"],[137,139,"P","천자"],[198,202,"P","화양공주"],[220,224,"P","화평공주"],[286,290,"P","화양공주"],[292,294,"P","이대봉"],[303,307,"P","화평공주"],[309,311,"P","장애황"],[362,364,"P","왕희"],[366,368,"P","이대봉"],[464,466,"P","장애황"],[486,488,"P","천자"]]},{"c":2,"sub":"","t":"하고 처소로 물러 나와 생각하니 분기가 하늘을 찔러 울음을 참지 못하였다. 칼을 빼어 책상을 쳐서 문밖으로 내던지고 앞뒤 일을 생각하였다. '조정 대신과 같은 반열이요 내 벼슬도 지나쳐 몸에 맞지 않으니, 벼슬을 내놓고 고향에 돌아가 규방을 지키며 제사를 받들고 원수 왕희를 죽여 분을 풀고자 하였는데, 천만뜻밖에 공주의 부마를 의논하시니 나의 사정이 절박하다. 내 생각에 승상과 초왕이 시아버지와 남편인 줄 대강 짐작은 하고 있었는데, 오늘로 보니 분명한 줄 알았도다. 왕희와 진태열을 내 칼로 죽인 뒤에 사정을 아뢸까 하였더니 내가 아니라도 죽일 자가 있도다.'","sp":[[150,152,"P","왕희"],[209,211,"P","왕희"],[213,215,"P","이대봉"],[264,266,"P","왕희"],[268,271,"P","진태열"]]},{"c":2,"sub":"","t":"하고 곧 상소를 지어 임금 앞에 올렸다. 그 상소에 이렇게 쓰여 있었다. \"한림 겸 예부상서 연국공 연왕은 삼가 머리를 조아려 백 번 절하고 한 장의 글월로 폐하께 아룁니다. 신이 본래 원한이 깊어 여자로서 남자가 되어, 위로는 황상을 속이고 아래로는 백관을 속였는데 하늘 같은 은혜가 망극하여 한림의 자리에 있었습니다. 뜻밖에 외적이 강성하여 조정이 바라는 바에 따라 외람되이 상장군의 절월과 대원수의 인신을 받아 싸움터에 나아가 반적을 잡고 백성을 진무하여 돌아왔으니 이는 황상의 넓으신 덕택이옵니다. 신첩의 본래 사정을 일찍 아뢰고 벼슬을 내놓고 고향에 돌아가 규방을 지키며 세상을 마치는 날까지 제사를 받들고자 하였으나, 우승상 왕희를 죽여 원수를 갚고자 함은 이 시랑 부자가 죽은 원수와 신첩의 부모가 모두 돌아가신 것을 한탄하였기 때문입니다. 오늘로 보니 밝은 하늘이 도우시어 승상 부자가 살아 있으니 신첩의 평생 소원을 풀까 합니다. 엎드려 바라건대 황상께서는 신첩의 사정을 살피시어 초왕 대봉과 신첩으로 하여금 평생 소원을 풀고 무궁한 즐거움을 이루게 하시기를 천만 빕니다.\" 황상께서 다 보시고 크게 놀라며 크게 칭찬하셨다. \"만고에 드문 일이로다.","sp":[[42,44,"P","장화"],[56,58,"P","장애황"],[128,130,"P","천자"],[165,167,"P","장화"],[267,269,"P","천자"],[352,355,"P","이익"],[356,358,"P","왕희"],[374,378,"P","이익"],[441,443,"P","왕희"],[483,485,"P","천자"],[502,504,"P","이대봉"],[505,507,"P","이대봉"],[555,557,"P","천자"]]},{"c":2,"sub":"","t":"새 가운데 봉황이요 여자 가운데 호걸이로다. 여자의 몸으로 남자 옷으로 바꾸어 입고 입신양명하여 기둥 같은 신하로 짐을 섬기다가, 남쪽의 난을 쓸어 없애고 큰 공을 이루고 돌아오니 그 공으로 봉작을 아끼지 않았는데, 오늘 상소를 보니 충과 효를 겸하였도다.\" 하시고 곧 초왕 대봉을 들게 하여 연왕의 상소를 보라 하셨다. 승상과 초왕이 다 보고 크게 놀라고 크게 기뻐하며 아뢰었다. \"전 한림 장화와 정의가 남달라, 서로 자녀를 낳으면 장성하거든 혼례를 이루자 하였는데, 죄가 무거워 명을 받아 죽을 지경에 이르렀으므로 그사이 살았는지 죽었는지 알지 못하던 중에 어찌 또 이같이 서로 만날 줄 알았겠습니까. 오늘로 보니 이 모두 황상의 넓으신 덕택인가 합니다.\" 황상께서 말씀하셨다. \"초왕의 이름은 대봉이요 연왕의 이름은 애황이라 하니,","sp":[[151,153,"P","이대봉"],[154,156,"P","이대봉"],[164,166,"P","장애황"],[180,182,"P","왕희"],[184,186,"P","이대봉"],[217,219,"P","장화"],[220,222,"P","장화"],[352,354,"P","천자"],[371,373,"P","천자"],[384,386,"P","이대봉"],[392,394,"P","이대봉"],[397,399,"P","장애황"],[405,407,"P","장애황"]]},{"c":2,"sub":"","t":"이는 반드시 옥황상제께서 짐의 사직을 받들게 하시려고 봉작을 내리신 것이로다.\" 하시고, 예관에게 명하여 연왕의 문서와 예부상서의 문서는 거두고 다른 벼슬은 그대로 두게 하셨다. 황상께서 친히 신하에게 명하여 중매로 삼고 태사관에게 날을 받게 하여, 임금 앞에서 혼사를 주관하여 대봉과 애황의 혼례를 이루시니 위의가 찬란하였다. 침향궁을 수리하고 구름 같은 채색 장막은 하늘 높이 치고 궁 안에 교배석을 차리니, 삼천 궁녀가 모시고 조정 백관이 거느리니 이러한 위엄은 천고에 처음이었다.","sp":[[8,10,"P","천자"],[59,61,"P","장애황"],[100,102,"P","천자"],[156,158,"P","이대봉"],[160,162,"P","장애황"]]},{"c":2,"sub":"","t":"초왕이 교배석으로 나오는데, 몸에는 청룡과 해와 달을 수놓은 곤룡포를 입고 봉황을 새긴 학띠를 두르고, 머리에는 금관을 쓰고, 허리에는 원수의 인신과 상장군의 절월이며 병마대원수의 인신을 차고 교배석으로 나왔다. 또 신부가 나오는데, 칠보단장에 명월패를 차고 머리에는 금화관을 쓰고 허리에는 대원수의 인신과 병마상장군의 절월을 띠고, 채의 입은 궁녀들이 좌우로 모셨으니, 남해 관음이 바닷속에 있는 듯, 둥근 밝은 달이 부상에 뜬 듯, 달 같은 자태 꽃 같은 얼굴이 사람의 정신을 비추었다. 신랑 신부가 술잔을 나눌 때 황금 잔을 들어 마시니, 물총새와 공작이 연리지에 깃든 듯하고 원앙이 푸른 물을 만난 모습이었다.","sp":[[0,2,"P","이대봉"]]},{"c":2,"sub":"","t":"큰 예를 마친 뒤 날이 저물자 여러 대신은 각각 처소로 돌아가고 신랑 신부는 신방으로 들어가는데 수백 궁녀가 밤이 다하도록 모셨다. 신방 화촉 첫날밤에 신랑 신부가 평생의 한을 풀 터이니, 사랑스럽고 즐겁고 신기함을 어찌 다 말로 하겠는가. 원앙과 비취의 즐거움을 이루고 밤이 지나자 초왕이 곧 조복을 갖추고 대궐에 들어가 황제께 절하니 황상께서 기뻐하시며 말씀하셨다. \"짐이 경의 소회를 풀어 주었으니 경도 짐이 바라는 바를 저버리지 말라. 옛날 요임금의 딸 아황·여영 자매도 순임금 한 사람을 섬겼으니 이제 짐도 그와 같이 하리라.\" 하시고 초왕을 부마로 정하셨다. 초왕이 사양하지 못하고 물러 나와 부친께 그 연유를 아뢰니 승상이 황은에 크게 사례하였다. 또 장 부인이 시아버지께 예로 절하니","sp":[[159,161,"P","이대봉"],[181,183,"P","천자"],[189,191,"P","천자"],[305,307,"P","이대봉"],[319,321,"P","이대봉"],[352,354,"P","왕희"],[372,376,"P","장애황"]]},{"c":2,"sub":"","t":"승상이 한편으로 기쁘고 한편으로 슬퍼하며 지난 일을 이야기하였다. 장 부인이 아뢰었다. \"전날 바닷가에서 수륙재를 지낸 일이며, 시어머님을 모셔다가 장미동 시비 난향과 함께 계시게 한 사연을 아룁니다.\" 승상이 크게 놀라고 크게 기뻐하며 말하였다. \"이러한 일은 고금에 없는 일이다.\" 하고 곧 초왕을 불러 사연을 말하니 초왕이 부인에게 사례하였다. 그날로 금등과 옥교를 갖추고 침향궁 노비를 재촉하며 임금 앞에 들어가 이 뜻을 아뢴 뒤, 초왕 부부가 기주 장미동으로 떠나 며칠 만에 이르렀다. 사당에 절하여 뵙고 모친을 모시니, 서로 그리던 말이며 정다운 마음을 어찌 다 말로 하며, 장 부인이 몹시 서러워한 것을 어찌 다 기록하겠는가. 장 한림 댁 사당을 모시고 집안 식구를 거느리고 황성으로 올라와 황상을 뵐 때, 부인이 승상을 살펴보니 털이 수북하여 알아보기 어려웠다.","sp":[[0,2,"P","왕희"],[37,41,"P","장애황"],[90,92,"P","난향"],[114,116,"P","왕희"],[165,167,"P","이대봉"],[180,182,"P","이대봉"],[184,186,"P","마고선녀"],[246,248,"P","이대봉"],[328,332,"P","장애황"],[358,362,"P","장화"],[394,396,"P","천자"],[403,405,"P","마고선녀"],[407,409,"P","왕희"]]},{"c":2,"sub":"","t":"승상은 \"부인이 머리를 깎았으니 알아보기 어렵구려.\" 하며 서로 한편으로 기쁘고 한편으로 슬퍼하니 그 모습은 한 입으로 다 말하기 어려웠다. 이때 황제가 이 사연을 들으시고 승상을 초국 태왕에 봉하시고 그 부인을 정렬왕비에 봉하시며 보화를 많이 내리시니, 성은에 감사하여 머리를 조아려 사례하고 물러 나왔다. 각기 처소를 정하시는데, 태왕과 정렬왕비는 숭예궁에 머물게 하시고, 초왕과 충렬왕후는 침향궁에 머물되 시녀 백 명이 모시게 하시고 많은 녹봉을 주셨다. 또 부친 태상왕은 친국문후에 봉하시어 많은 녹봉을 받게 하시니 초왕의 부귀가 천하의 으뜸이었다. 이때 우승상 왕희는 초왕이 오랑캐 나라로 갈 때 옥에 가두어 두었는데, 그사이 일이 번거로워[?]","sp":[[0,2,"P","왕희"],[5,7,"P","마고선녀"],[82,84,"P","천자"],[97,99,"P","왕희"],[104,106,"P","이익"],[115,117,"P","마고선녀"],[119,123,"P","양씨"],[187,189,"P","이익"],[191,195,"P","양씨"],[211,213,"P","이대봉"],[215,219,"P","장애황"],[263,266,"P","이익"],[268,272,"P","이익"],[293,295,"P","이대봉"],[315,318,"P","이익"],[319,321,"P","왕희"],[323,325,"P","이대봉"]]},{"c":2,"sub":"","t":"죄를 다스리지 못하였다. 초왕과 태상이 정서문에 나와 앉아 왕희를 잡아내어 앞뒤 죄목을 물은 뒤, 사공 십여 명을 잡아들여 낱낱이 죄를 따지고 장안 큰길에서 외쳤다. \"소신 왕희가 충신을 모해하여 귀양지로 보낼 때 황명으로 가는 몸을 사공 놈들과 함께 꾀하여 금은을 많이 주고 만경창파 깊은 물에 부자를 한꺼번에 묶어 물속에 넣으라 하니, 무지한 필부들이 금은만 생각하고 인의를 몰랐으니 살기를 바라겠느냐. 하늘의 명이 온전하여 초왕 부자가 살아나 많은 녹봉을 받거니와, 무지한 뱃사람 놈들의 용납하지 못할 죄를 생각하며 지체하지 말라.\" 하고 망나니를 호령하여 장안 큰길에서 처참하였다. 왕희를 섬돌 아래 다시 꿇리고 초왕이 청룡도를 들고 왕희에게 말하였다. \"네 목을 베어야 할 것이로되 황상의 넓으신 성덕을 생각하여 너도 우리 부자처럼 멀리 귀양 보내니 황상의 은덕을 죽은 귀신이 되어도 잊지 말라.\" 하고 이 뜻을 황제께 아뢰니 황상께서 초왕의 어질고 착함을 칭찬하셨다.[?]","sp":[[14,16,"P","이대봉"],[33,35,"P","왕희"],[97,99,"P","왕희"],[240,242,"P","이대봉"],[330,332,"P","왕희"],[347,349,"P","이대봉"],[359,361,"P","왕희"],[387,389,"P","천자"],[425,427,"P","천자"],[460,462,"P","천자"],[468,470,"P","천자"],[473,475,"P","이대봉"]]},{"c":2,"sub":"","t":"왕희 부자를 절도에 귀양 보내 가두었다. 또 장 원수가 출전할 때 병부상서 진태열을 군량관으로 삼았는데, 그는 스스로 죄를 알고 병석에 누워 일어나지 않았다. 군졸을 호령하여 태열을 잡아들여 죄를 따졌다. \"너는 전날 병부상서의 자리에 있으면서 우승상 왕희 놈과 한패가 되어 나랏일을 어지럽히고 충신을 멀리 귀양 보내고, 소인이 때를 만나게 하여 이간으로 황상의 성덕을 가리고 포악으로 충신을 모함하여 죽였다. 난세를 당하여서는 사직을 보전하지 못하였으니 네 전날의 충심은 다 어디로 갔느냐.\" 태열이 대답하였다. \"소신은 전날 지은 죄가 적지 않으나 장 원수를 모시고 만 리 원정에서 고생한 사정이 있으니 엎드려 바라건대 초왕은 용서하소서.\"","sp":[[0,2,"P","왕희"],[25,29,"P","장애황"],[31,33,"P","출전"],[37,41,"P","진태열"],[42,45,"P","진태열"],[47,50,"P","진태열"],[122,126,"P","진태열"],[137,140,"P","이익"],[141,143,"P","왕희"],[199,201,"P","천자"],[309,313,"P","장애황"],[349,351,"P","이대봉"]]},{"c":2,"sub":"","t":"초왕이 크게 꾸짖었다. \"너희 진가 놈들을 조정에 둘 수 없다.\" 하시며 \"전날 난리 때 네 사촌 병부시랑 진여 놈도 황상을 재촉하여 흉노에게 항서를 올리라 하였으니 이 역시 반적의 무리다. 너희를 당장 처참할 것이로되 황상의 넓으신 성덕을 생각하여 먼 곳으로 귀양 보내니 빨리 귀양지로 가라.\" 하고 진여를 잡아들여 태열과 함께 귀양 보내니, 조정 백관이며 백성이 모두 초왕의 성덕을 칭송하지 않는 이가 없었다. 이때 황상께서 초왕의 정사를 보시고 \"어찌 아름답지 않은가.\" 하시고 두 공주의 부마를 정하시는데, 일관에게 날을 받게 하니 봄 3월 보름이었다. 궁 안에 큰 잔치를 베풀고 초왕과 혼례를 이루신다 하니 장후가 몹시 기뻐하였다.","sp":[[0,2,"P","이대봉"],[55,59,"P","진태열"],[60,62,"P","진여"],[66,68,"P","천자"],[75,77,"P","북흉노"],[123,125,"P","천자"],[169,171,"P","진여"],[208,210,"P","이대봉"],[235,237,"P","천자"],[240,242,"P","이대봉"],[329,331,"P","이대봉"],[345,347,"P","장애황"]]},{"c":2,"sub":"","t":"길일이 되자 초왕은 금포에 옥띠, 용문포를 두르고 금관 조복으로 교배석에 나아가고, 두 공주는 초록 저고리 붉은 치마의 채색 단장에 명월 옥패를 차고 삼천 궁녀가 옹위하여 나오는데, 그 모습은 북두칠성의 좌보·우필이 나뉘어 선 듯하였다. 비단옷과 꽃 같은 복색은 햇빛을 희롱하고 두 공주의 꽃 같은 얼굴 달 같은 자태는 원근에 비치는구나. 황금 잔을 들어 큰 예를 마친 뒤 해가 함지에 지고 황혼이 되어 자는 새가 숲에 들 때, 신방 화촉에 원앙금침과 비취의 즐거움을 이루니 이 또한 하늘이 정한 인연인가 하노라. 이때 황제가 초왕을 부르시어 말씀하셨다. \"경은 이제 짐의 부마요 또 초왕이 된 지 오래니, 어찌 남의 나라 임금이 되어 오래도록 짐의 곁을 떠나지 않겠는가.\" 하시고 \"곧 행차를 차려 초국에 들어가 백성의 정사를 살펴 만세에 전하라.\" 하셨다. 그날로 두 공주의 행차를 차리는데, 화양공주를 숙렬왕비에 봉하시고 화평공주를 전안왕비에 봉하시며 금과 비단과 채단을 많이 내리셨다. 황제와 황후가 몹시 애틋해하시며 십 리 밖까지 나와 전송하시고 봄가을로 조회하라 하시니, 초왕과 태상왕이 머리를 조아려 은혜에 사례하고 초국으로 향하였다. 기주에 내려가 양가 선산에 성묘하고 떠날 때 충렬왕후가 초왕에게 아뢰었다.","sp":[[7,9,"P","이대봉"],[291,293,"P","천자"],[295,297,"P","이대봉"],[327,329,"P","이대봉"],[446,450,"P","화양공주"],[452,456,"P","화양공주"],[463,467,"P","화평공주"],[469,473,"P","화평공주"],[500,502,"P","천자"],[550,552,"P","이대봉"],[554,557,"P","이익"],[612,616,"P","장애황"],[618,620,"P","이대봉"]]},{"c":2,"sub":"","t":"\"전날 신첩이 화를 피하다가 여남 최 어사 집 부인을 만나 삼 년을 보살펴 주고 사랑하시던 사정과, 소저와 혼인을 의논하시던 말씀\"을 낱낱이 아뢰니, 초왕이 듣고 몹시 기뻐하며 최 어사 댁에 미리 기별을 놓고 부인과 함께 들어가니, 황황히 분주한 가운데 몹시 반가워하셨다. 앞뒤 일을 이야기하고 초왕이 최 소저와 길일을 가려 혼례를 이루니 이 또한 하늘이 정한 인연이었다. 원앙의 즐거움을 이룬 뒤 며칠 머물러 그 선산에 성묘하고 하직하고, 어사 댁 식구를 수습하여 여러 날 만에 초국에 이르니, 조정 백관이며 장수와 군졸이 반정에 나와 맞아 궁중으로 들어가 각기 처소를 정하였다. 최씨가 태상왕과 태상왕비께 뵈니 몹시 사랑하시고, 두 공주께 뵈니 또한 사랑하였다.","sp":[[26,28,"P","마고선녀"],[84,86,"P","이대봉"],[117,119,"P","마고선녀"],[165,167,"P","이대봉"],[169,173,"P","최 소저"],[326,328,"P","최 소저"],[330,333,"P","이익"],[335,338,"P","이익"]]},{"c":2,"sub":"","t":"초왕이 정전에 나와 앉아 군신의 조회를 받은 뒤 나랏일을 의논하는데, 도총장을 불러 물었다. \"군병이 얼마나 되느냐?\" 아뢰었다. \"갑병이 삼십만, 정병이 사십만, 철기가 삼십만, 궁노군이 이십만이니 합하면 일백이십만이나 됩니다.\" 또 물었다. \"군량과 염초는 어떠하냐?\" \"흰쌀이 팔백만 석이요 소금이 오백만 석이요 말먹이 풀은 아홉 산같이 쌓였습니다.\" 또 물었다. \"초국의 땅은 얼마나 되느냐?\" \"하남이 삼십여 성, 하북이 삼십여 성, 하서가 오십여 성, 강동이 사십여 성이니 합하면 일백오십여 성입니다.\" \"장수는 얼마나 있느냐?\" \"지혜가 넉넉하고 재주가 남보다 뛰어난 자가 백여 명이고 그 나머지가 수백 명입니다.\" \"성명을 올리라.\" 하시니 곧 명록을 들였다. 보니 추종, 형종수, 한선, 백기, 오인 등 십여 명이요, 이정, 곽희, 정순, 장담, 왕주 등 이십여 명이요, 그 나머지 장수가 백여 명이었다. 모두 각기 군사를 거느리고 조련을 연습하게 하고 군호를 엄숙히 하니 두려워하지 않는 이가 없었다.","sp":[[0,2,"P","이대봉"]]},{"c":2,"sub":"","t":"백성을 다스리는 정사를 덕화로 꾀하니 온 나라가 무사하여 마을마다 백성은 격양가를 부르며 산호만세를 부르고, 해마다 풍년이 들고 비와 바람이 순조로웠다. 이때 부국강병의 권세를 가졌으며 나라 안이 태평하여 만민이 칭송하였다. 이때 충렬왕후가 왕께 아뢰었다. \"난향의 공이 적지 않으니 대왕은 깊이 생각하소서.\" 왕이 깨닫고 후궁으로 삼아 충렬왕비와 함께 머물게 하니 네 아내와 첩 하나를 두었다. 충렬왕비는 아직 태기가 없고 두 공주는 각각 아들을 낳고 최 부인도 아들 하나를 낳았다. 충렬왕후가 태기가 없음을 초왕이 한탄하고 태상과 태후도 민망히 여겼다.[?]","sp":[[129,133,"P","장애황"],[145,147,"P","난향"],[181,183,"P","난향"],[254,258,"P","최 소저"],[272,276,"P","장애황"],[286,288,"P","이대봉"],[299,301,"P","양씨"]]},{"c":2,"sub":"","t":"이때는 대명 성화 임진년 정월 보름이었다. 천자가 여러 신하를 모아 즐기시며 태평을 생각하고 \"초왕 부부의 큰 공이 하늘 같고 바다 같다.\" 하시며 종일 취하도록 즐기셨다. 문득 정남 절도사 정비가 상소를 올렸다. 뜯어보니 이렇게 쓰여 있었다. \"남선우가 또 분을 이기지 못하여 남만 다섯 나라와 합세하여 장수 백여 명과 정병 철기 오백만을 일으켜 지경을 범하여 백성을 수없이 죽이고 물밀듯 들어오니 엎드려 바라건대 폐하께서는 급히 막으소서.\" 다 보시고 크게 놀라 여러 신하를 돌아보시니 여러 신하가 함께 아뢰었다. \"형세가 위급하니 급히 초왕 대봉을 부르소서.\"","sp":[[24,26,"P","천자"],[53,55,"P","이대봉"],[138,141,"P","남선우"],[303,305,"P","이대봉"],[306,308,"P","이대봉"]]},{"c":2,"sub":"","t":"황상께서 곧 부르시려 할 때 또 하북 절도사 최선이 장계를 올렸다. 뜯어보시니 이렇게 쓰여 있었다. \"북흉노가 죽은 뒤로 그 아들 삼형제가 군사를 조련하여 밤낮으로 연습하고, 토번·가달과 흉노 묵특이 한마음으로 함께 꾀하여 장수 천여 명과 군사 팔십만이라 하오나 그 수를 알 수 없습니다.\" 황상께서 다 보시고 크게 놀라 얼굴빛을 잃고 말씀하셨다. \"이 일을 어찌하랴. 남북의 적병이 다시 딴마음을 품으니, 전날은 장해운을 썼지만 이제는 규방에 들어갔으니 한편은 대봉을 보내겠으나 또 한편은 누구로 하여금 막게 하겠는가. 짐의 덕이 없어 도적이 자주 일어나니 초왕 대봉이 공을 이루고 돌아오면 이번에는 천자의 자리를 대봉에게 전하리라.\" 하시며 눈물을 흘리시니 여러 신하가 간하였다. \"용의 눈물이 땅에 떨어지면 삼 년 가문다 하니 너무 서러워하지 마소서.","sp":[[0,2,"P","천자"],[57,60,"P","북흉노"],[105,107,"P","북흉노"],[108,110,"P","묵특"],[163,165,"P","천자"],[232,235,"P","장애황"],[259,261,"P","이대봉"],[313,315,"P","이대봉"],[316,318,"P","이대봉"],[337,339,"P","천자"],[345,347,"P","이대봉"]]},{"c":2,"sub":"","t":"초왕만 부르시면 그 초왕후는 본래 충효를 갖춘 사람이라 앉아 있지 않을 것입니다.\" 황상께서 곧 부르시니, 초왕이 전교를 보고 크게 놀라 온 나라가 소동하였다. 나랏일을 태상왕께 미루고 용포를 벗고 월각 투구에 용린갑을 여미고 청룡도를 비껴 들고 오추마를 채찍질하여 그날로 황성에 이르러 섬돌 아래 엎드렸다. 황상께서 초왕의 손을 잡고 나랏일이 위태로움을 말씀하시니 초왕이 아뢰었다. \"저들이 비록 남북의 강병이 억만이나 조금도 근심하지 마소서.\"","sp":[[0,2,"P","이대봉"],[11,13,"P","이대봉"],[47,49,"P","천자"],[60,62,"P","이대봉"],[95,98,"P","이익"],[173,175,"P","천자"],[178,180,"P","이대봉"],[205,207,"P","이대봉"]]},{"c":2,"sub":"","t":"하고 곧 사자에게 명하여 충렬왕후에게 사연을 알리니, 장후가 사연을 보고 크게 놀라 화려한 옷을 벗고 전날 입던 갑옷과 투구를 갖추고 참사검을 들고 천리준총을 타고, 태상과 태후, 두 공주며 최 부인과 후궁에게 다 하직하고 준총을 채찍질하여 황성에 이르니 황제와 초왕이 성 밖에 나와 맞았다. 말에서 내려 엎드려 아뢰었다. \"초왕 부부의 정성이 부족하여 자주 외적이 강성한가 합니다.\" 황상께서 그 충성을 크게 칭찬하시고 적을 막을 일을 의논하시니 장후가 아뢰었다. \"황상의 덕택이 유독 초왕 부부에게\" 나랏일을 태상왕께 미루고 용포를 벗고 월각 투구와 용린갑을 여미고 청룡도를 비껴 들고 오추마를 채찍질하여 그날로 황성에 이르러 섬돌 아래 엎드리니, 황상께서 초왕의 손을 잡고 나랏일이 위태로움을 말씀하셨다. 초왕이 아뢰었다. \"저들이 비록 남북의 강병이 억만이나 조금도 근심하지 마소서.\"","sp":[[14,18,"P","장애황"],[30,32,"P","장애황"],[97,99,"P","양씨"],[107,111,"P","최 소저"],[113,115,"P","난향"],[143,145,"P","천자"],[147,149,"P","이대봉"],[182,184,"P","이대봉"],[216,218,"P","천자"],[251,253,"P","장애황"],[262,264,"P","천자"],[273,275,"P","이대봉"],[287,290,"P","이익"],[365,367,"P","천자"],[370,372,"P","이대봉"],[398,400,"P","이대봉"]]},{"c":2,"sub":"","t":"하니 곧 사자에게 명하여 충렬왕후에게 사연을 알렸다. 장계를 보고 크게 놀라 화려한 옷을 벗고 전날 입던 갑옷과 투구를 갖추고 □을 들고[?] 천리준총을 타고, 태상과 태후, 두 공주며 최 부인과 후궁에게 다 하직하고 준총을 채찍질하여 황성에 이르니 황제와 초왕이 성 밖에 나와 맞았다. 말에서 내려 엎드려 아뢰었다. \"초왕 부부의 정성이 부족하여 자주 외적이 강성한가 합니다.\" 황상께서 그 충성을 크게 칭찬하시고 적을 막을 일을 의논하시니 장후가 아뢰었다. \"황상의 덕택이 유독 초왕 부부에게 미쳤으니, 불행하여 싸움터에 나가 죽은들 어찌 무심하겠습니까. 엎드려 바라건대 황상께서는 근심하지 마소서.\"","sp":[[14,18,"P","장애황"],[94,96,"P","양씨"],[104,108,"P","최 소저"],[110,112,"P","난향"],[140,142,"P","천자"],[144,146,"P","이대봉"],[179,181,"P","이대봉"],[213,215,"P","천자"],[248,250,"P","장애황"],[259,261,"P","천자"],[270,272,"P","이대봉"],[322,324,"P","천자"]]},{"c":2,"sub":"","t":"하고 군병을 일으키는데, 장후를 대원수 대사마 대장군 겸 병마도총독 장군에 봉하시고 인검과 절월을 주시며 \"군중에 만일 태만한 자가 있거든 곧 베라.\" 하시고, 연왕을 대원수 겸 상장군에 봉하시고[?] 군병을 일으키셨다. 장 원수는 황성의 군사를 일으키고 이 원수는 중국의 군사를 일으켜 두 원수가 각각 군병 팔십만씩 거느려 진군하는데, 대봉은 북흉노를 치러 가고 애황은 남선우를 치러 갔다. 이때 애황이 아이를 밴 지 일곱 달이었다. 각각 말을 타고 대봉이 애황의 손을 잡고 말하였다. \"원수가 아이를 밴 지 일곱 달이라 배 속의 핏덩이를 보전하기를 어찌 바라겠소. 부디 몸을 보전하여 무사히 돌아와 다시 만나기를 천만 바라오.\" 하며 애틋한 정을 이기지 못하였다. 또 애황이 말하였다. \"원수는 첩을 생각하지 마시고 대군을 거느려 한번 북을 쳐 도적을 깨뜨리고 빨리 돌아와 황상의 근심을 덜고 태상과 태황의 근심을 덜게 하소서.\" 말 위에서 서로 나뉘어 이별하고 대봉은 북으로 가고 애황은 남으로 가서 진군하였다.","sp":[[14,16,"P","장애황"],[90,92,"P","장애황"],[124,128,"P","장애황"],[143,147,"P","이대봉"],[189,191,"P","이대봉"],[193,196,"P","북흉노"],[204,206,"P","장애황"],[208,211,"P","남선우"],[223,225,"P","장애황"],[253,255,"P","이대봉"],[257,259,"P","장애황"],[376,378,"P","장애황"],[435,437,"P","천자"],[485,487,"P","이대봉"],[496,498,"P","장애황"]]},{"c":2,"sub":"","t":"이때 남선우는 대병을 거느리고 진남관에 웅거하여 황성의 대군을 기다리고 있었다. 장 원수가 수십 일 만에 진남에 이르니 진남관 수문장이 아뢰었다. \"적병이 엄장하니 원수께서는 가볍게 대적하지 마소서.\" 원수가 남관 오 리 밖에 진을 치고 격서를 보내 싸움을 돋우었다. 선우가 선봉장 골통에게 명하여 원수를 대적하라 하니 골통이 명을 받들고 맞섰다. 원수는 전날 출전하였던 장수들을 거느리고 갔으므로 그대로 군호를 삼고 응하여 말을 타고 나가는데, 백금 투구에 흑운포를 입고 일곱 자 참사검을 높이 들고 천리준총을 비껴 타고 적진으로 달려들며 남주작, 북현무와 청룡, 백호를 호령하여 적진의 후군을 마구 쳤다. 원수는 선봉장 골통을 맞아 싸워 반 합도 못 되어 원수의 칼이 공중에 빛나며 골통의 머리를 베어 들고 좌충우돌하니, 전날 쓰던 용맹을 오늘 시험하매 기력이 배나 더하였다. 큰 싸움 삼십여 합에 팔십만 대병을 몰아치니 선우도 당하지 못할 줄 알고 군사를 거느리고 달아나려 하였다. 적군을 썩은 풀 베듯 하니 군사의 주검이 무덤 같고 피가 흘러 내를 이루니 누가 겁내지 않겠는가. 적진 장졸이 원수의 용맹을 보고 물결 헤어지듯 흩어졌다.","sp":[[3,6,"P","남선우"],[45,49,"P","장애황"],[150,152,"P","남선우"],[158,160,"P","골통"],[179,181,"P","골통"],[202,204,"P","출전"],[349,351,"P","골통"],[384,386,"P","골통"],[462,464,"P","남선우"],[557,561,"P","이대봉"]]},{"c":2,"sub":"","t":"선우가 죽기로 달아나는데 원수의 호통 한 소리에 칼빛이 번뜩이더니 선우가 몸을 뒤집으며 말에서 떨어졌다. 선우의 목을 함에 넣어 남만 다섯 나라에 보내고, 남은 적진 장졸은 장수들을 호령하여 씨도 없이 다 죽이고 백만 군을 진무하였다. 이때 다섯 나라 왕이 선우의 목을 보고 금과 비단과 채단을 수레에 싣고 항서를 올리며 죽기로 사죄하였다. 원수가 다섯 나라 왕을 잡아들여 죄를 따지고 항서와 예물을 받으며 \"이 뒤에 만일 반심을 두면 너희 다섯 나라의 씨를 없앨 것이니 물러가 동지 조공을 지체하지 말라.\" 하니, 저마다 애걸하고 허물을 선우에게 돌리며 머리를 조아려 사례하고 돌아갔다. 원수가 군사를 수습하여 관 위에서 군사를 먹이고 위로하고, 예물을 싣고 차차 길을 떠나 황성으로 올라오다가 하양에 들어섰을 때 몸이 고단하여 영채를 세우고 쉬던 차에 가슴과 배가 몹시 아프더니, 혼미한 가운데 아이를 낳으니 활달한 사내아이였다. 사흘 동안 몸조리하고 말을 타지 못하므로 수레를 타고 진군하였다.","sp":[[0,2,"P","남선우"],[37,39,"P","남선우"],[59,61,"P","남선우"],[144,146,"P","남선우"],[302,304,"P","남선우"]]},{"c":2,"sub":"","t":"이때 대봉이 군사 팔십만으로 북쪽 땅에 이르니 흉노의 대병이 태산을 등지고 진을 치고 있었다. 원수가 백 리 평사에 진을 치고 필마단검으로 오랑캐 진에 달려들어 우레 같은 소리를 천둥같이 지르며, 동쪽에 번뜻 서쪽 장수를 베고, 남쪽에 번뜻 북쪽 장수를 베고, 서쪽으로 가는 듯 동쪽 장수를 베고, 동쪽으로 가는 듯 서쪽 장수를 베며 좌충우돌 거침없이 다니니, 군사와 장수가 넋을 잃어 허둥댈 때 서로 밟혀 죽는 자가 태반이었다. 오추마가 달리는 곳에 청룡도가 번뜩이며 순식간에 무찌르고 이름 없는 장수 팔십여 명을 베고 초국의 대병으로 마구 치니, 원수의 재주는 천신 같고 달리는 말은 나는 용이었다. 흉노의 백만 대병이 일시에 흩어지니 흉노가 당하지 못하여 군사를 거느리고 달아나려 하였으나, 좌우의 복병이 벌여 서 있어 갈 곳이 없었다. 몹시 다급하던 차에 호통 한 소리에 청룡도가 번뜩이며 흉노의 머리를 베어 들고 적군을 호령하니, 바람만 보고도 겁에 질려 일시에 항복하였다. 장수는 곤장 서른 대를 치되 모두 패군의 장수라 하여 쳐서 내보내고, 군사는 낱낱이 곤장 서른 대씩 쳐서 물리치니, 원수의 은덕을 빌며 살아 돌아감을 사례하였다.[?]","sp":[[3,5,"P","이대봉"],[26,28,"P","북흉노"],[338,340,"P","북흉노"],[358,360,"P","북흉노"],[446,448,"P","북흉노"]]},{"c":2,"sub":"","t":"원수가 흉노의 목을 토번과 가달국으로 보내며 말하였다. \"너희가 하늘의 때를 모르고 하늘의 위엄을 범하였으니 만일 항복하지 않으면 이같이 죽여 천하를 평정할 것이니 빨리 항복하라.\" 격서와 함께 봉하여 보내니, 토번과 가달이 원수의 용맹을 소문으로 듣고 겁에 질려 일시에 항복하였다. 항서와 예물을 갖추고 사신을 보내 사죄하자, 바친 예물을 수레에 싣고 항서를 받으며 사신을 잡아들여 죄를 따진 뒤 \"만일 다시 죄를 범하면 토번과 가달의 씨를 멸할 것이니 해마다 조공을 동지사 편에 바치라. 만일 태만하면 죄를 면하지 못하리라.\" 하고 내보내니 명을 받들고 돌아갔다. 창고의 곡식을 풀어 백성을 구휼하고 돌아오는데, 원수의 마음이 심란하여 군사를 먹이고 위로한 뒤 장수들을 불러 말하였다. \"군사를 거느리고 오라. 나는 급히 가서 장후의 생사를 알아보겠다.\"","sp":[[4,6,"P","북흉노"],[124,128,"P","이대봉"],[409,411,"P","장애황"]]},{"c":2,"sub":"","t":"하며 말을 재촉하여 밤낮으로 길을 배로 달려 황성으로 갔다. 팔십 일에 갔던 길을 너댓새 만에 이르러 황상께 뵈니, 황상께서 크게 놀라고 크게 기뻐하시며 \"원수가 홀로 오니 무슨 까닭인가?\" 하셨다. 대봉이 엎드려 앞뒤 사정을 아뢰고 곧 길을 떠나 남쪽으로 가는데, 며칠 만에 남주 땅에 이르니 장 원수가 군사를 거느리고 돌아오고 있었다. 진 앞에 나아가 두 원수가 서로 공을 치하하고 몹시 반가워하였다. 아기를 살펴보니 영웅호걸의 상이라 초왕과 장 원수가 크게 기뻐하며 행군을 재촉하여 황성에 이르니, 또 초국 병마도 당도하였다. 합세하여 두 원수가 함께 들어가니 황상께서 조정 백관을 거느리고 맞으며 원수와 장수와 군졸을 위로하셨다. 두 원수가 대궐에 들어가니 황후가 두 원수의 손을 잡고 칭찬을 마지않으시고, 황제와 황후와 조정 백관이 장후가 해산한 것을 보고 더욱 칭찬하였다.","sp":[[57,59,"P","천자"],[65,67,"P","천자"],[112,114,"P","이대봉"],[165,169,"P","장애황"],[246,248,"P","이대봉"],[250,254,"P","장애황"],[317,319,"P","천자"],[400,402,"P","천자"],[415,417,"P","장애황"]]},{"c":2,"sub":"","t":"\"만고 이후로 이런 충성은 없도다. 두 원수가 한번 가서 흉적을 깨뜨리고 돌아와 짐의 근심을 덜고 사해를 태평하게 하니 두 원수의 공덕은 하늘 같고 바다 같다.\" 하시고, 장후가 군중에서 낳은 아이의 이름을 출전이라 하시고 금은을 많이 내리셨다. 태평연을 베풀어 초왕 내외의 공덕을 일컫고 만세를 부르며, 장수들은 벼슬을 올리고 군사는 상을 많이 주시니 하나도 원망이 없고 하늘 같은 은혜에 감사하며 각기 집으로 돌아갔다. 이때 초왕과 장 원수가 천자 앞에 하직하고 군사를 거느리고 초국에 이르니, 태상과 왕비들이 반정에 나와 왕을 돌아보며 장후를 치하하고 아기를 받들었다. 그 충성과 공덕이며 용맹을 온 나라가 칭송하였다. 궁 안에 큰 잔치를 베풀고 며칠을 즐긴 뒤 장수와 군졸을 각각 집으로 돌아가게 하니 성은에 감사하며 돌아갔다.","sp":[[96,98,"P","장애황"],[116,118,"P","출전"],[147,149,"P","이대봉"],[240,242,"P","이대봉"],[244,248,"P","장애황"],[250,252,"P","천자"],[303,305,"P","장애황"]]},{"c":2,"sub":"","t":"초왕의 덕과 장후의 덕화가 사해를 덮으니 천하가 태평하고, 성스러운 자손은 대대로 이어져 만세에 전하였다. 장후가 아들 셋과 딸 둘을 낳으니 모두 풍채가 영웅이어서 그 부모를 닮았다. 둘째 아들 형제를 황제께 아뢰어 장씨로 성을 내려 장씨의 제사를 받들게 하고, 황성에 돌아가 살게 하여 공후장상으로 많은 녹봉을 먹고 대대로 장씨 가문이 끊이지 않았다. 천자도 태평성대로 만세토록 무궁하시고 초왕도 대대로 이어져 만세에 전하니, 근심 없이 지낼 것이 사람 밖에 없으리라[?]. 사람이 생기거든 임금께 충성하는 본을 받아 이름을 천추에 전할지어다. 천천만만세토록 무궁하옵소서.","sp":[[0,2,"P","이대봉"],[7,9,"P","장애황"],[60,62,"P","장애황"],[113,115,"P","천자"],[198,200,"P","천자"],[219,221,"P","이대봉"]]}]});
